109	static void bk7258_cpu2_fpu_initialize(void)
110	{
111	  /* Match the primary AP core before CPU2 can enter exception_common. */
112	
113	  BK7258_SCB_CPACR &= ~((3u << 20) | (3u << 22));
114	  __asm volatile ("dsb sy; isb sy" ::: "memory");
115	  BK7258_FPU_FPCCR &= ~((1u << 31) | (1u << 30) | (1u << 29));
116	  BK7258_SCB_CPACR |= ((3u << 20) | (3u << 22));
117	  __asm volatile ("dsb sy; isb sy" ::: "memory");
118	}
