142	static int bk7258_cpu2_wait(uint32_t wanted, uint32_t timeout_ms)
143	{
144	  volatile struct bk7258_cpu2_probe_state_s *state =
145	    bk7258_cpu2_probe_state();
146	  uint32_t current;
147	  uint32_t elapsed;
148	
149	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
150	    {
151	      current = state->state;
152	      __asm volatile ("dmb sy" ::: "memory");
153	      if (current == wanted)
154	        {
155	          return OK;
156	        }
157	
158	      if (current == BK7258_CPU2_PROBE_STATE_FAILED)
159	        {
160	          return -EIO;
161	        }
162	
163	      up_mdelay(1);
164	    }
165	
166	  return -ETIMEDOUT;
167	}
