271	static FAR void *bk7258_ap_cpu1_affinity_task(FAR void *arg)
272	{
273	  volatile struct bk7258_ap_affinity_state_s *state = arg;
274	  cpu_set_t observed = 0;
275	  pthread_t self = pthread_self();
276	  int ret;
277	
278	  if (state == NULL)
279	    {
280	      return NULL;
281	    }
282	
283	  state->task_id = (uint32_t)self;
284	  state->task_cpu = (uint32_t)up_cpu_index();
285	  state->task_started++;
286	  __asm volatile ("dmb sy" ::: "memory");
287	
288	  if (state->magic != BK7258_AP_AFFINITY_STATE_MAGIC ||
289	      state->version != BK7258_AP_AFFINITY_STATE_VERSION ||
290	      state->size != sizeof(struct bk7258_ap_affinity_state_s) ||
291	      state->generation != bk7258_ap_boot_state()->generation ||
292	      state->state != BK7258_AP_AFFINITY_STATE_DISPATCHING)
293	    {
294	      bk7258_ap_affinity_fail(state,
295	                             BK7258_AP_AFFINITY_ERROR_BAD_STATE);
296	      goto done;
297	    }
298	
299	  state->state = BK7258_AP_AFFINITY_STATE_RUNNING;
300	  __asm volatile ("dmb sy" ::: "memory");
301	
302	  ret = pthread_getaffinity_np(self, sizeof(observed), &observed);
303	  state->observed_mask = (uint32_t)observed;
304	
305	  if (ret != 0)
306	    {
307	      bk7258_ap_affinity_fail(state,
308	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
309	    }
310	  else if (state->task_cpu != BK7258_AP_SECONDARY_CPU)
311	    {
312	      bk7258_ap_affinity_fail(state,
313	                             BK7258_AP_AFFINITY_ERROR_BAD_CPU);
314	    }
315	  else if (state->observed_mask != state->requested_mask)
316	    {
317	      bk7258_ap_affinity_fail(state,
318	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
319	    }
320	
321	done:
322	  state->task_completed++;
323	  __asm volatile ("dmb sy; sev" ::: "memory");
324	  return NULL;
325	}
