329	bk7258_ap_secondary_scheduler_entry(void)
330	{
331	  volatile struct bk7258_cpu2_probe_state_s *state =
332	    bk7258_cpu2_probe_state();
333	  uint32_t control;
334	  uint32_t msp;
335	
336	  arm_initialize_stack();
337	  __asm volatile ("mrs %0, msp" : "=r" (msp));
338	  __asm volatile ("mrs %0, control" : "=r" (control));
339	
340	  state->runtime_msp = msp;
341	  state->control = control;
342	  state->online_mask = BK7258_AP_ONLINE_MASK;
343	  state->secondary_ready = 1;
344	
345	#ifdef CONFIG_SCHED_INSTRUMENTATION
346	  sched_note_cpu_started(this_task());
347	#endif
348	
349	  bk7258_ap_ipi_mark_scheduler_online();
350	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
351	  state->state = BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE;
352	  __asm volatile ("dmb sy; sev" ::: "memory");
353	
354	  nx_idle_trampoline();
355	
356	  bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
357	  for (; ; )
358	    {
359	      __asm volatile ("wfe");
360	    }
361	}
