363	static void __attribute__((naked, noreturn, used))
364	bk7258_ap_secondary_enter_scheduler(
365	  uint32_t stack_top __attribute__((unused)))
366	{
367	  __asm volatile
368	    (
369	      "msr msp, r0\n"
370	      "dsb sy\n"
371	      "isb sy\n"
372	      "b bk7258_ap_secondary_scheduler_entry\n"
373	    );
374	}
375	#endif
