377	static void __attribute__((noinline, noreturn, used))
378	bk7258_ap_secondary_bootstrap(void)
379	{
380	  volatile struct bk7258_cpu2_probe_state_s *state;
381	
382	  bk7258_cpu2_fpu_initialize();
383	  state = bk7258_cpu2_probe_state();
384	  uint32_t control;
385	  uint32_t msp;
386	
387	  __asm volatile ("mrs %0, msp" : "=r" (msp));
388	  __asm volatile ("mrs %0, control" : "=r" (control));
389	
390	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
391	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
392	  state->runtime_vtor = BK7258_SCB_VTOR;
393	  state->runtime_msp = msp;
394	  state->control = control;
395	  state->boot_count++;
396	  __asm volatile ("dmb sy" ::: "memory");
397	
398	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
399	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
400	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
401	    {
402	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
403	      goto parked;
404	    }
405	
406	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
407	  __asm volatile ("dmb sy" ::: "memory");
408	
409	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
410	        BK7258_CPU2_LOCAL_CORE_ID ||
411	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
412	    {
413	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
414	      goto parked;
415	    }
416	
417	  if (state->runtime_vtor !=
418	      (uint32_t)(uintptr_t)__vector_core1_table)
419	    {
420	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
421	      goto parked;
422	    }
423	
424	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
425	      msp > BK7258_CPU2_BOOT_STACK_TOP)
426	    {
427	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
428	      goto parked;
429	    }
430	
431	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
432	      state->idle_stack_base >= state->idle_stack_top ||
433	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
434	    {
435	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
436	      goto parked;
437	    }
438	
439	#ifdef CONFIG_BK7258_AP_IPI
440	  if (bk7258_ap_ipi_secondary_initialize() < 0)
441	    {
442	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
443	      goto parked;
444	    }
445	#endif
446	
447	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
448	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
449	  state->online_mask = BK7258_AP_PRIMARY_MASK;
450	
451	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
452	  state->secondary_ready = 0;
453	  __asm volatile ("dmb sy" ::: "memory");
454	
455	  if (bk7258_cpu2_scheduler_irq_initialize() < 0)
456	    {
457	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
458	      goto parked;
459	    }
460	
461	  bk7258_ap_secondary_enter_scheduler(state->idle_stack_top);
462	#else
463	  state->secondary_ready = 1;
464	  __asm volatile ("dmb sy" ::: "memory");
465	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
466	  __asm volatile ("dmb sy; sev" ::: "memory");
467	
468	#  ifdef CONFIG_BK7258_AP_IPI
469	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
470	#  endif
471	
472	  for (; ; )
473	    {
474	      __asm volatile ("dmb sy" ::: "memory");
475	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
476	        {
477	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
478	          state->secondary_ready = 0;
479	          __asm volatile ("dmb sy" ::: "memory");
480	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
481	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
482	          __asm volatile ("dmb sy; sev" ::: "memory");
483	          goto parked;
484	        }
485	
486	      state->heartbeat++;
487	#  ifdef CONFIG_BK7258_AP_IPI
488	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
489	#  else
490	      __asm volatile ("dmb sy; wfe" ::: "memory");
491	#  endif
492	    }
493	#endif
494	
495	parked:
496	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
497	  for (; ; )
498	    {
499	      __asm volatile ("wfe");
500	    }
501	}
502	
503	static void __attribute__((naked, noreturn, used))
504	bk7258_ap_secondary_reset(void)
505	{
506	  __asm volatile
507	    (
508	      "cpsid i\n"
509	      "movs r0, #0\n"
510	      "msr control, r0\n"
511	      "msr basepri, r0\n"
512	      "msr faultmask, r0\n"
513	      "ldr r0, =0x20000000\n"
514	      "movs r1, #1\n"
515	      "str r1, [r0]\n"
516	      "ldr r0, =__vector_core1_table\n"
517	      "ldr r1, =0xe000ed08\n"
518	      "str r0, [r1]\n"
519	      "dsb sy\n"
520	      "isb sy\n"
521	      "b bk7258_ap_secondary_bootstrap\n"
522	    );
523	}
