525	static void __attribute__((noinline, noreturn, used))
526	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
527	{
528	  volatile struct bk7258_cpu2_probe_state_s *state =
529	    bk7258_cpu2_probe_state();
530	  uintptr_t frame = (uintptr_t)stack;
531	  uint32_t error;
532	
533	  state->fault_exception = exception;
534	  state->fault_hfsr = BK7258_SCB_HFSR;
535	  state->fault_cfsr = BK7258_SCB_CFSR;
536	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
537	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
538	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
539	
540	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
541	      ((frame >= BK7258_CPU2_BOOT_STACK_BASE &&
542	        frame <= BK7258_CPU2_BOOT_STACK_TOP -
543	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
544	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
545	       ||
546	       (frame >= state->idle_stack_base &&
547	        frame <= state->idle_stack_top -
548	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
549	#endif
550	      ))
551	    {
552	      const volatile uint32_t *regs =
553	        (const volatile uint32_t *)frame;
554	
555	      state->fault_lr = regs[5];
556	      state->fault_pc = regs[6];
557	      state->fault_xpsr = regs[7];
558	    }
559	
560	  error = exception == 2u ?
561	    BK7258_CPU2_PROBE_ERROR_NMI :
562	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
563	  bk7258_cpu2_fail(error);
564	
565	  for (; ; )
566	    {
567	      __asm volatile ("wfe");
568	    }
569	}
570	
571	static void __attribute__((naked, noreturn, used))
572	bk7258_ap_secondary_fault_entry(void)
573	{
574	  __asm volatile
575	    (
576	      "tst lr, #4\n"
577	      "ite eq\n"
578	      "mrseq r0, msp\n"
579	      "mrsne r0, psp\n"
580	      "mrs r1, ipsr\n"
581	      "b bk7258_ap_secondary_fault_handler\n"
582	    );
583	}
