625	int up_cpu_start(int cpu)
626	{
627	  volatile struct bk7258_cpu2_probe_state_s *state =
628	    bk7258_cpu2_probe_state();
629	  volatile uint32_t *control = bk7258_cpu2_control();
630	  struct tcb_s *tcb;
631	  uintptr_t idle_base;
632	  uintptr_t idle_top;
633	  uint32_t generation;
634	  uint32_t value;
635	  int ret;
636	
637	  if (cpu != BK7258_AP_SECONDARY_CPU)
638	    {
639	      return -EINVAL;
640	    }
641	
642	  bk7258_cpu2_hold_reset(state);
643	  up_mdelay(1);
644	
645	  generation = bk7258_ap_boot_state()->generation;
646	  if (generation == 0)
647	    {
648	      generation = 1;
649	    }
650	
651	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
652	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
653	  state->size = sizeof(*state);
654	  state->generation = generation;
655	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
656	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
657	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
658	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
659	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
660	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
661	  state->secondary_entry =
662	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
663	  state->online_mask = BK7258_AP_PRIMARY_MASK;
664	
665	  tcb = current_task(cpu);
666	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
667	      tcb->adj_stack_size == 0)
668	    {
669	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
670	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
671	      return -ENOMEM;
672	    }
673	
674	  idle_base = (uintptr_t)tcb->stack_base_ptr;
675	  idle_top = idle_base + tcb->adj_stack_size;
676	  state->idle_stack_base = (uint32_t)idle_base;
677	  state->idle_stack_top = (uint32_t)idle_top;
678	
679	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
680	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
681	    {
682	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
683	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
684	      return -ENOMEM;
685	    }
686	
687	  value = *control;
688	  state->control_before = value;
689	  value &= ~(BK7258_SYS_CPU2_RESET |
690	             BK7258_SYS_CPU2_POWER_DOWN |
691	             BK7258_SYS_CPU2_HALT |
692	             BK7258_SYS_CPU2_RXEVT_SEL |
693	             BK7258_SYS_CPU2_BOOT_MASK);
694	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
695	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
696	  *control = value;
697	  __asm volatile ("dsb sy; isb sy" ::: "memory");
698	
699	  state->control_after = value;
700	  __asm volatile ("dmb sy" ::: "memory");
701	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
702	  __asm volatile ("dmb sy" ::: "memory");
703	
704	#ifdef CONFIG_BK7258_AP_IPI
705	  ret = bk7258_ap_ipi_primary_initialize();
706	  if (ret < 0)
707	    {
708	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
709	      return ret;
710	    }
711	#endif
712	
713	  value |= BK7258_SYS_CPU2_RESET;
714	  *control = value;
715	  state->control_after = value;
716	  __asm volatile ("dsb sy; sev" ::: "memory");
717	
718	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
719	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE,
720	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
721	#else
722	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
723	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
724	#endif
725	  if (ret < 0)
726	    {
727	      bk7258_cpu2_hold_reset(state);
728	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
729	        {
730	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
731	        }
732	    }
733	
734	  return ret;
735	}
