786	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
787	int bk7258_ap_smp_scheduler_selftest(uint32_t timeout_ms)
788	{
789	  volatile struct bk7258_ap_smp_state_s *state = bk7258_ap_smp_state();
790	  uint32_t elapsed;
791	  int cpu;
792	  int ret;
793	
794	  if (timeout_ms == 0)
795	    {
796	      timeout_ms = BK7258_AP_SMP_DEFAULT_TIMEOUT_MS;
797	    }
798	
799	  if (state->magic != BK7258_AP_SMP_STATE_MAGIC ||
800	      state->version != BK7258_AP_SMP_STATE_VERSION ||
801	      state->size != sizeof(struct bk7258_ap_smp_state_s) ||
802	      state->generation != bk7258_ap_boot_state()->generation ||
803	      state->state != BK7258_AP_SMP_STATE_ONLINE ||
804	      state->online_mask != BK7258_AP_ONLINE_MASK)
805	    {
806	      return -EAGAIN;
807	    }
808	
809	  state->error = BK7258_AP_SMP_ERROR_NONE;
810	  state->requested_count = 2;
811	  state->completed_count = 0;
812	  state->test_runs++;
813	  state->last_callback_cpu = UINT32_MAX;
814	
815	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
816	    {
817	      state->tx_count[cpu] = 0;
818	      state->rx_count[cpu] = 0;
819	      state->coalesced_count[cpu] = 0;
820	      state->send_failures[cpu] = 0;
821	      state->call_handler_count[cpu] = 0;
822	      state->delivered_handler_count[cpu] = 0;
823	      state->callback_count[cpu] = 0;
824	      state->last_command[cpu] = 0;
825	    }
826	
827	  __asm volatile ("dmb sy" ::: "memory");
828	  state->state = BK7258_AP_SMP_STATE_TESTING;
829	  __asm volatile ("dmb sy" ::: "memory");
830	
831	  nxsched_smp_call_init(&g_bk7258_ap_smp_forward_call,
832	                        bk7258_ap_smp_secondary_callback,
833	                        (FAR void *)state);
834	  ret = nxsched_smp_call_single_async(BK7258_AP_SECONDARY_CPU,
835	                                      &g_bk7258_ap_smp_forward_call);
836	  if (ret < 0)
837	    {
838	      state->error = BK7258_AP_SMP_ERROR_CALL;
839	      state->state = BK7258_AP_SMP_STATE_FAILED;
840	      __asm volatile ("dmb sy; sev" ::: "memory");
841	      return ret;
842	    }
843	
844	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
845	    {
846	      __asm volatile ("dmb sy" ::: "memory");
847	      if (state->callback_count[BK7258_AP_PRIMARY_CPU] == 1 &&
848	          state->callback_count[BK7258_AP_SECONDARY_CPU] == 1)
849	        {
850	          break;
851	        }
852	
853	      if (state->state == BK7258_AP_SMP_STATE_FAILED)
854	        {
855	          return -EIO;
856	        }
857	
858	      up_mdelay(1);
859	    }
860	
861	  if (elapsed == timeout_ms)
862	    {
863	      state->error = BK7258_AP_SMP_ERROR_TIMEOUT;
864	      state->state = BK7258_AP_SMP_STATE_FAILED;
865	      __asm volatile ("dmb sy; sev" ::: "memory");
866	      return -ETIMEDOUT;
867	    }
868	
869	  if (state->tx_count[0] < 1 || state->tx_count[1] < 1 ||
870	      state->rx_count[0] < 1 || state->rx_count[1] < 1 ||
871	      state->call_handler_count[0] < 1 ||
872	      state->call_handler_count[1] < 1 ||
873	      state->delivered_handler_count[0] < 1 ||
874	      state->delivered_handler_count[1] < 1 ||
875	      state->send_failures[0] != 0 ||
876	      state->send_failures[1] != 0 ||
877	      state->last_callback_cpu != BK7258_AP_PRIMARY_CPU)
878	    {
879	      state->error = BK7258_AP_SMP_ERROR_COUNT_MISMATCH;
880	      state->state = BK7258_AP_SMP_STATE_FAILED;
881	      __asm volatile ("dmb sy; sev" ::: "memory");
882	      return -EIO;
883	    }
884	
885	  state->completed_count = 2;
886	  state->error = BK7258_AP_SMP_ERROR_NONE;
887	  __asm volatile ("dmb sy" ::: "memory");
888	  state->state = BK7258_AP_SMP_STATE_PASSED;
889	  __asm volatile ("dmb sy; sev" ::: "memory");
890	  return OK;
891	}
892	#endif
