894	#ifdef CONFIG_BK7258_AP_SMP_CPU1_AFFINITY
895	int bk7258_ap_smp_affinity_selftest(uint32_t timeout_ms)
896	{
897	  volatile struct bk7258_ap_affinity_state_s *state =
898	    bk7258_ap_affinity_state();
899	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
900	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
901	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
902	    bk7258_cpu2_probe_state();
903	  FAR struct tcb_s *tcb;
904	  pthread_attr_t attr;
905	  pthread_t thread;
906	  cpu_set_t cpuset = (cpu_set_t)1u << BK7258_AP_SECONDARY_CPU;
907	  uint32_t elapsed;
908	  int ret;
909	
910	  if (timeout_ms == 0)
911	    {
912	      timeout_ms = BK7258_AP_AFFINITY_TIMEOUT_MS;
913	    }
914	
915	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
916	  state->version = BK7258_AP_AFFINITY_STATE_VERSION;
917	  state->size = sizeof(*state);
918	  state->generation = bk7258_ap_boot_state()->generation;
919	  state->state = BK7258_AP_AFFINITY_STATE_INITIALIZING;
920	  state->requested_mask = (uint32_t)cpuset;
921	  state->test_runs = 1;
922	  state->timeout_ms = timeout_ms;
923	  state->smp_tx_before = smp->tx_count[BK7258_AP_PRIMARY_CPU];
924	  state->smp_rx_before = smp->rx_count[BK7258_AP_SECONDARY_CPU];
925	  state->smp_fail_before = smp->send_failures[BK7258_AP_PRIMARY_CPU];
926	  state->ipi_irq_before = ipi->irq_count[BK7258_AP_SECONDARY_CPU];
927	  state->ipi_wake_before = ipi->wake_count[BK7258_AP_SECONDARY_CPU];
928	  state->cpu2_calls_before = cpu2->smp_call_requests;
929	  __asm volatile ("dmb sy" ::: "memory");
930	  state->magic = BK7258_AP_AFFINITY_STATE_MAGIC;
931	  __asm volatile ("dmb sy" ::: "memory");
932	
933	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
934	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
935	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
936	      smp->generation != state->generation ||
937	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
938	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
939	      smp->online_mask != BK7258_AP_ONLINE_MASK ||
940	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
941	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
942	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
943	      ipi->generation != state->generation ||
944	      ipi->state != BK7258_AP_IPI_STATE_READY ||
945	      ipi->error != BK7258_AP_IPI_ERROR_NONE ||
946	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE ||
947	      cpu2->online_mask != BK7258_AP_ONLINE_MASK)
948	    {
949	      bk7258_ap_affinity_fail(state,
950	                             BK7258_AP_AFFINITY_ERROR_BAD_STATE);
951	      return -EAGAIN;
952	    }
953	
954	  ret = pthread_attr_init(&attr);
955	  if (ret != 0)
956	    {
957	      bk7258_ap_affinity_fail(state, BK7258_AP_AFFINITY_ERROR_ATTR);
958	      return -ret;
959	    }
960	
961	  ret = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
962	  if (ret == 0)
963	    {
964	      ret = pthread_attr_setaffinity_np(&attr, sizeof(cpuset), &cpuset);
965	    }
966	
967	  if (ret != 0)
968	    {
969	      (void)pthread_attr_destroy(&attr);
970	      bk7258_ap_affinity_fail(state, BK7258_AP_AFFINITY_ERROR_ATTR);
971	      return -ret;
972	    }
973	
974	  state->state = BK7258_AP_AFFINITY_STATE_DISPATCHING;
975	  __asm volatile ("dmb sy" ::: "memory");
976	  ret = pthread_create(&thread, &attr, bk7258_ap_cpu1_affinity_task,
977	                       (FAR void *)state);
978	  (void)pthread_attr_destroy(&attr);
979	  if (ret != 0)
980	    {
981	      bk7258_ap_affinity_fail(state, BK7258_AP_AFFINITY_ERROR_CREATE);
982	      return -ret;
983	    }
984	
985	  state->task_id = (uint32_t)thread;
986	  __asm volatile ("dmb sy" ::: "memory");
987	
988	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
989	    {
990	      __asm volatile ("dmb sy" ::: "memory");
991	      if (state->task_completed == 1)
992	        {
993	          tcb = nxsched_get_tcb((pid_t)thread);
994	          if (tcb == NULL)
995	            {
996	              state->pid_released = 1;
997	              __asm volatile ("dmb sy" ::: "memory");
998	              break;
999	            }
1000	
1001	          nxsched_put_tcb(tcb);
1002	        }
1003	
1004	      up_mdelay(1);
1005	    }
1006	
1007	  if (elapsed == timeout_ms)
1008	    {
1009	      bk7258_ap_affinity_fail(state,
1010	                             BK7258_AP_AFFINITY_ERROR_TIMEOUT);
1011	      return -ETIMEDOUT;
1012	    }
1013	
1014	  __asm volatile ("dmb sy" ::: "memory");
1015	  state->smp_tx_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1016	  state->smp_rx_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1017	  state->smp_fail_after = smp->send_failures[BK7258_AP_PRIMARY_CPU];
1018	  state->ipi_irq_after = ipi->irq_count[BK7258_AP_SECONDARY_CPU];
1019	  state->ipi_wake_after = ipi->wake_count[BK7258_AP_SECONDARY_CPU];
1020	  state->cpu2_calls_after = cpu2->smp_call_requests;
1021	  __asm volatile ("dmb sy" ::: "memory");
1022	
1023	  if (state->state == BK7258_AP_AFFINITY_STATE_FAILED)
1024	    {
1025	      return -EIO;
1026	    }
1027	
1028	  if (state->state != BK7258_AP_AFFINITY_STATE_RUNNING ||
1029	      state->task_started != 1 || state->task_completed != 1 ||
1030	      state->pid_released != 1 ||
1031	      state->task_cpu != BK7258_AP_SECONDARY_CPU ||
1032	      state->requested_mask !=
1033	        ((uint32_t)1u << BK7258_AP_SECONDARY_CPU) ||
1034	      state->observed_mask != state->requested_mask ||
1035	      state->smp_tx_after <= state->smp_tx_before ||
1036	      state->smp_rx_after <= state->smp_rx_before ||
1037	      state->ipi_irq_after <= state->ipi_irq_before ||
1038	      state->ipi_wake_after <= state->ipi_wake_before ||
1039	      state->cpu2_calls_after <= state->cpu2_calls_before ||
1040	      state->smp_fail_after != state->smp_fail_before ||
1041	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
1042	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
1043	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE)
1044	    {
1045	      bk7258_ap_affinity_fail(
1046	        state, BK7258_AP_AFFINITY_ERROR_COUNT_MISMATCH);
1047	      return -EIO;
1048	    }
1049	
1050	  state->error = BK7258_AP_AFFINITY_ERROR_NONE;
1051	  __asm volatile ("dmb sy" ::: "memory");
1052	  state->state = BK7258_AP_AFFINITY_STATE_PASSED;
1053	  __asm volatile ("dmb sy; sev" ::: "memory");
1054	  return OK;
1055	}
