1058	int bk7258_ap_smp_secondary_stop(uint32_t timeout_ms)
1059	{
1060	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1061	  (void)timeout_ms;
1062	  return -ENOTSUP;
1063	#else
1064	  volatile struct bk7258_cpu2_probe_state_s *state =
1065	    bk7258_cpu2_probe_state();
1066	  int ret = OK;
1067	
1068	  if (timeout_ms == 0)
1069	    {
1070	      timeout_ms = BK7258_CPU2_PROBE_STOP_TIMEOUT_MS;
1071	    }
1072	
1073	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
1074	      state->version != BK7258_CPU2_PROBE_STATE_VERSION)
1075	    {
1076	      ret = -EIO;
1077	    }
1078	  else if (state->state == BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
1079	           state->state == BK7258_CPU2_PROBE_STATE_BOOTSTRAP ||
1080	           state->state == BK7258_CPU2_PROBE_STATE_STARTING)
1081	    {
1082	      state->command = BK7258_CPU2_PROBE_COMMAND_STOP;
1083	      __asm volatile ("dmb sy" ::: "memory");
1084	#ifdef CONFIG_BK7258_AP_IPI
1085	      ret = bk7258_ap_ipi_wake_secondary();
1086	      if (ret >= 0)
1087	        {
1088	          ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
1089	                                 timeout_ms);
1090	        }
1091	#else
1092	      __asm volatile ("sev" ::: "memory");
1093	      ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
1094	                             timeout_ms);
1095	#endif
1096	    }
1097	  else if (state->state == BK7258_CPU2_PROBE_STATE_FAILED)
1098	    {
1099	      ret = -EIO;
1100	    }
1101	
1102	  bk7258_cpu2_hold_reset(state);
1103	  state->secondary_ready = 0;
1104	  __asm volatile ("dmb sy" ::: "memory");
1105	
1106	#ifdef CONFIG_BK7258_AP_IPI
1107	  if (ret >= 0)
1108	    {
1109	      bk7258_ap_ipi_mark_stopped();
1110	    }
1111	#endif
1112	
1113	  if (ret < 0 && state->state != BK7258_CPU2_PROBE_STATE_FAILED)
1114	    {
1115	      bk7258_cpu2_fail(ret == -ETIMEDOUT ?
1116	        BK7258_CPU2_PROBE_ERROR_TIMEOUT :
1117	        BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
1118	    }
1119	
1120	  return ret;
1121	#endif
1122	}
