57	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
58	{
59	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
60	  __asm volatile ("dsb sy" ::: "memory");
61	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
62	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
63	  __asm volatile ("dsb sy" ::: "memory");
64	}
