66	static uint32_t bk7258_ap_mbox_receive(void)
67	{
68	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
69	  uint32_t event = BK7258_AP_EVENT_NONE;
70	
71	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
72	       BK7258_MBOX_BOX0_BIT) != 0)
73	    {
74	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
75	          BK7258_AP_DOORBELL_MAGIC)
76	        {
77	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
78	        }
79	
80	      bk7258_ap_mbox_ack(mbox);
81	    }
82	
83	  return event;
84	}
