230	int bk7258_ap_main(int argc, char *argv[])
231	{
232	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
233	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
234	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
235	#endif
236	  uint32_t event;
237	  int error;
238	  int ret;
239	
240	  (void)argc;
241	  (void)argv;
242	
243	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
244	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
245	      state->size != sizeof(struct bk7258_ap_boot_state_s))
246	    {
247	      state->state = BK7258_AP_STATE_FAILED;
248	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
249	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
250	      goto parked;
251	    }
252	
253	  error = bk7258_ap_validate_runtime();
254	  if (error != BK7258_AP_ERROR_NONE)
255	    {
256	      state->state = BK7258_AP_STATE_FAILED;
257	      state->error = (uint32_t)error;
258	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
259	      goto parked;
260	    }
261	
262	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
263	  error = bk7258_ap_validate_secondary_bootstrap();
264	  if (error != BK7258_AP_ERROR_NONE)
265	    {
266	      state->state = BK7258_AP_STATE_FAILED;
267	      state->error = (uint32_t)error;
268	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
269	      goto parked;
270	    }
271	#else
272	  ret = bk7258_cpu2_probe_start(BK7258_CPU2_PROBE_TIMEOUT_MS);
273	  if (ret < 0)
274	    {
275	      state->state = BK7258_AP_STATE_FAILED;
276	      state->error = BK7258_AP_ERROR_CPU2_PROBE;
277	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
278	      goto parked;
279	    }
280	#endif
281	
282	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
283	  ret = bk7258_ap_smp_scheduler_selftest(
284	    BK7258_AP_SMP_DEFAULT_TIMEOUT_MS);
285	  if (ret < 0)
286	    {
287	      state->state = BK7258_AP_STATE_FAILED;
288	      state->error = BK7258_AP_ERROR_CPU2_SMP_SCHEDULER;
289	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
290	      goto parked;
291	    }
292	#endif
293	
294	#ifdef CONFIG_BK7258_AP_SMP_CPU1_AFFINITY
295	  ret = bk7258_ap_smp_affinity_selftest(
296	    BK7258_AP_AFFINITY_TIMEOUT_MS);
297	  if (ret < 0)
298	    {
299	      state->state = BK7258_AP_STATE_FAILED;
300	      state->error = BK7258_AP_ERROR_CPU2_AFFINITY;
301	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
302	      goto parked;
303	    }
304	#endif
305	
306	  state->error      = BK7258_AP_ERROR_NONE;
307	  state->last_event = BK7258_AP_EVENT_READY;
308	  state->state      = BK7258_AP_STATE_READY;
309	  __asm volatile ("dmb sy" ::: "memory");
310	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
311	
312	  for (; ; )
313	    {
314	      event = bk7258_ap_mbox_receive();
315	      if (event != BK7258_AP_EVENT_NONE)
316	        {
317	          state->last_event = event;
318	        }
319	
320	      if (event == BK7258_AP_EVENT_STOP ||
321	          state->command == BK7258_AP_COMMAND_STOP)
322	        {
323	          state->state = BK7258_AP_STATE_STOPPING;
324	          __asm volatile ("dmb sy" ::: "memory");
325	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
326	          ret = bk7258_ap_smp_secondary_stop(
327	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
328	#else
329	          ret = bk7258_cpu2_probe_stop(
330	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
331	#endif
332	          if (ret < 0)
333	            {
334	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
335	              state->error = BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
336	#else
337	              state->error = BK7258_AP_ERROR_CPU2_PROBE;
338	#endif
339	              state->state = BK7258_AP_STATE_FAILED;
340	              state->last_event = BK7258_AP_EVENT_FAILED;
341	              bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
342	              break;
343	            }
344	
345	          state->state = BK7258_AP_STATE_STOPPED;
346	          state->last_event = BK7258_AP_EVENT_STOPPED;
347	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
348	          break;
349	        }
350	
351	#ifdef CONFIG_BK7258_AP_IPI
352	      if (event == BK7258_AP_EVENT_IPI_TEST ||
353	          state->command == BK7258_AP_COMMAND_IPI_TEST)
354	        {
355	          volatile struct bk7258_ap_ipi_state_s *ipi =
356	            bk7258_ap_ipi_state();
357	
358	          state->command = BK7258_AP_COMMAND_NONE;
359	          __asm volatile ("dmb sy" ::: "memory");
360	          ret = bk7258_ap_ipi_selftest(ipi->requested_count,
361	                                       ipi->timeout_ms);
362	          if (ret < 0)
363	            {
364	              state->error = BK7258_AP_ERROR_CPU2_IPI;
365	              state->last_event = BK7258_AP_EVENT_IPI_TEST_FAILED;
366	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_FAILED);
367	            }
368	          else
369	            {
370	              state->error = BK7258_AP_ERROR_NONE;
371	              state->last_event = BK7258_AP_EVENT_IPI_TEST_PASSED;
372	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_PASSED);
373	            }
374	        }
375	#endif
376	
377	      state->heartbeat++;
378	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
379	      smp->sleep_enter_count++;
380	#endif
381	      __asm volatile ("dmb sy; sev" ::: "memory");
382	      nxsig_usleep(BK7258_AP_HEARTBEAT_US);
383	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
384	      smp->sleep_return_count++;
385	      __asm volatile ("dmb sy" ::: "memory");
386	#endif
387	    }
388	
389	parked:
390	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
391	  for (; ; )
392	    {
393	      __asm volatile ("wfe");
394	    }
395	
396	  return 0;
397	}
