26	/****************************************************************************
27	 * External Function Prototypes
28	 ****************************************************************************/
29	
30	/* These four routines are provided by the pinned Beken CP SDK archives. */
31	
32	extern void sys_drv_set_cpu1_pwr_dw(uint32_t is_pwr_down);
33	extern void sys_drv_set_cpu1_rxevt_sel(uint32_t value);
34	extern void sys_drv_set_cpu1_boot_address_offset(uint32_t address_offset);
35	extern void sys_drv_set_cpu1_reset(uint32_t reset_value);
36	
37	/****************************************************************************
38	 * Private Data
39	 ****************************************************************************/
40	
41	/* Singleton SoC CPU1 control state.  The mutex serializes SYS register and
42	 * shared-state transitions issued by concurrent NSH callers.
43	 */
44	
45	static mutex_t g_bk7258_ap_lock = NXMUTEX_INITIALIZER;
46	static bool g_bk7258_ap_initialized;
47	
48	/****************************************************************************
49	 * Private Functions
50	 ****************************************************************************/
51	
52	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
53	{
54	  return (volatile uint32_t *)(uintptr_t)base;
55	}
56	
57	static void bk7258_cpu2_force_reset(void)
58	{
59	  volatile uint32_t *control =
60	    (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
61	
62	  *control &= ~BK7258_SYS_CPU2_RESET;
63	  __asm volatile ("dsb sy; isb sy" ::: "memory");
64	}
65	
66	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
67	{
68	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
69	  __asm volatile ("dsb sy" ::: "memory");
70	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
71	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
72	  __asm volatile ("dsb sy" ::: "memory");
73	}
74	
75	static void bk7258_ap_mbox_initialize(void)
76	{
77	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
78	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
79	
80	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
81	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
82	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
83	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
84	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
85	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
86	
87	  bk7258_ap_mbox_ack(to_ap);
88	  bk7258_ap_mbox_ack(to_cp);
89	}
90	
91	static void bk7258_ap_mbox_send(uint32_t event)
92	{
93	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
94	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
95	
96	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
97	       BK7258_MBOX_BOX0_BIT) != 0)
98	    {
99	      bk7258_ap_mbox_ack(mbox);
100	    }
101	
102	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
103	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
104	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
105	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
106	  __asm volatile ("dmb sy" ::: "memory");
107	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
108	  state->cp_to_ap_doorbells++;
109	  __asm volatile ("dsb sy; sev" ::: "memory");
110	}
111	
112	static uint32_t bk7258_ap_mbox_receive(void)
113	{
114	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
115	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
116	  uint32_t event = BK7258_AP_EVENT_NONE;
117	
118	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
119	       BK7258_MBOX_BOX0_BIT) != 0)
120	    {
121	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
122	          BK7258_AP_DOORBELL_MAGIC &&
123	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
124	        {
125	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
126	        }
127	
128	      bk7258_ap_mbox_ack(mbox);
129	    }
130	
131	  return event;
132	}
133	
134	static void bk7258_ap_state_prepare(void)
135	{
136	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
137	  uint32_t generation = 1;
138	
139	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
140	      state->version == BK7258_AP_BOOT_STATE_VERSION)
141	    {
142	      generation = state->generation + 1;
143	    }
144	
145	  memset((void *)(uintptr_t)state, 0,
146	         sizeof(struct bk7258_ap_boot_state_s));
147	  bk7258_ap_fault_state()->magic = 0;
148	  bk7258_cpu2_probe_state()->magic = 0;
149	  bk7258_ap_ipi_state()->magic = 0;
150	  bk7258_ap_smp_state()->magic = 0;
151	  bk7258_ap_affinity_state()->magic = 0;
152	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
153	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
154	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
155	  state->generation  = generation;
156	  state->command     = BK7258_AP_COMMAND_START;
157	  state->state       = BK7258_AP_STATE_STARTING;
158	  state->ram_start   = BK7258_AP_RAM_BASE;
159	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
160	  state->flash_start = BK7258_AP_FLASH_ADDR;
161	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
162	  __asm volatile ("dmb sy" ::: "memory");
163	}
164	
165	static bool bk7258_ap_scheduler_online(void)
166	{
167	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
168	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
169	    bk7258_cpu2_probe_state();
170	
171	  __asm volatile ("dmb sy" ::: "memory");
172	  return cpu2->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
173	         cpu2->version == BK7258_CPU2_PROBE_STATE_VERSION &&
174	         cpu2->size == sizeof(struct bk7258_cpu2_probe_state_s) &&
175	         cpu2->generation == state->generation &&
176	         cpu2->state == BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE &&
177	         cpu2->online_mask == 0x3u;
178	}
179	
180	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
181	{
182	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
183	  uint32_t elapsed;
184	  uint32_t event;
185	
186	  if (timeout_ms == 0)
187	    {
188	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
189	    }
190	
191	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
192	    {
193	      event = bk7258_ap_mbox_receive();
194	      if (event != BK7258_AP_EVENT_NONE)
195	        {
196	          state->last_event = event;
197	        }
198	
199	      __asm volatile ("dmb sy" ::: "memory");
200	      if (state->state == wanted)
201	        {
202	          return OK;
203	        }
204	
205	      if (state->state == BK7258_AP_STATE_FAILED)
206	        {
207	          return -EIO;
208	        }
209	
210	      nxsig_usleep(1000);
211	    }
212	
213	  return -ETIMEDOUT;
214	}
215	
216	static int bk7258_ap_start_locked(uint32_t timeout_ms)
217	{
218	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
219	  int ret;
220	
221	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
222	      (state->state == BK7258_AP_STATE_READY ||
223	       state->state == BK7258_AP_STATE_STARTING))
224	    {
225	      return -EBUSY;
226	    }
227	
228	  /* Hold CPU1 while replacing shared state and the boot address. */
229	
230	  sys_drv_set_cpu1_reset(0);
231	  __asm volatile ("dsb sy; isb sy" ::: "memory");
232	  bk7258_cpu2_force_reset();
233	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
234	  bk7258_ap_mbox_initialize();
235	  bk7258_ap_state_prepare();
236	
237	  /* Exact BK7258 CPU1 release order from the CP SDK. */
238	
239	  sys_drv_set_cpu1_pwr_dw(0);
240	  sys_drv_set_cpu1_rxevt_sel(1);
241	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
242	  __asm volatile ("dsb sy; isb sy" ::: "memory");
243	  sys_drv_set_cpu1_reset(1);
244	  __asm volatile ("dsb sy; sev" ::: "memory");
245	
246	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
247	  if (ret < 0)
248	    {
249	      sys_drv_set_cpu1_reset(0);
250	      __asm volatile ("dsb sy; isb sy" ::: "memory");
251	      bk7258_cpu2_force_reset();
252	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
253	      sys_drv_set_cpu1_pwr_dw(1);
254	
255	      if (state->state != BK7258_AP_STATE_FAILED)
256	        {
257	          state->error = BK7258_AP_ERROR_TIMEOUT;
258	        }
259	
260	      state->command = BK7258_AP_COMMAND_NONE;
261	      state->state = BK7258_AP_STATE_FAILED;
262	      state->last_event = BK7258_AP_EVENT_FAILED;
263	      __asm volatile ("dmb sy" ::: "memory");
264	    }
265	
266	  return ret;
267	}
268	
269	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
270	{
271	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
272	  int ret = OK;
273	
274	  if (bk7258_ap_scheduler_online())
275	    {
276	      return -ENOTSUP;
277	    }
278	
279	  if (state->state == BK7258_AP_STATE_READY ||
280	      state->state == BK7258_AP_STATE_STARTING)
281	    {
282	      state->command = BK7258_AP_COMMAND_STOP;
283	      __asm volatile ("dmb sy" ::: "memory");
284	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
285	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
286	    }
287	
288	  /* A timeout still ends in a deterministic forced stop of both AP cores. */
289	
290	  sys_drv_set_cpu1_reset(0);
291	  __asm volatile ("dsb sy; isb sy" ::: "memory");
292	  bk7258_cpu2_force_reset();
293	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
294	  sys_drv_set_cpu1_pwr_dw(1);
295	
296	  if (ret < 0 && state->state != BK7258_AP_STATE_FAILED)
297	    {
298	      state->error = BK7258_AP_ERROR_TIMEOUT;
299	    }
300	
301	  state->command = BK7258_AP_COMMAND_NONE;
302	  state->state = BK7258_AP_STATE_STOPPED;
303	  state->last_event = BK7258_AP_EVENT_STOPPED;
304	  __asm volatile ("dmb sy" ::: "memory");
305	  return ret;
306	}
