308	/****************************************************************************
309	 * Public Functions
310	 ****************************************************************************/
311	
312	int bk7258_ap_control_initialize(void)
313	{
314	  int ret;
315	
316	  ret = nxmutex_lock(&g_bk7258_ap_lock);
317	  if (ret < 0)
318	    {
319	      return ret;
320	    }
321	
322	  if (!g_bk7258_ap_initialized)
323	    {
324	      bk7258_ap_mbox_initialize();
325	      g_bk7258_ap_initialized = true;
326	    }
327	
328	  nxmutex_unlock(&g_bk7258_ap_lock);
329	  return OK;
330	}
331	
332	int bk7258_ap_start(uint32_t timeout_ms)
333	{
334	  int ret;
335	
336	  ret = nxmutex_lock(&g_bk7258_ap_lock);
337	  if (ret < 0)
338	    {
339	      return ret;
340	    }
341	
342	  if (!g_bk7258_ap_initialized)
343	    {
344	      bk7258_ap_mbox_initialize();
345	      g_bk7258_ap_initialized = true;
346	    }
347	
348	  ret = bk7258_ap_start_locked(timeout_ms);
349	  nxmutex_unlock(&g_bk7258_ap_lock);
350	  return ret;
351	}
352	
353	int bk7258_ap_stop(uint32_t timeout_ms)
354	{
355	  int ret;
356	
357	  ret = nxmutex_lock(&g_bk7258_ap_lock);
358	  if (ret < 0)
359	    {
360	      return ret;
361	    }
362	
363	  ret = bk7258_ap_stop_locked(timeout_ms);
364	  nxmutex_unlock(&g_bk7258_ap_lock);
365	  return ret;
366	}
367	
368	int bk7258_ap_restart(uint32_t timeout_ms)
369	{
370	  int ret;
371	
372	  ret = nxmutex_lock(&g_bk7258_ap_lock);
373	  if (ret < 0)
374	    {
375	      return ret;
376	    }
377	
378	  ret = bk7258_ap_stop_locked(timeout_ms);
379	  if (ret == OK || ret == -ETIMEDOUT)
380	    {
381	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
382	      ret = bk7258_ap_start_locked(timeout_ms);
383	    }
384	
385	  nxmutex_unlock(&g_bk7258_ap_lock);
386	  return ret;
387	}
388	
389	int bk7258_ap_ipi_test(uint32_t count, uint32_t timeout_ms)
390	{
391	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
392	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
393	  uint32_t elapsed;
394	  uint32_t event;
395	  int ret;
396	
397	  if (count == 0)
398	    {
399	      count = BK7258_AP_IPI_DEFAULT_COUNT;
400	    }
401	
402	  if (timeout_ms == 0)
403	    {
404	      timeout_ms = BK7258_AP_IPI_DEFAULT_TIMEOUT_MS;
405	    }
406	
407	  if (count > BK7258_AP_IPI_MAX_COUNT)
408	    {
409	      return -ERANGE;
410	    }
411	
412	  ret = nxmutex_lock(&g_bk7258_ap_lock);
413	  if (ret < 0)
414	    {
415	      return ret;
416	    }
417	
418	  __asm volatile ("dmb sy" ::: "memory");
419	  if (bk7258_ap_scheduler_online())
420	    {
421	      ret = -ENOTSUP;
422	      goto out;
423	    }
424	
425	  if (state->state != BK7258_AP_STATE_READY ||
426	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
427	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
428	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
429	      ipi->generation != state->generation)
430	    {
431	      ret = -EAGAIN;
432	      goto out;
433	    }
434	
435	  if (ipi->state == BK7258_AP_IPI_STATE_RUNNING ||
436	      ipi->state == BK7258_AP_IPI_STATE_REQUESTED)
437	    {
438	      ret = -EBUSY;
439	      goto out;
440	    }
441	
442	  ipi->requested_count = count;
443	  ipi->completed_count = 0;
444	  ipi->timeout_ms = timeout_ms;
445	  ipi->error = BK7258_AP_IPI_ERROR_NONE;
446	  ipi->state = BK7258_AP_IPI_STATE_REQUESTED;
447	  state->command = BK7258_AP_COMMAND_IPI_TEST;
448	  __asm volatile ("dmb sy" ::: "memory");
449	  bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST);
450	
451	  ret = -ETIMEDOUT;
452	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
453	    {
454	      event = bk7258_ap_mbox_receive();
455	      if (event != BK7258_AP_EVENT_NONE)
456	        {
457	          state->last_event = event;
458	        }
459	
460	      __asm volatile ("dmb sy" ::: "memory");
461	      if (ipi->state == BK7258_AP_IPI_STATE_PASSED)
462	        {
463	          ret = OK;
464	          break;
465	        }
466	
467	      if (ipi->state == BK7258_AP_IPI_STATE_FAILED ||
468	          state->state == BK7258_AP_STATE_FAILED)
469	        {
470	          ret = -EIO;
471	          break;
472	        }
473	
474	      nxsig_usleep(1000);
475	    }
476	
477	out:
478	  nxmutex_unlock(&g_bk7258_ap_lock);
479	  return ret;
480	}
481	
482	void bk7258_ap_get_status(struct bk7258_ap_boot_state_s *status)
483	{
484	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
485	
486	  if (status != NULL)
487	    {
488	      __asm volatile ("dmb sy" ::: "memory");
489	      memcpy(status, (const void *)(uintptr_t)state, sizeof(*status));
490	      __asm volatile ("dmb sy" ::: "memory");
491	    }
492	}
