141	static uint32_t apctl_u32(const char *value, uint32_t fallback)
142	{
143	  char *end;
144	  unsigned long parsed;
145	
146	  if (value == NULL)
147	    {
148	      return fallback;
149	    }
150	
151	  parsed = strtoul(value, &end, 0);
152	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
153	    {
154	      return fallback;
155	    }
156	
157	  return (uint32_t)parsed;
158	}
