366	static void apctl_usage(void)
367	{
368	  printf("usage: apctl start|stop|restart|status [timeout_ms]\n");
369	  printf("       apctl cycle [count] [timeout_ms]\n");
370	  printf("       apctl ipitest [count] [timeout_ms]\n");
371	}
