373	/****************************************************************************
374	 * Public Functions
375	 ****************************************************************************/
376	
377	int main(int argc, char *argv[])
378	{
379	  uint32_t timeout;
380	  uint32_t count;
381	  uint32_t i;
382	  int ret = -EINVAL;
383	
384	  if (argc < 2)
385	    {
386	      apctl_usage();
387	      return 1;
388	    }
389	
390	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
391	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
392	
393	  if (strcmp(argv[1], "start") == 0)
394	    {
395	      ret = bk7258_ap_start(timeout);
396	    }
397	  else if (strcmp(argv[1], "stop") == 0)
398	    {
399	      ret = bk7258_ap_stop(timeout);
400	    }
401	  else if (strcmp(argv[1], "restart") == 0)
402	    {
403	      ret = bk7258_ap_restart(timeout);
404	    }
405	  else if (strcmp(argv[1], "status") == 0)
406	    {
407	      apctl_status();
408	      return 0;
409	    }
410	  else if (strcmp(argv[1], "ipitest") == 0)
411	    {
412	      count = apctl_u32(argc > 2 ? argv[2] : NULL,
413	                        BK7258_AP_IPI_DEFAULT_COUNT);
414	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
415	                          BK7258_AP_IPI_DEFAULT_TIMEOUT_MS);
416	      ret = bk7258_ap_ipi_test(count, timeout);
417	    }
418	  else if (strcmp(argv[1], "cycle") == 0)
419	    {
420	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
421	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
422	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
423	
424	      /* Normalize the entry state so every iteration is one complete
425	       * start/stop generation, including when cycle is invoked from READY.
426	       */
427	
428	      ret = bk7258_ap_stop(timeout);
429	      for (i = 0; ret >= 0 && i < count; i++)
430	        {
431	          ret = bk7258_ap_start(timeout);
432	          if (ret < 0)
433	            {
434	              break;
435	            }
436	
437	          apctl_status();
438	          ret = bk7258_ap_stop(timeout);
439	        }
440	    }
441	  else
442	    {
443	      apctl_usage();
444	      return 1;
445	    }
446	
447	  apctl_status();
448	  if (ret < 0)
449	    {
450	      if (ret == -ENOTSUP)
451	        {
452	          fprintf(stderr,
453	                  "apctl: %s is disabled while AP scheduler-online mode "
454	                  "is active\n", argv[1]);
455	        }
456	      else
457	        {
458	          fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
459	        }
460	
461	      return 1;
462	    }
463	
464	  return 0;
465	}
