52	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
53	{
54	  return (volatile uint32_t *)(uintptr_t)base;
55	}
56	
57	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
58	{
59	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
60	  __asm volatile ("dsb sy" ::: "memory");
61	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
62	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
63	  __asm volatile ("dsb sy" ::: "memory");
64	}
65	
66	static uint32_t bk7258_ap_mbox_receive(void)
67	{
68	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
69	  uint32_t event = BK7258_AP_EVENT_NONE;
70	
71	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
72	       BK7258_MBOX_BOX0_BIT) != 0)
73	    {
74	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
75	          BK7258_AP_DOORBELL_MAGIC)
76	        {
77	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
78	        }
79	
80	      bk7258_ap_mbox_ack(mbox);
81	    }
82	
83	  return event;
84	}
85	
86	static void bk7258_ap_mbox_send(uint32_t event)
87	{
88	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
89	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
90	
91	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
92	       BK7258_MBOX_BOX0_BIT) != 0)
93	    {
94	      bk7258_ap_mbox_ack(mbox);
95	    }
96	
97	  mbox[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
98	  mbox[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
99	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
100	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
101	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
102	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->state;
103	  __asm volatile ("dmb sy" ::: "memory");
104	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
105	  state->ap_to_cp_doorbells++;
106	  __asm volatile ("dsb sy; sev" ::: "memory");
107	}
108	
109	static int bk7258_ap_validate_runtime(void)
110	{
111	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
112	  void *test;
113	  uint32_t msp;
114	
115	  __asm volatile ("mrs %0, msp" : "=r"(msp));
116	
117	  state->runtime_vtor    = BK7258_SCB_VTOR;
118	  state->runtime_msp     = msp;
119	  state->clock_hz        = bk7258_clockdiag_current_cpu_hz();
120	  state->systick_ctrl    = BK7258_SYSTICK_CTRL;
121	  state->systick_reload  = BK7258_SYSTICK_RELOAD;
122	  state->systick_current = BK7258_SYSTICK_CURRENT;
123	  state->heap_start      = (uint32_t)g_idle_topstack;
124	  state->heap_end        = BK7258_AP_HEAP_END;
125	  state->ram_start       = BK7258_AP_RAM_BASE;
126	  state->ram_end         = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
127	  state->flash_start     = BK7258_AP_FLASH_ADDR;
128	  state->flash_end       = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
129	
130	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR != 0 ||
131	      state->physical_core_id != 1)
132	    {
133	      return BK7258_AP_ERROR_BAD_CORE_ID;
134	    }
135	
136	  if (state->runtime_vtor < BK7258_AP_RAM_BASE ||
137	      state->runtime_vtor >= BK7258_SHARED_RAM_BASE ||
138	      (state->runtime_vtor & 0x1ffu) != 0)
139	    {
140	      return BK7258_AP_ERROR_BAD_VTOR;
141	    }
142	
143	  if ((state->systick_ctrl &
144	       (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT)) !=
145	      (BK7258_SYSTICK_ENABLE | BK7258_SYSTICK_TICKINT) ||
146	      state->systick_reload == 0)
147	    {
148	      return BK7258_AP_ERROR_BAD_SYSTICK;
149	    }
150	
151	  test = kmm_malloc(64);
152	  if (test == NULL)
153	    {
154	      return BK7258_AP_ERROR_HEAP;
155	    }
156	
157	  memset(test, 0xa5, 64);
158	  state->heap_test = (uint32_t)(uintptr_t)test;
159	  kmm_free(test);
160	  return BK7258_AP_ERROR_NONE;
161	}
