230	int bk7258_ap_main(int argc, char *argv[])
231	{
232	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
233	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
234	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
235	#endif
236	  uint32_t event;
237	  int error;
238	  int ret;
239	
240	  (void)argc;
241	  (void)argv;
242	
243	  if (state->magic != BK7258_AP_BOOT_STATE_MAGIC ||
244	      state->version != BK7258_AP_BOOT_STATE_VERSION ||
245	      state->size != sizeof(struct bk7258_ap_boot_state_s))
246	    {
247	      state->state = BK7258_AP_STATE_FAILED;
248	      state->error = BK7258_AP_ERROR_BAD_BOOT_STATE;
249	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
250	      goto parked;
251	    }
252	
253	  error = bk7258_ap_validate_runtime();
254	  if (error != BK7258_AP_ERROR_NONE)
255	    {
256	      state->state = BK7258_AP_STATE_FAILED;
257	      state->error = (uint32_t)error;
258	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
259	      goto parked;
260	    }
261	
262	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
263	  error = bk7258_ap_validate_secondary_bootstrap();
264	  if (error != BK7258_AP_ERROR_NONE)
265	    {
266	      state->state = BK7258_AP_STATE_FAILED;
267	      state->error = (uint32_t)error;
268	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
269	      goto parked;
270	    }
271	#else
272	  ret = bk7258_cpu2_probe_start(BK7258_CPU2_PROBE_TIMEOUT_MS);
273	  if (ret < 0)
274	    {
275	      state->state = BK7258_AP_STATE_FAILED;
276	      state->error = BK7258_AP_ERROR_CPU2_PROBE;
277	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
278	      goto parked;
279	    }
280	#endif
281	
282	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
283	  ret = bk7258_ap_smp_scheduler_selftest(
284	    BK7258_AP_SMP_DEFAULT_TIMEOUT_MS);
285	  if (ret < 0)
286	    {
287	      state->state = BK7258_AP_STATE_FAILED;
288	      state->error = BK7258_AP_ERROR_CPU2_SMP_SCHEDULER;
289	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
290	      goto parked;
291	    }
292	#endif
293	
294	#ifdef CONFIG_BK7258_AP_SMP_CPU1_AFFINITY
295	#  ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
296	  ret = bk7258_ap_smp_affinity_selftest(
297	    BK7258_AP_SEM_WAKE_TIMEOUT_MS);
298	#  else
299	  ret = bk7258_ap_smp_affinity_selftest(
300	    BK7258_AP_AFFINITY_TIMEOUT_MS);
301	#  endif
302	  if (ret < 0)
303	    {
304	      state->state = BK7258_AP_STATE_FAILED;
305	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
306	      state->error = BK7258_AP_ERROR_CPU2_SEM_WAKE;
307	#else
308	      state->error = BK7258_AP_ERROR_CPU2_AFFINITY;
309	#endif
310	      bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
311	      goto parked;
312	    }
313	#endif
314	
315	  state->error      = BK7258_AP_ERROR_NONE;
316	  state->last_event = BK7258_AP_EVENT_READY;
317	  state->state      = BK7258_AP_STATE_READY;
318	  __asm volatile ("dmb sy" ::: "memory");
319	  bk7258_ap_mbox_send(BK7258_AP_EVENT_READY);
320	
321	  for (; ; )
322	    {
323	      event = bk7258_ap_mbox_receive();
324	      if (event != BK7258_AP_EVENT_NONE)
325	        {
326	          state->last_event = event;
327	        }
328	
329	      if (event == BK7258_AP_EVENT_STOP ||
330	          state->command == BK7258_AP_COMMAND_STOP)
331	        {
332	          state->state = BK7258_AP_STATE_STOPPING;
333	          __asm volatile ("dmb sy" ::: "memory");
334	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
335	          ret = bk7258_ap_smp_secondary_stop(
336	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
337	#else
338	          ret = bk7258_cpu2_probe_stop(
339	            BK7258_CPU2_PROBE_STOP_TIMEOUT_MS);
340	#endif
341	          if (ret < 0)
342	            {
343	#ifdef CONFIG_BK7258_AP_SMP_BOOTSTRAP
344	              state->error = BK7258_AP_ERROR_CPU2_SMP_BOOTSTRAP;
345	#else
346	              state->error = BK7258_AP_ERROR_CPU2_PROBE;
347	#endif
348	              state->state = BK7258_AP_STATE_FAILED;
349	              state->last_event = BK7258_AP_EVENT_FAILED;
350	              bk7258_ap_mbox_send(BK7258_AP_EVENT_FAILED);
351	              break;
352	            }
353	
354	          state->state = BK7258_AP_STATE_STOPPED;
355	          state->last_event = BK7258_AP_EVENT_STOPPED;
356	          bk7258_ap_mbox_send(BK7258_AP_EVENT_STOPPED);
357	          break;
358	        }
359	
360	#ifdef CONFIG_BK7258_AP_IPI
361	      if (event == BK7258_AP_EVENT_IPI_TEST ||
362	          state->command == BK7258_AP_COMMAND_IPI_TEST)
363	        {
364	          volatile struct bk7258_ap_ipi_state_s *ipi =
365	            bk7258_ap_ipi_state();
366	
367	          state->command = BK7258_AP_COMMAND_NONE;
368	          __asm volatile ("dmb sy" ::: "memory");
369	          ret = bk7258_ap_ipi_selftest(ipi->requested_count,
370	                                       ipi->timeout_ms);
371	          if (ret < 0)
372	            {
373	              state->error = BK7258_AP_ERROR_CPU2_IPI;
374	              state->last_event = BK7258_AP_EVENT_IPI_TEST_FAILED;
375	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_FAILED);
376	            }
377	          else
378	            {
379	              state->error = BK7258_AP_ERROR_NONE;
380	              state->last_event = BK7258_AP_EVENT_IPI_TEST_PASSED;
381	              bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST_PASSED);
382	            }
383	        }
384	#endif
385	
386	      state->heartbeat++;
387	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
388	      smp->sleep_enter_count++;
389	#endif
390	      __asm volatile ("dmb sy; sev" ::: "memory");
391	      nxsig_usleep(BK7258_AP_HEARTBEAT_US);
392	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
393	      smp->sleep_return_count++;
394	      __asm volatile ("dmb sy" ::: "memory");
395	#endif
396	    }
397	
398	parked:
399	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
400	  for (; ; )
401	    {
402	      __asm volatile ("wfe");
403	    }
404	
405	  return 0;
406	}
