26	/****************************************************************************
27	 * External Function Prototypes
28	 ****************************************************************************/
29	
30	/* These four routines are provided by the pinned Beken CP SDK archives. */
31	
32	extern void sys_drv_set_cpu1_pwr_dw(uint32_t is_pwr_down);
33	extern void sys_drv_set_cpu1_rxevt_sel(uint32_t value);
34	extern void sys_drv_set_cpu1_boot_address_offset(uint32_t address_offset);
35	extern void sys_drv_set_cpu1_reset(uint32_t reset_value);
36	
37	/****************************************************************************
38	 * Private Data
39	 ****************************************************************************/
40	
41	/* Singleton SoC CPU1 control state.  The mutex serializes SYS register and
42	 * shared-state transitions issued by concurrent NSH callers.
43	 */
44	
45	static mutex_t g_bk7258_ap_lock = NXMUTEX_INITIALIZER;
46	static bool g_bk7258_ap_initialized;
47	
48	/****************************************************************************
49	 * Private Functions
50	 ****************************************************************************/
51	
52	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
53	{
54	  return (volatile uint32_t *)(uintptr_t)base;
55	}
56	
57	static void bk7258_cpu2_force_reset(void)
58	{
59	  volatile uint32_t *control =
60	    (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
61	
62	  *control &= ~BK7258_SYS_CPU2_RESET;
63	  __asm volatile ("dsb sy; isb sy" ::: "memory");
64	}
65	
66	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
67	{
68	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
69	  __asm volatile ("dsb sy" ::: "memory");
70	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
71	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
72	  __asm volatile ("dsb sy" ::: "memory");
73	}
74	
75	static void bk7258_ap_mbox_initialize(void)
76	{
77	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
78	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
79	
80	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
81	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
82	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
83	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
84	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
85	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
86	
87	  bk7258_ap_mbox_ack(to_ap);
88	  bk7258_ap_mbox_ack(to_cp);
89	}
90	
91	static void bk7258_ap_mbox_send(uint32_t event)
92	{
93	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
94	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
95	
96	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
97	       BK7258_MBOX_BOX0_BIT) != 0)
98	    {
99	      bk7258_ap_mbox_ack(mbox);
100	    }
101	
102	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
103	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
104	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
105	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
106	  __asm volatile ("dmb sy" ::: "memory");
107	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
108	  state->cp_to_ap_doorbells++;
109	  __asm volatile ("dsb sy; sev" ::: "memory");
110	}
111	
112	static uint32_t bk7258_ap_mbox_receive(void)
113	{
114	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
115	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
116	  uint32_t event = BK7258_AP_EVENT_NONE;
117	
118	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
119	       BK7258_MBOX_BOX0_BIT) != 0)
120	    {
121	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
122	          BK7258_AP_DOORBELL_MAGIC &&
123	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
124	        {
125	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
126	        }
127	
128	      bk7258_ap_mbox_ack(mbox);
129	    }
130	
131	  return event;
132	}
133	
134	static void bk7258_ap_state_prepare(void)
135	{
136	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
137	  uint32_t generation = 1;
138	
139	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
140	      state->version == BK7258_AP_BOOT_STATE_VERSION)
141	    {
142	      generation = state->generation + 1;
143	    }
144	
145	  memset((void *)(uintptr_t)state, 0,
146	         sizeof(struct bk7258_ap_boot_state_s));
147	  bk7258_ap_fault_state()->magic = 0;
148	  bk7258_cpu2_probe_state()->magic = 0;
149	  bk7258_ap_ipi_state()->magic = 0;
150	  bk7258_ap_smp_state()->magic = 0;
151	  bk7258_ap_affinity_state()->magic = 0;
152	  bk7258_ap_sem_wake_state()->magic = 0;
153	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
154	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
155	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
156	  state->generation  = generation;
157	  state->command     = BK7258_AP_COMMAND_START;
158	  state->state       = BK7258_AP_STATE_STARTING;
159	  state->ram_start   = BK7258_AP_RAM_BASE;
160	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
161	  state->flash_start = BK7258_AP_FLASH_ADDR;
162	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
163	  __asm volatile ("dmb sy" ::: "memory");
164	}
165	
166	static bool bk7258_ap_scheduler_online(void)
167	{
168	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
169	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
170	    bk7258_cpu2_probe_state();
171	
172	  __asm volatile ("dmb sy" ::: "memory");
173	  return cpu2->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
174	         cpu2->version == BK7258_CPU2_PROBE_STATE_VERSION &&
175	         cpu2->size == sizeof(struct bk7258_cpu2_probe_state_s) &&
176	         cpu2->generation == state->generation &&
177	         cpu2->state == BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE &&
178	         cpu2->online_mask == 0x3u;
179	}
180	
181	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
182	{
183	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
184	  uint32_t elapsed;
185	  uint32_t event;
186	
187	  if (timeout_ms == 0)
188	    {
189	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
190	    }
191	
192	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
193	    {
194	      event = bk7258_ap_mbox_receive();
195	      if (event != BK7258_AP_EVENT_NONE)
196	        {
197	          state->last_event = event;
198	        }
199	
200	      __asm volatile ("dmb sy" ::: "memory");
201	      if (state->state == wanted)
202	        {
203	          return OK;
204	        }
205	
206	      if (state->state == BK7258_AP_STATE_FAILED)
207	        {
208	          return -EIO;
209	        }
210	
211	      nxsig_usleep(1000);
212	    }
213	
214	  return -ETIMEDOUT;
215	}
216	
217	static int bk7258_ap_start_locked(uint32_t timeout_ms)
218	{
219	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
220	  int ret;
221	
222	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
223	      (state->state == BK7258_AP_STATE_READY ||
224	       state->state == BK7258_AP_STATE_STARTING))
225	    {
226	      return -EBUSY;
227	    }
228	
229	  /* Hold CPU1 while replacing shared state and the boot address. */
230	
231	  sys_drv_set_cpu1_reset(0);
232	  __asm volatile ("dsb sy; isb sy" ::: "memory");
233	  bk7258_cpu2_force_reset();
234	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
235	  bk7258_ap_mbox_initialize();
236	  bk7258_ap_state_prepare();
237	
238	  /* Exact BK7258 CPU1 release order from the CP SDK. */
239	
240	  sys_drv_set_cpu1_pwr_dw(0);
241	  sys_drv_set_cpu1_rxevt_sel(1);
242	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
243	  __asm volatile ("dsb sy; isb sy" ::: "memory");
244	  sys_drv_set_cpu1_reset(1);
245	  __asm volatile ("dsb sy; sev" ::: "memory");
246	
247	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
248	  if (ret < 0)
249	    {
250	      sys_drv_set_cpu1_reset(0);
251	      __asm volatile ("dsb sy; isb sy" ::: "memory");
252	      bk7258_cpu2_force_reset();
253	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
254	      sys_drv_set_cpu1_pwr_dw(1);
255	
256	      if (state->state != BK7258_AP_STATE_FAILED)
257	        {
258	          state->error = BK7258_AP_ERROR_TIMEOUT;
259	        }
260	
261	      state->command = BK7258_AP_COMMAND_NONE;
262	      state->state = BK7258_AP_STATE_FAILED;
263	      state->last_event = BK7258_AP_EVENT_FAILED;
264	      __asm volatile ("dmb sy" ::: "memory");
265	    }
266	
267	  return ret;
268	}
269	
270	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
271	{
272	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
273	  int ret = OK;
274	
275	  if (bk7258_ap_scheduler_online())
276	    {
277	      return -ENOTSUP;
278	    }
279	
280	  if (state->state == BK7258_AP_STATE_READY ||
281	      state->state == BK7258_AP_STATE_STARTING)
282	    {
283	      state->command = BK7258_AP_COMMAND_STOP;
284	      __asm volatile ("dmb sy" ::: "memory");
285	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
286	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
287	    }
288	
289	  /* A timeout still ends in a deterministic forced stop of both AP cores. */
290	
291	  sys_drv_set_cpu1_reset(0);
292	  __asm volatile ("dsb sy; isb sy" ::: "memory");
293	  bk7258_cpu2_force_reset();
294	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
295	  sys_drv_set_cpu1_pwr_dw(1);
296	
297	  if (ret < 0 && state->state != BK7258_AP_STATE_FAILED)
298	    {
299	      state->error = BK7258_AP_ERROR_TIMEOUT;
300	    }
301	
302	  state->command = BK7258_AP_COMMAND_NONE;
303	  state->state = BK7258_AP_STATE_STOPPED;
304	  state->last_event = BK7258_AP_EVENT_STOPPED;
305	  __asm volatile ("dmb sy" ::: "memory");
306	  return ret;
307	}
