309	/****************************************************************************
310	 * Public Functions
311	 ****************************************************************************/
312	
313	int bk7258_ap_control_initialize(void)
314	{
315	  int ret;
316	
317	  ret = nxmutex_lock(&g_bk7258_ap_lock);
318	  if (ret < 0)
319	    {
320	      return ret;
321	    }
322	
323	  if (!g_bk7258_ap_initialized)
324	    {
325	      bk7258_ap_mbox_initialize();
326	      g_bk7258_ap_initialized = true;
327	    }
328	
329	  nxmutex_unlock(&g_bk7258_ap_lock);
330	  return OK;
331	}
332	
333	int bk7258_ap_start(uint32_t timeout_ms)
334	{
335	  int ret;
336	
337	  ret = nxmutex_lock(&g_bk7258_ap_lock);
338	  if (ret < 0)
339	    {
340	      return ret;
341	    }
342	
343	  if (!g_bk7258_ap_initialized)
344	    {
345	      bk7258_ap_mbox_initialize();
346	      g_bk7258_ap_initialized = true;
347	    }
348	
349	  ret = bk7258_ap_start_locked(timeout_ms);
350	  nxmutex_unlock(&g_bk7258_ap_lock);
351	  return ret;
352	}
353	
354	int bk7258_ap_stop(uint32_t timeout_ms)
355	{
356	  int ret;
357	
358	  ret = nxmutex_lock(&g_bk7258_ap_lock);
359	  if (ret < 0)
360	    {
361	      return ret;
362	    }
363	
364	  ret = bk7258_ap_stop_locked(timeout_ms);
365	  nxmutex_unlock(&g_bk7258_ap_lock);
366	  return ret;
367	}
368	
369	int bk7258_ap_restart(uint32_t timeout_ms)
370	{
371	  int ret;
372	
373	  ret = nxmutex_lock(&g_bk7258_ap_lock);
374	  if (ret < 0)
375	    {
376	      return ret;
377	    }
378	
379	  ret = bk7258_ap_stop_locked(timeout_ms);
380	  if (ret == OK || ret == -ETIMEDOUT)
381	    {
382	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
383	      ret = bk7258_ap_start_locked(timeout_ms);
384	    }
385	
386	  nxmutex_unlock(&g_bk7258_ap_lock);
387	  return ret;
388	}
389	
390	int bk7258_ap_ipi_test(uint32_t count, uint32_t timeout_ms)
391	{
392	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
393	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
394	  uint32_t elapsed;
395	  uint32_t event;
396	  int ret;
397	
398	  if (count == 0)
399	    {
400	      count = BK7258_AP_IPI_DEFAULT_COUNT;
401	    }
402	
403	  if (timeout_ms == 0)
404	    {
405	      timeout_ms = BK7258_AP_IPI_DEFAULT_TIMEOUT_MS;
406	    }
407	
408	  if (count > BK7258_AP_IPI_MAX_COUNT)
409	    {
410	      return -ERANGE;
411	    }
412	
413	  ret = nxmutex_lock(&g_bk7258_ap_lock);
414	  if (ret < 0)
415	    {
416	      return ret;
417	    }
418	
419	  __asm volatile ("dmb sy" ::: "memory");
420	  if (bk7258_ap_scheduler_online())
421	    {
422	      ret = -ENOTSUP;
423	      goto out;
424	    }
425	
426	  if (state->state != BK7258_AP_STATE_READY ||
427	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
428	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
429	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
430	      ipi->generation != state->generation)
431	    {
432	      ret = -EAGAIN;
433	      goto out;
434	    }
435	
436	  if (ipi->state == BK7258_AP_IPI_STATE_RUNNING ||
437	      ipi->state == BK7258_AP_IPI_STATE_REQUESTED)
438	    {
439	      ret = -EBUSY;
440	      goto out;
441	    }
442	
443	  ipi->requested_count = count;
444	  ipi->completed_count = 0;
445	  ipi->timeout_ms = timeout_ms;
446	  ipi->error = BK7258_AP_IPI_ERROR_NONE;
447	  ipi->state = BK7258_AP_IPI_STATE_REQUESTED;
448	  state->command = BK7258_AP_COMMAND_IPI_TEST;
449	  __asm volatile ("dmb sy" ::: "memory");
450	  bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST);
451	
452	  ret = -ETIMEDOUT;
453	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
454	    {
455	      event = bk7258_ap_mbox_receive();
456	      if (event != BK7258_AP_EVENT_NONE)
457	        {
458	          state->last_event = event;
459	        }
460	
461	      __asm volatile ("dmb sy" ::: "memory");
462	      if (ipi->state == BK7258_AP_IPI_STATE_PASSED)
463	        {
464	          ret = OK;
465	          break;
466	        }
467	
468	      if (ipi->state == BK7258_AP_IPI_STATE_FAILED ||
469	          state->state == BK7258_AP_STATE_FAILED)
470	        {
471	          ret = -EIO;
472	          break;
473	        }
474	
475	      nxsig_usleep(1000);
476	    }
477	
478	out:
479	  nxmutex_unlock(&g_bk7258_ap_lock);
480	  return ret;
481	}
