483	void bk7258_ap_get_status(struct bk7258_ap_boot_state_s *status)
484	{
485	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
486	
487	  if (status != NULL)
488	    {
489	      __asm volatile ("dmb sy" ::: "memory");
490	      memcpy(status, (const void *)(uintptr_t)state, sizeof(*status));
491	      __asm volatile ("dmb sy" ::: "memory");
492	    }
493	}
