123	static void bk7258_cpu2_fpu_initialize(void)
124	{
125	  /* Match the primary AP core before CPU2 can enter exception_common. */
126	
127	  BK7258_SCB_CPACR &= ~((3u << 20) | (3u << 22));
128	  __asm volatile ("dsb sy; isb sy" ::: "memory");
129	  BK7258_FPU_FPCCR &= ~((1u << 31) | (1u << 30) | (1u << 29));
130	  BK7258_SCB_CPACR |= ((3u << 20) | (3u << 22));
131	  __asm volatile ("dsb sy; isb sy" ::: "memory");
132	}
