156	static int bk7258_cpu2_wait(uint32_t wanted, uint32_t timeout_ms)
157	{
158	  volatile struct bk7258_cpu2_probe_state_s *state =
159	    bk7258_cpu2_probe_state();
160	  uint32_t current;
161	  uint32_t elapsed;
162	
163	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
164	    {
165	      current = state->state;
166	      __asm volatile ("dmb sy" ::: "memory");
167	      if (current == wanted)
168	        {
169	          return OK;
170	        }
171	
172	      if (current == BK7258_CPU2_PROBE_STATE_FAILED)
173	        {
174	          return -EIO;
175	        }
176	
177	      up_mdelay(1);
178	    }
179	
180	  return -ETIMEDOUT;
181	}
