299	static int bk7258_ap_sem_waiter_blocked(
300	  volatile struct bk7258_ap_sem_wake_state_s *state,
301	  pthread_t thread, cpu_set_t cpuset)
302	{
303	  FAR struct tcb_s *tcb;
304	  irqstate_t flags;
305	  int value = 0;
306	  int ret;
307	  int blocked;
308	
309	  tcb = nxsched_get_tcb((pid_t)thread);
310	  if (tcb == NULL)
311	    {
312	      return 0;
313	    }
314	
315	  flags = enter_critical_section();
316	  ret = nxsem_get_value(&g_bk7258_ap_cpu1_sem, &value);
317	  state->waiter_sem_value = (int32_t)value;
318	  blocked = ret >= 0 &&
319	            state->task_id == (uint32_t)thread &&
320	            tcb->task_state == TSTATE_WAIT_SEM &&
321	            tcb->waitobj == (FAR void *)&g_bk7258_ap_cpu1_sem &&
322	            value == -1 &&
323	            tcb->affinity == cpuset;
324	  leave_critical_section(flags);
325	  nxsched_put_tcb(tcb);
326	  __asm volatile ("dmb sy" ::: "memory");
327	  return blocked;
328	}
329	#endif
