331	static FAR void *bk7258_ap_cpu1_affinity_task(FAR void *arg)
332	{
333	  volatile struct bk7258_ap_affinity_state_s *state = arg;
334	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
335	  volatile struct bk7258_ap_sem_wake_state_s *sem_state =
336	    bk7258_ap_sem_wake_state();
337	  uint32_t wait_state;
338	#endif
339	  cpu_set_t observed = 0;
340	  pthread_t self = pthread_self();
341	  int ret;
342	
343	  if (state == NULL)
344	    {
345	      return NULL;
346	    }
347	
348	  state->task_id = (uint32_t)self;
349	  state->task_cpu = (uint32_t)up_cpu_index();
350	  state->task_started++;
351	  __asm volatile ("dmb sy" ::: "memory");
352	
353	  if (state->magic != BK7258_AP_AFFINITY_STATE_MAGIC ||
354	      state->version != BK7258_AP_AFFINITY_STATE_VERSION ||
355	      state->size != sizeof(struct bk7258_ap_affinity_state_s) ||
356	      state->generation != bk7258_ap_boot_state()->generation ||
357	      state->state != BK7258_AP_AFFINITY_STATE_DISPATCHING)
358	    {
359	      bk7258_ap_affinity_fail(state,
360	                             BK7258_AP_AFFINITY_ERROR_BAD_STATE);
361	      goto done;
362	    }
363	
364	  state->state = BK7258_AP_AFFINITY_STATE_RUNNING;
365	  __asm volatile ("dmb sy" ::: "memory");
366	
367	  ret = pthread_getaffinity_np(self, sizeof(observed), &observed);
368	  state->observed_mask = (uint32_t)observed;
369	
370	  if (ret != 0)
371	    {
372	      bk7258_ap_affinity_fail(state,
373	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
374	    }
375	  else if (state->task_cpu != BK7258_AP_SECONDARY_CPU)
376	    {
377	      bk7258_ap_affinity_fail(state,
378	                             BK7258_AP_AFFINITY_ERROR_BAD_CPU);
379	    }
380	  else if (state->observed_mask != state->requested_mask)
381	    {
382	      bk7258_ap_affinity_fail(state,
383	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
384	    }
385	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
386	  else if (sem_state->magic != BK7258_AP_SEM_WAKE_STATE_MAGIC ||
387	           sem_state->version != BK7258_AP_SEM_WAKE_STATE_VERSION ||
388	           sem_state->size != sizeof(struct bk7258_ap_sem_wake_state_s) ||
389	           sem_state->generation != state->generation ||
390	           sem_state->state != BK7258_AP_SEM_WAKE_STATE_INITIALIZING ||
391	           sem_state->error != BK7258_AP_SEM_WAKE_ERROR_NONE)
392	    {
393	      bk7258_ap_sem_wake_fail(sem_state,
394	                             BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
395	    }
396	  else
397	    {
398	      sem_state->task_id = (uint32_t)self;
399	      sem_state->wait_entered = 1;
400	      sem_state->state = BK7258_AP_SEM_WAKE_STATE_WAITING;
401	      __asm volatile ("dmb sy; sev" ::: "memory");
402	
403	      ret = nxsem_wait_uninterruptible(&g_bk7258_ap_cpu1_sem);
404	      __asm volatile ("dmb sy" ::: "memory");
405	      wait_state = sem_state->state;
406	      sem_state->wait_result = (int32_t)ret;
407	      sem_state->wait_returned = 1;
408	      sem_state->wake_cpu = (uint32_t)up_cpu_index();
409	      __asm volatile ("dmb sy" ::: "memory");
410	
411	      if (ret < 0)
412	        {
413	          bk7258_ap_sem_wake_fail(sem_state,
414	                                 BK7258_AP_SEM_WAKE_ERROR_SEM_WAIT);
415	        }
416	      else if (wait_state != BK7258_AP_SEM_WAKE_STATE_POSTED)
417	        {
418	          bk7258_ap_sem_wake_fail(sem_state,
419	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
420	        }
421	      else if (sem_state->wake_cpu != BK7258_AP_SECONDARY_CPU)
422	        {
423	          bk7258_ap_sem_wake_fail(sem_state,
424	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_CPU);
425	        }
426	      else
427	        {
428	          sem_state->state = BK7258_AP_SEM_WAKE_STATE_WOKEN;
429	          __asm volatile ("dmb sy; sev" ::: "memory");
430	        }
431	    }
432	#endif
433	
434	done:
435	  state->task_completed++;
436	  __asm volatile ("dmb sy; sev" ::: "memory");
437	  return NULL;
438	}
439	#endif
