441	static void __attribute__((noinline, noreturn, used))
442	bk7258_ap_secondary_scheduler_entry(void)
443	{
444	  volatile struct bk7258_cpu2_probe_state_s *state =
445	    bk7258_cpu2_probe_state();
446	  uint32_t control;
447	  uint32_t msp;
448	
449	  arm_initialize_stack();
450	  __asm volatile ("mrs %0, msp" : "=r" (msp));
451	  __asm volatile ("mrs %0, control" : "=r" (control));
452	
453	  state->runtime_msp = msp;
454	  state->control = control;
455	  state->online_mask = BK7258_AP_ONLINE_MASK;
456	  state->secondary_ready = 1;
457	
458	#ifdef CONFIG_SCHED_INSTRUMENTATION
459	  sched_note_cpu_started(this_task());
460	#endif
461	
462	  bk7258_ap_ipi_mark_scheduler_online();
463	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
464	  state->state = BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE;
465	  __asm volatile ("dmb sy; sev" ::: "memory");
466	
467	  nx_idle_trampoline();
468	
469	  bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
470	  for (; ; )
471	    {
472	      __asm volatile ("wfe");
473	    }
474	}
