477	bk7258_ap_secondary_enter_scheduler(
478	  uint32_t stack_top __attribute__((unused)))
479	{
480	  __asm volatile
481	    (
482	      "msr msp, r0\n"
483	      "dsb sy\n"
484	      "isb sy\n"
485	      "b bk7258_ap_secondary_scheduler_entry\n"
486	    );
487	}
488	#endif
