490	static void __attribute__((noinline, noreturn, used))
491	bk7258_ap_secondary_bootstrap(void)
492	{
493	  volatile struct bk7258_cpu2_probe_state_s *state;
494	
495	  bk7258_cpu2_fpu_initialize();
496	  state = bk7258_cpu2_probe_state();
497	  uint32_t control;
498	  uint32_t msp;
499	
500	  __asm volatile ("mrs %0, msp" : "=r" (msp));
501	  __asm volatile ("mrs %0, control" : "=r" (control));
502	
503	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
504	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
505	  state->runtime_vtor = BK7258_SCB_VTOR;
506	  state->runtime_msp = msp;
507	  state->control = control;
508	  state->boot_count++;
509	  __asm volatile ("dmb sy" ::: "memory");
510	
511	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
512	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
513	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
514	    {
515	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
516	      goto parked;
517	    }
518	
519	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
520	  __asm volatile ("dmb sy" ::: "memory");
521	
522	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
523	        BK7258_CPU2_LOCAL_CORE_ID ||
524	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
525	    {
526	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
527	      goto parked;
528	    }
529	
530	  if (state->runtime_vtor !=
531	      (uint32_t)(uintptr_t)__vector_core1_table)
532	    {
533	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
534	      goto parked;
535	    }
536	
537	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
538	      msp > BK7258_CPU2_BOOT_STACK_TOP)
539	    {
540	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
541	      goto parked;
542	    }
543	
544	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
545	      state->idle_stack_base >= state->idle_stack_top ||
546	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
547	    {
548	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
549	      goto parked;
550	    }
551	
552	#ifdef CONFIG_BK7258_AP_IPI
553	  if (bk7258_ap_ipi_secondary_initialize() < 0)
554	    {
555	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
556	      goto parked;
557	    }
558	#endif
559	
560	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
561	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
562	  state->online_mask = BK7258_AP_PRIMARY_MASK;
563	
564	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
565	  state->secondary_ready = 0;
566	  __asm volatile ("dmb sy" ::: "memory");
567	
568	  if (bk7258_cpu2_scheduler_irq_initialize() < 0)
569	    {
570	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
571	      goto parked;
572	    }
573	
574	  bk7258_ap_secondary_enter_scheduler(state->idle_stack_top);
575	#else
576	  state->secondary_ready = 1;
577	  __asm volatile ("dmb sy" ::: "memory");
578	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
579	  __asm volatile ("dmb sy; sev" ::: "memory");
580	
581	#  ifdef CONFIG_BK7258_AP_IPI
582	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
583	#  endif
584	
585	  for (; ; )
586	    {
587	      __asm volatile ("dmb sy" ::: "memory");
588	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
589	        {
590	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
591	          state->secondary_ready = 0;
592	          __asm volatile ("dmb sy" ::: "memory");
593	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
594	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
595	          __asm volatile ("dmb sy; sev" ::: "memory");
596	          goto parked;
597	        }
598	
599	      state->heartbeat++;
600	#  ifdef CONFIG_BK7258_AP_IPI
601	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
602	#  else
603	      __asm volatile ("dmb sy; wfe" ::: "memory");
604	#  endif
605	    }
606	#endif
607	
608	parked:
609	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
610	  for (; ; )
611	    {
612	      __asm volatile ("wfe");
613	    }
614	}
