616	static void __attribute__((naked, noreturn, used))
617	bk7258_ap_secondary_reset(void)
618	{
619	  __asm volatile
620	    (
621	      "cpsid i\n"
622	      "movs r0, #0\n"
623	      "msr control, r0\n"
624	      "msr basepri, r0\n"
625	      "msr faultmask, r0\n"
626	      "ldr r0, =0x20000000\n"
627	      "movs r1, #1\n"
628	      "str r1, [r0]\n"
629	      "ldr r0, =__vector_core1_table\n"
630	      "ldr r1, =0xe000ed08\n"
631	      "str r0, [r1]\n"
632	      "dsb sy\n"
633	      "isb sy\n"
634	      "b bk7258_ap_secondary_bootstrap\n"
635	    );
636	}
