638	static void __attribute__((noinline, noreturn, used))
639	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
640	{
641	  volatile struct bk7258_cpu2_probe_state_s *state =
642	    bk7258_cpu2_probe_state();
643	  uintptr_t frame = (uintptr_t)stack;
644	  uint32_t error;
645	
646	  state->fault_exception = exception;
647	  state->fault_hfsr = BK7258_SCB_HFSR;
648	  state->fault_cfsr = BK7258_SCB_CFSR;
649	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
650	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
651	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
652	
653	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
654	      ((frame >= BK7258_CPU2_BOOT_STACK_BASE &&
655	        frame <= BK7258_CPU2_BOOT_STACK_TOP -
656	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
657	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
658	       ||
659	       (frame >= state->idle_stack_base &&
660	        frame <= state->idle_stack_top -
661	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
662	#endif
663	      ))
664	    {
665	      const volatile uint32_t *regs =
666	        (const volatile uint32_t *)frame;
667	
668	      state->fault_lr = regs[5];
669	      state->fault_pc = regs[6];
670	      state->fault_xpsr = regs[7];
671	    }
672	
673	  error = exception == 2u ?
674	    BK7258_CPU2_PROBE_ERROR_NMI :
675	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
676	  bk7258_cpu2_fail(error);
677	
678	  for (; ; )
679	    {
680	      __asm volatile ("wfe");
681	    }
682	}
