684	static void __attribute__((naked, noreturn, used))
685	bk7258_ap_secondary_fault_entry(void)
686	{
687	  __asm volatile
688	    (
689	      "tst lr, #4\n"
690	      "ite eq\n"
691	      "mrseq r0, msp\n"
692	      "mrsne r0, psp\n"
693	      "mrs r1, ipsr\n"
694	      "b bk7258_ap_secondary_fault_handler\n"
695	    );
696	}
