738	int up_cpu_start(int cpu)
739	{
740	  volatile struct bk7258_cpu2_probe_state_s *state =
741	    bk7258_cpu2_probe_state();
742	  volatile uint32_t *control = bk7258_cpu2_control();
743	  struct tcb_s *tcb;
744	  uintptr_t idle_base;
745	  uintptr_t idle_top;
746	  uint32_t generation;
747	  uint32_t value;
748	  int ret;
749	
750	  if (cpu != BK7258_AP_SECONDARY_CPU)
751	    {
752	      return -EINVAL;
753	    }
754	
755	  bk7258_cpu2_hold_reset(state);
756	  up_mdelay(1);
757	
758	  generation = bk7258_ap_boot_state()->generation;
759	  if (generation == 0)
760	    {
761	      generation = 1;
762	    }
763	
764	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
765	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
766	  state->size = sizeof(*state);
767	  state->generation = generation;
768	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
769	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
770	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
771	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
772	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
773	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
774	  state->secondary_entry =
775	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
776	  state->online_mask = BK7258_AP_PRIMARY_MASK;
777	
778	  tcb = current_task(cpu);
779	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
780	      tcb->adj_stack_size == 0)
781	    {
782	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
783	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
784	      return -ENOMEM;
785	    }
786	
787	  idle_base = (uintptr_t)tcb->stack_base_ptr;
788	  idle_top = idle_base + tcb->adj_stack_size;
789	  state->idle_stack_base = (uint32_t)idle_base;
790	  state->idle_stack_top = (uint32_t)idle_top;
791	
792	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
793	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
794	    {
795	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
796	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
797	      return -ENOMEM;
798	    }
799	
800	  value = *control;
801	  state->control_before = value;
802	  value &= ~(BK7258_SYS_CPU2_RESET |
803	             BK7258_SYS_CPU2_POWER_DOWN |
804	             BK7258_SYS_CPU2_HALT |
805	             BK7258_SYS_CPU2_RXEVT_SEL |
806	             BK7258_SYS_CPU2_BOOT_MASK);
807	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
808	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
809	  *control = value;
810	  __asm volatile ("dsb sy; isb sy" ::: "memory");
811	
812	  state->control_after = value;
813	  __asm volatile ("dmb sy" ::: "memory");
814	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
815	  __asm volatile ("dmb sy" ::: "memory");
816	
817	#ifdef CONFIG_BK7258_AP_IPI
818	  ret = bk7258_ap_ipi_primary_initialize();
819	  if (ret < 0)
820	    {
821	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
822	      return ret;
823	    }
824	#endif
825	
826	  value |= BK7258_SYS_CPU2_RESET;
827	  *control = value;
828	  state->control_after = value;
829	  __asm volatile ("dsb sy; sev" ::: "memory");
830	
831	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
832	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE,
833	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
834	#else
835	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
836	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
837	#endif
838	  if (ret < 0)
839	    {
840	      bk7258_cpu2_hold_reset(state);
841	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
842	        {
843	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
844	        }
845	    }
846	
847	  return ret;
848	}
