899	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
900	int bk7258_ap_smp_scheduler_selftest(uint32_t timeout_ms)
901	{
902	  volatile struct bk7258_ap_smp_state_s *state = bk7258_ap_smp_state();
903	  uint32_t elapsed;
904	  int cpu;
905	  int ret;
906	
907	  if (timeout_ms == 0)
908	    {
909	      timeout_ms = BK7258_AP_SMP_DEFAULT_TIMEOUT_MS;
910	    }
911	
912	  if (state->magic != BK7258_AP_SMP_STATE_MAGIC ||
913	      state->version != BK7258_AP_SMP_STATE_VERSION ||
914	      state->size != sizeof(struct bk7258_ap_smp_state_s) ||
915	      state->generation != bk7258_ap_boot_state()->generation ||
916	      state->state != BK7258_AP_SMP_STATE_ONLINE ||
917	      state->online_mask != BK7258_AP_ONLINE_MASK)
918	    {
919	      return -EAGAIN;
920	    }
921	
922	  state->error = BK7258_AP_SMP_ERROR_NONE;
923	  state->requested_count = 2;
924	  state->completed_count = 0;
925	  state->test_runs++;
926	  state->last_callback_cpu = UINT32_MAX;
927	
928	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
929	    {
930	      state->tx_count[cpu] = 0;
931	      state->rx_count[cpu] = 0;
932	      state->coalesced_count[cpu] = 0;
933	      state->send_failures[cpu] = 0;
934	      state->call_handler_count[cpu] = 0;
935	      state->delivered_handler_count[cpu] = 0;
936	      state->callback_count[cpu] = 0;
937	      state->last_command[cpu] = 0;
938	    }
939	
940	  __asm volatile ("dmb sy" ::: "memory");
941	  state->state = BK7258_AP_SMP_STATE_TESTING;
942	  __asm volatile ("dmb sy" ::: "memory");
943	
944	  nxsched_smp_call_init(&g_bk7258_ap_smp_forward_call,
945	                        bk7258_ap_smp_secondary_callback,
946	                        (FAR void *)state);
947	  ret = nxsched_smp_call_single_async(BK7258_AP_SECONDARY_CPU,
948	                                      &g_bk7258_ap_smp_forward_call);
949	  if (ret < 0)
950	    {
951	      state->error = BK7258_AP_SMP_ERROR_CALL;
952	      state->state = BK7258_AP_SMP_STATE_FAILED;
953	      __asm volatile ("dmb sy; sev" ::: "memory");
954	      return ret;
955	    }
956	
957	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
958	    {
959	      __asm volatile ("dmb sy" ::: "memory");
960	      if (state->callback_count[BK7258_AP_PRIMARY_CPU] == 1 &&
961	          state->callback_count[BK7258_AP_SECONDARY_CPU] == 1)
962	        {
963	          break;
964	        }
965	
966	      if (state->state == BK7258_AP_SMP_STATE_FAILED)
967	        {
968	          return -EIO;
969	        }
970	
971	      up_mdelay(1);
972	    }
973	
974	  if (elapsed == timeout_ms)
975	    {
976	      state->error = BK7258_AP_SMP_ERROR_TIMEOUT;
977	      state->state = BK7258_AP_SMP_STATE_FAILED;
978	      __asm volatile ("dmb sy; sev" ::: "memory");
979	      return -ETIMEDOUT;
980	    }
981	
982	  if (state->tx_count[0] < 1 || state->tx_count[1] < 1 ||
983	      state->rx_count[0] < 1 || state->rx_count[1] < 1 ||
984	      state->call_handler_count[0] < 1 ||
985	      state->call_handler_count[1] < 1 ||
986	      state->delivered_handler_count[0] < 1 ||
987	      state->delivered_handler_count[1] < 1 ||
988	      state->send_failures[0] != 0 ||
989	      state->send_failures[1] != 0 ||
990	      state->last_callback_cpu != BK7258_AP_PRIMARY_CPU)
991	    {
992	      state->error = BK7258_AP_SMP_ERROR_COUNT_MISMATCH;
993	      state->state = BK7258_AP_SMP_STATE_FAILED;
994	      __asm volatile ("dmb sy; sev" ::: "memory");
995	      return -EIO;
996	    }
997	
998	  state->completed_count = 2;
999	  state->error = BK7258_AP_SMP_ERROR_NONE;
1000	  __asm volatile ("dmb sy" ::: "memory");
1001	  state->state = BK7258_AP_SMP_STATE_PASSED;
1002	  __asm volatile ("dmb sy; sev" ::: "memory");
1003	  return OK;
1004	}
1005	#endif
