1052	  state->cpu2_calls_before = cpu2->smp_call_requests;
1053	  __asm volatile ("dmb sy" ::: "memory");
1054	  state->magic = BK7258_AP_AFFINITY_STATE_MAGIC;
1055	  __asm volatile ("dmb sy" ::: "memory");
1056	
