1385	int bk7258_ap_smp_secondary_stop(uint32_t timeout_ms)
1386	{
1387	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1388	  (void)timeout_ms;
1389	  return -ENOTSUP;
1390	#else
1391	  volatile struct bk7258_cpu2_probe_state_s *state =
1392	    bk7258_cpu2_probe_state();
1393	  int ret = OK;
1394	
1395	  if (timeout_ms == 0)
1396	    {
1397	      timeout_ms = BK7258_CPU2_PROBE_STOP_TIMEOUT_MS;
1398	    }
1399	
1400	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
1401	      state->version != BK7258_CPU2_PROBE_STATE_VERSION)
1402	    {
1403	      ret = -EIO;
1404	    }
1405	  else if (state->state == BK7258_CPU2_PROBE_STATE_SECONDARY_READY ||
1406	           state->state == BK7258_CPU2_PROBE_STATE_BOOTSTRAP ||
1407	           state->state == BK7258_CPU2_PROBE_STATE_STARTING)
1408	    {
1409	      state->command = BK7258_CPU2_PROBE_COMMAND_STOP;
1410	      __asm volatile ("dmb sy" ::: "memory");
1411	#ifdef CONFIG_BK7258_AP_IPI
1412	      ret = bk7258_ap_ipi_wake_secondary();
1413	      if (ret >= 0)
1414	        {
1415	          ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
1416	                                 timeout_ms);
1417	        }
1418	#else
1419	      __asm volatile ("sev" ::: "memory");
1420	      ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_STOPPED,
1421	                             timeout_ms);
1422	#endif
1423	    }
1424	  else if (state->state == BK7258_CPU2_PROBE_STATE_FAILED)
1425	    {
1426	      ret = -EIO;
1427	    }
1428	
1429	  bk7258_cpu2_hold_reset(state);
1430	  state->secondary_ready = 0;
1431	  __asm volatile ("dmb sy" ::: "memory");
1432	
1433	#ifdef CONFIG_BK7258_AP_IPI
1434	  if (ret >= 0)
1435	    {
1436	      bk7258_ap_ipi_mark_stopped();
1437	    }
1438	#endif
1439	
1440	  if (ret < 0 && state->state != BK7258_CPU2_PROBE_STATE_FAILED)
1441	    {
1442	      bk7258_cpu2_fail(ret == -ETIMEDOUT ?
1443	        BK7258_CPU2_PROBE_ERROR_TIMEOUT :
1444	        BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
1445	    }
1446	
1447	  return ret;
1448	#endif
1449	}
