166	static uint32_t apctl_u32(const char *value, uint32_t fallback)
167	{
168	  char *end;
169	  unsigned long parsed;
170	
171	  if (value == NULL)
172	    {
173	      return fallback;
174	    }
175	
176	  parsed = strtoul(value, &end, 0);
177	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
178	    {
179	      return fallback;
180	    }
181	
182	  return (uint32_t)parsed;
183	}
