439	static void apctl_usage(void)
440	{
441	  printf("usage: apctl start|stop|restart|status [timeout_ms]\n");
442	  printf("       apctl cycle [count] [timeout_ms]\n");
443	  printf("       apctl ipitest [count] [timeout_ms]\n");
444	}
445	
446	/****************************************************************************
447	 * Public Functions
448	 ****************************************************************************/
449	
450	int main(int argc, char *argv[])
451	{
452	  uint32_t timeout;
453	  uint32_t count;
454	  uint32_t i;
455	  int ret = -EINVAL;
456	
457	  if (argc < 2)
458	    {
459	      apctl_usage();
460	      return 1;
461	    }
462	
463	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
464	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
465	
466	  if (strcmp(argv[1], "start") == 0)
467	    {
468	      ret = bk7258_ap_start(timeout);
469	    }
470	  else if (strcmp(argv[1], "stop") == 0)
471	    {
472	      ret = bk7258_ap_stop(timeout);
473	    }
474	  else if (strcmp(argv[1], "restart") == 0)
475	    {
476	      ret = bk7258_ap_restart(timeout);
477	    }
478	  else if (strcmp(argv[1], "status") == 0)
479	    {
480	      apctl_status();
481	      return 0;
482	    }
483	  else if (strcmp(argv[1], "ipitest") == 0)
484	    {
485	      count = apctl_u32(argc > 2 ? argv[2] : NULL,
486	                        BK7258_AP_IPI_DEFAULT_COUNT);
487	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
488	                          BK7258_AP_IPI_DEFAULT_TIMEOUT_MS);
489	      ret = bk7258_ap_ipi_test(count, timeout);
490	    }
491	  else if (strcmp(argv[1], "cycle") == 0)
492	    {
493	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
494	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
495	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
496	
497	      /* Normalize the entry state so every iteration is one complete
498	       * start/stop generation, including when cycle is invoked from READY.
499	       */
500	
501	      ret = bk7258_ap_stop(timeout);
502	      for (i = 0; ret >= 0 && i < count; i++)
503	        {
504	          ret = bk7258_ap_start(timeout);
505	          if (ret < 0)
506	            {
507	              break;
508	            }
509	
510	          apctl_status();
511	          ret = bk7258_ap_stop(timeout);
512	        }
513	    }
514	  else
515	    {
516	      apctl_usage();
517	      return 1;
518	    }
519	
520	  apctl_status();
521	  if (ret < 0)
522	    {
523	      if (ret == -ENOTSUP)
524	        {
525	          fprintf(stderr,
526	                  "apctl: %s is disabled while AP scheduler-online mode "
527	                  "is active\n", argv[1]);
528	        }
529	      else
530	        {
531	          fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
532	        }
533	
534	      return 1;
535	    }
536	
537	  return 0;
538	}
