40	/****************************************************************************
41	 * Name: nxsched_get_tcb/nxsched_put_tcb/nxsched_get_tcb_by_index
42	 *
43	 * Description:
44	 *   Given a task ID,
45	 *   Obtain a valid TCB and increment the corresponding reference count to
46	 *   prevent it from being released. nxsched_get_tcb and nxsched_put_tcb
47	 *   must be called in pairs to ensure the proper release of the TCB.
48	 *
49	 ****************************************************************************/
50	
51	FAR struct tcb_s *nxsched_get_tcb(pid_t pid)
52	{
53	  FAR struct tcb_s *ret = NULL;
54	  irqstate_t flags;
55	  int hash_ndx;
56	
57	  flags = spin_lock_irqsave_notrace(&g_pidhashlock);
58	  if (g_pidhash != NULL && pid >= 0)
59	    {
60	      /* The test and the return setup should be atomic.  This still does
61	       * not provide proper protection if the recipient of the TCB does not
62	       * also protect against the task associated with the TCB from
63	       * terminating asynchronously.
64	       */
65	
66	      /* Get the hash_ndx associated with the pid */
67	
68	      hash_ndx = PIDHASH(pid);
69	
70	      /* Verify that the correct TCB was found. */
71	
72	      if (g_pidhash[hash_ndx] != NULL && pid == g_pidhash[hash_ndx]->pid)
73	        {
74	          /* Return the TCB associated with this pid (if any) */
75	
76	          ret = g_pidhash[hash_ndx];
77	        }
78	    }
79	
80	  if (ret && ret != running_task())
81	    {
82	      if (!up_interrupt_context())
83	        {
84	          /* If we are in the thread context, after obtaining a reference to
85	           * another task, we may not be able to release this reference
86	           * immediately. The purpose of refs is also to prevent the
87	           * situation where this_task is killed and thus unable to release
88	           * the references to other tasks. We need to record the total
89	           * number of references that this_task makes to other tasks.
90	           */
91	
92	          atomic_add(&this_task()->refs, 1);
93	        }
94	
