688	              BK7258_AP_FLASH_OFFSET,
689	              "AP flash must start after LittleFS");
690	static_assert(BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE ==
691	              BK7258_SHARED_RAM_BASE,
692	              "AP RAM must end at the shared page");
693	static_assert(sizeof(struct bk7258_ap_boot_state_s) ==
694	              BK7258_AP_FAULT_STATE_OFFSET,
695	              "AP boot-state ABI must remain 0x80 bytes");
696	static_assert(BK7258_AP_FAULT_STATE_OFFSET +
697	              sizeof(struct bk7258_ap_fault_state_s) <=
698	              BK7258_CP_FAULT_STATE_OFFSET,
