48	/****************************************************************************
49	 * Private Functions
50	 ****************************************************************************/
51	
52	static inline volatile uint32_t *bk7258_ap_mbox(uint32_t base)
53	{
54	  return (volatile uint32_t *)(uintptr_t)base;
55	}
56	
57	static void bk7258_cpu2_force_reset(void)
58	{
59	  volatile uint32_t *control =
60	    (volatile uint32_t *)(uintptr_t)BK7258_SYS_CPU2_CONTROL;
61	
62	  *control &= ~BK7258_SYS_CPU2_RESET;
63	  __asm volatile ("dsb sy; isb sy" ::: "memory");
64	}
65	
66	static void bk7258_ap_mbox_ack(volatile uint32_t *mbox)
67	{
68	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
69	  __asm volatile ("dsb sy" ::: "memory");
70	  mbox[BK7258_MBOX_READY_OFFSET / 4] = 0;
71	  mbox[BK7258_MBOX_CLEAR_OFFSET / 4] = 0;
72	  __asm volatile ("dsb sy" ::: "memory");
73	}
74	
75	static void bk7258_ap_mbox_initialize(void)
76	{
77	  volatile uint32_t *to_ap = bk7258_ap_mbox(BK7258_MBOX0_BASE);
78	  volatile uint32_t *to_cp = bk7258_ap_mbox(BK7258_MBOX1_BASE);
79	
80	  to_ap[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
81	  to_cp[BK7258_MBOX_CLKRST_OFFSET / 4] = 1u;
82	  to_ap[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 0;
83	  to_ap[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 1;
84	  to_cp[BK7258_MBOX_SENDER_OFFSET / 4] = 1u << 1;
85	  to_cp[BK7258_MBOX_RECEIVER_OFFSET / 4] = 1u << 0;
86	
87	  bk7258_ap_mbox_ack(to_ap);
88	  bk7258_ap_mbox_ack(to_cp);
89	}
90	
91	static void bk7258_ap_mbox_send(uint32_t event)
92	{
93	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX0_BASE);
94	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
95	
96	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
97	       BK7258_MBOX_BOX0_BIT) != 0)
98	    {
99	      bk7258_ap_mbox_ack(mbox);
100	    }
101	
102	  mbox[BK7258_MBOX_PARAM0_OFFSET / 4] = BK7258_AP_DOORBELL_MAGIC;
103	  mbox[BK7258_MBOX_PARAM1_OFFSET / 4] = event;
104	  mbox[BK7258_MBOX_PARAM2_OFFSET / 4] = state->generation;
105	  mbox[BK7258_MBOX_PARAM3_OFFSET / 4] = state->command;
106	  __asm volatile ("dmb sy" ::: "memory");
107	  mbox[BK7258_MBOX_READY_OFFSET / 4] = BK7258_MBOX_BOX0_BIT;
108	  state->cp_to_ap_doorbells++;
109	  __asm volatile ("dsb sy; sev" ::: "memory");
110	}
111	
112	static uint32_t bk7258_ap_mbox_receive(void)
113	{
114	  volatile uint32_t *mbox = bk7258_ap_mbox(BK7258_MBOX1_BASE);
115	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
116	  uint32_t event = BK7258_AP_EVENT_NONE;
117	
118	  if ((mbox[BK7258_MBOX_READY_OFFSET / 4] &
119	       BK7258_MBOX_BOX0_BIT) != 0)
120	    {
121	      if (mbox[BK7258_MBOX_PARAM0_OFFSET / 4] ==
122	          BK7258_AP_DOORBELL_MAGIC &&
123	          mbox[BK7258_MBOX_PARAM2_OFFSET / 4] == state->generation)
124	        {
125	          event = mbox[BK7258_MBOX_PARAM1_OFFSET / 4];
126	        }
127	
128	      bk7258_ap_mbox_ack(mbox);
129	    }
130	
131	  return event;
132	}
133	
134	static void bk7258_ap_state_prepare(void)
135	{
136	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
137	  uint32_t generation = 1;
138	
139	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
140	      state->version == BK7258_AP_BOOT_STATE_VERSION)
141	    {
142	      generation = state->generation + 1;
143	    }
144	
145	  memset((void *)(uintptr_t)state, 0,
146	         sizeof(struct bk7258_ap_boot_state_s));
147	  bk7258_ap_fault_state()->magic = 0;
148	  bk7258_cpu2_probe_state()->magic = 0;
149	  bk7258_ap_ipi_state()->magic = 0;
150	  bk7258_ap_smp_state()->magic = 0;
151	  bk7258_ap_affinity_state()->magic = 0;
152	  bk7258_ap_sem_wake_state()->magic = 0;
153	  bk7258_ap_sem_wake_loop_state()->magic = 0;
154	  state->magic       = BK7258_AP_BOOT_STATE_MAGIC;
155	  state->version     = BK7258_AP_BOOT_STATE_VERSION;
156	  state->size        = sizeof(struct bk7258_ap_boot_state_s);
157	  state->generation  = generation;
158	  state->command     = BK7258_AP_COMMAND_START;
159	  state->state       = BK7258_AP_STATE_STARTING;
160	  state->ram_start   = BK7258_AP_RAM_BASE;
161	  state->ram_end     = BK7258_AP_RAM_BASE + BK7258_AP_RAM_SIZE;
162	  state->flash_start = BK7258_AP_FLASH_ADDR;
163	  state->flash_end   = BK7258_AP_FLASH_ADDR + BK7258_AP_FLASH_SIZE;
164	  __asm volatile ("dmb sy" ::: "memory");
165	}
166	
167	static bool bk7258_ap_scheduler_online(void)
168	{
169	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
170	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
171	    bk7258_cpu2_probe_state();
172	
173	  __asm volatile ("dmb sy" ::: "memory");
174	  return cpu2->magic == BK7258_CPU2_PROBE_STATE_MAGIC &&
175	         cpu2->version == BK7258_CPU2_PROBE_STATE_VERSION &&
176	         cpu2->size == sizeof(struct bk7258_cpu2_probe_state_s) &&
177	         cpu2->generation == state->generation &&
178	         cpu2->state == BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE &&
179	         cpu2->online_mask == 0x3u;
180	}
181	
182	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
183	{
184	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
185	  uint32_t elapsed;
186	  uint32_t event;
187	
188	  if (timeout_ms == 0)
189	    {
190	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
191	    }
192	
193	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
194	    {
195	      event = bk7258_ap_mbox_receive();
196	      if (event != BK7258_AP_EVENT_NONE)
197	        {
198	          state->last_event = event;
199	        }
200	
201	      __asm volatile ("dmb sy" ::: "memory");
202	      if (state->state == wanted)
203	        {
204	          return OK;
205	        }
206	
207	      if (state->state == BK7258_AP_STATE_FAILED)
208	        {
209	          return -EIO;
210	        }
211	
212	      nxsig_usleep(1000);
213	    }
214	
215	  return -ETIMEDOUT;
216	}
217	
218	static int bk7258_ap_start_locked(uint32_t timeout_ms)
219	{
220	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
221	  int ret;
222	
223	  if (state->magic == BK7258_AP_BOOT_STATE_MAGIC &&
224	      (state->state == BK7258_AP_STATE_READY ||
225	       state->state == BK7258_AP_STATE_STARTING))
226	    {
227	      return -EBUSY;
228	    }
229	
230	  /* Hold CPU1 while replacing shared state and the boot address. */
231	
232	  sys_drv_set_cpu1_reset(0);
233	  __asm volatile ("dsb sy; isb sy" ::: "memory");
234	  bk7258_cpu2_force_reset();
235	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
236	  bk7258_ap_mbox_initialize();
237	  bk7258_ap_state_prepare();
238	
239	  /* Exact BK7258 CPU1 release order from the CP SDK. */
240	
241	  sys_drv_set_cpu1_pwr_dw(0);
242	  sys_drv_set_cpu1_rxevt_sel(1);
243	  sys_drv_set_cpu1_boot_address_offset(BK7258_AP_FLASH_ADDR >> 8);
244	  __asm volatile ("dsb sy; isb sy" ::: "memory");
245	  sys_drv_set_cpu1_reset(1);
246	  __asm volatile ("dsb sy; sev" ::: "memory");
247	
248	  ret = bk7258_ap_wait(BK7258_AP_STATE_READY, timeout_ms);
249	  if (ret < 0)
250	    {
251	      sys_drv_set_cpu1_reset(0);
252	      __asm volatile ("dsb sy; isb sy" ::: "memory");
253	      bk7258_cpu2_force_reset();
254	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
255	      sys_drv_set_cpu1_pwr_dw(1);
256	
257	      if (state->state != BK7258_AP_STATE_FAILED)
258	        {
259	          state->error = BK7258_AP_ERROR_TIMEOUT;
260	        }
261	
262	      state->command = BK7258_AP_COMMAND_NONE;
263	      state->state = BK7258_AP_STATE_FAILED;
264	      state->last_event = BK7258_AP_EVENT_FAILED;
265	      __asm volatile ("dmb sy" ::: "memory");
266	    }
267	
268	  return ret;
269	}
270	
271	static int bk7258_ap_stop_locked(uint32_t timeout_ms)
272	{
273	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
274	  int ret = OK;
275	
276	  if (bk7258_ap_scheduler_online())
277	    {
278	      return -ENOTSUP;
279	    }
280	
281	  if (state->state == BK7258_AP_STATE_READY ||
282	      state->state == BK7258_AP_STATE_STARTING)
283	    {
284	      state->command = BK7258_AP_COMMAND_STOP;
285	      __asm volatile ("dmb sy" ::: "memory");
286	      bk7258_ap_mbox_send(BK7258_AP_EVENT_STOP);
287	      ret = bk7258_ap_wait(BK7258_AP_STATE_STOPPED, timeout_ms);
288	    }
289	
290	  /* A timeout still ends in a deterministic forced stop of both AP cores. */
291	
292	  sys_drv_set_cpu1_reset(0);
293	  __asm volatile ("dsb sy; isb sy" ::: "memory");
294	  bk7258_cpu2_force_reset();
295	  up_mdelay(BK7258_AP_RESTART_DELAY_MS);
296	  sys_drv_set_cpu1_pwr_dw(1);
297	
298	  if (ret < 0 && state->state != BK7258_AP_STATE_FAILED)
299	    {
300	      state->error = BK7258_AP_ERROR_TIMEOUT;
301	    }
302	
303	  state->command = BK7258_AP_COMMAND_NONE;
304	  state->state = BK7258_AP_STATE_STOPPED;
305	  state->last_event = BK7258_AP_EVENT_STOPPED;
306	  __asm volatile ("dmb sy" ::: "memory");
307	  return ret;
308	}
