313	
314	int bk7258_ap_control_initialize(void)
315	{
316	  int ret;
317	
318	  ret = nxmutex_lock(&g_bk7258_ap_lock);
319	  if (ret < 0)
320	    {
321	      return ret;
322	    }
323	
324	  if (!g_bk7258_ap_initialized)
325	    {
326	      bk7258_ap_mbox_initialize();
327	      g_bk7258_ap_initialized = true;
328	    }
329	
330	  nxmutex_unlock(&g_bk7258_ap_lock);
331	  return OK;
332	}
