334	int bk7258_ap_start(uint32_t timeout_ms)
335	{
336	  int ret;
337	
338	  ret = nxmutex_lock(&g_bk7258_ap_lock);
339	  if (ret < 0)
340	    {
341	      return ret;
342	    }
343	
344	  if (!g_bk7258_ap_initialized)
345	    {
346	      bk7258_ap_mbox_initialize();
347	      g_bk7258_ap_initialized = true;
348	    }
349	
350	  ret = bk7258_ap_start_locked(timeout_ms);
351	  nxmutex_unlock(&g_bk7258_ap_lock);
352	  return ret;
353	}
