355	int bk7258_ap_stop(uint32_t timeout_ms)
356	{
357	  int ret;
358	
359	  ret = nxmutex_lock(&g_bk7258_ap_lock);
360	  if (ret < 0)
361	    {
362	      return ret;
363	    }
364	
365	  ret = bk7258_ap_stop_locked(timeout_ms);
366	  nxmutex_unlock(&g_bk7258_ap_lock);
367	  return ret;
368	}
