370	int bk7258_ap_restart(uint32_t timeout_ms)
371	{
372	  int ret;
373	
374	  ret = nxmutex_lock(&g_bk7258_ap_lock);
375	  if (ret < 0)
376	    {
377	      return ret;
378	    }
379	
380	  ret = bk7258_ap_stop_locked(timeout_ms);
381	  if (ret == OK || ret == -ETIMEDOUT)
382	    {
383	      up_mdelay(BK7258_AP_RESTART_DELAY_MS);
384	      ret = bk7258_ap_start_locked(timeout_ms);
385	    }
386	
387	  nxmutex_unlock(&g_bk7258_ap_lock);
388	  return ret;
389	}
