391	int bk7258_ap_ipi_test(uint32_t count, uint32_t timeout_ms)
392	{
393	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
394	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
395	  uint32_t elapsed;
396	  uint32_t event;
397	  int ret;
398	
399	  if (count == 0)
400	    {
401	      count = BK7258_AP_IPI_DEFAULT_COUNT;
402	    }
403	
404	  if (timeout_ms == 0)
405	    {
406	      timeout_ms = BK7258_AP_IPI_DEFAULT_TIMEOUT_MS;
407	    }
408	
409	  if (count > BK7258_AP_IPI_MAX_COUNT)
410	    {
411	      return -ERANGE;
412	    }
413	
414	  ret = nxmutex_lock(&g_bk7258_ap_lock);
415	  if (ret < 0)
416	    {
417	      return ret;
418	    }
419	
420	  __asm volatile ("dmb sy" ::: "memory");
421	  if (bk7258_ap_scheduler_online())
422	    {
423	      ret = -ENOTSUP;
424	      goto out;
425	    }
426	
427	  if (state->state != BK7258_AP_STATE_READY ||
428	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
429	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
430	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
431	      ipi->generation != state->generation)
432	    {
433	      ret = -EAGAIN;
434	      goto out;
435	    }
436	
437	  if (ipi->state == BK7258_AP_IPI_STATE_RUNNING ||
438	      ipi->state == BK7258_AP_IPI_STATE_REQUESTED)
439	    {
440	      ret = -EBUSY;
441	      goto out;
442	    }
443	
444	  ipi->requested_count = count;
445	  ipi->completed_count = 0;
446	  ipi->timeout_ms = timeout_ms;
447	  ipi->error = BK7258_AP_IPI_ERROR_NONE;
448	  ipi->state = BK7258_AP_IPI_STATE_REQUESTED;
449	  state->command = BK7258_AP_COMMAND_IPI_TEST;
450	  __asm volatile ("dmb sy" ::: "memory");
451	  bk7258_ap_mbox_send(BK7258_AP_EVENT_IPI_TEST);
452	
453	  ret = -ETIMEDOUT;
454	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
455	    {
456	      event = bk7258_ap_mbox_receive();
457	      if (event != BK7258_AP_EVENT_NONE)
458	        {
459	          state->last_event = event;
460	        }
461	
462	      __asm volatile ("dmb sy" ::: "memory");
463	      if (ipi->state == BK7258_AP_IPI_STATE_PASSED)
464	        {
465	          ret = OK;
466	          break;
467	        }
468	
469	      if (ipi->state == BK7258_AP_IPI_STATE_FAILED ||
470	          state->state == BK7258_AP_STATE_FAILED)
471	        {
472	          ret = -EIO;
473	          break;
474	        }
475	
476	      nxsig_usleep(1000);
477	    }
478	
479	out:
480	  nxmutex_unlock(&g_bk7258_ap_lock);
481	  return ret;
482	}
