193	static uint32_t apctl_u32(const char *value, uint32_t fallback)
194	{
195	  char *end;
196	  unsigned long parsed;
197	
198	  if (value == NULL)
199	    {
200	      return fallback;
201	    }
202	
203	  parsed = strtoul(value, &end, 0);
204	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
205	    {
206	      return fallback;
207	    }
208	
209	  return (uint32_t)parsed;
210	}
