454	             sem_wake.task_id, sem_wake.wait_entered,
455	             sem_wake.waiter_observed, sem_wake.waiter_sem_value);
456	      printf("Sem-wake post cpu/count/result=%" PRIu32 "/%" PRIu32
457	             "/%" PRId32
458	             " wait returned/result/cpu=%" PRIu32 "/%" PRId32
459	             "/%" PRIu32 "\n",
460	             sem_wake.post_cpu, sem_wake.post_count,
461	             sem_wake.post_result, sem_wake.wait_returned,
462	             sem_wake.wait_result, sem_wake.wake_cpu);
463	      printf("Sem-wake SMP tx0=%" PRIu32 "->%" PRIu32
464	             " rx1=%" PRIu32 "->%" PRIu32
465	             " fail0=%" PRIu32 "->%" PRIu32 "\n",
466	             sem_wake.smp_tx_before, sem_wake.smp_tx_after,
467	             sem_wake.smp_rx_before, sem_wake.smp_rx_after,
468	             sem_wake.smp_fail_before, sem_wake.smp_fail_after);
469	      printf("Sem-wake IPI irq1=%" PRIu32 "->%" PRIu32
470	             " wake1=%" PRIu32 "->%" PRIu32
471	             " calls=%" PRIu32 "->%" PRIu32 "\n",
472	             sem_wake.ipi_irq_before, sem_wake.ipi_irq_after,
473	             sem_wake.ipi_wake_before, sem_wake.ipi_wake_after,
474	             sem_wake.cpu2_calls_before, sem_wake.cpu2_calls_after);
475	    }
476	
477	  if (sem_loop.magic == BK7258_AP_SEM_WAKE_LOOP_STATE_MAGIC &&
478	      sem_loop.version == BK7258_AP_SEM_WAKE_LOOP_STATE_VERSION &&
479	      sem_loop.size == sizeof(sem_loop))
480	    {
481	      printf("AP sem-loop state=%s(%" PRIu32 ") error=%" PRIu32
482	             " generation=%" PRIu32 " requested/completed=%" PRIu32
483	             "/%" PRIu32 "\n",
484	             apctl_sem_wake_loop_state_name(sem_loop.state),
485	             sem_loop.state, sem_loop.error, sem_loop.generation,
486	             sem_loop.requested_cycles, sem_loop.completed_cycles);
487	      printf("Sem-loop waits entered/observed/returned=%" PRIu32
488	             "/%" PRIu32 "/%" PRIu32 " value=%" PRId32 "\n",
489	             sem_loop.wait_entered, sem_loop.waiter_observed,
490	             sem_loop.wait_returned, sem_loop.waiter_sem_value);
491	      printf("Sem-loop posts cpu/count/result=%" PRIu32 "/%" PRIu32
492	             "/%" PRId32 " wait result/cpu=%" PRId32 "/%" PRIu32
493	             "\n", sem_loop.post_cpu, sem_loop.post_count,
494	             sem_loop.post_result, sem_loop.wait_result,
495	             sem_loop.wake_cpu);
496	      printf("Sem-loop sequence wait/post/wake=%" PRIu32 "/%" PRIu32
497	             "/%" PRIu32 "\n", sem_loop.wait_sequence,
498	             sem_loop.post_sequence, sem_loop.wake_sequence);
499	      printf("Sem-loop SMP tx0=%" PRIu32 "->%" PRIu32
500	             " rx1=%" PRIu32 "->%" PRIu32
501	             " fail0=%" PRIu32 "->%" PRIu32 "\n",
502	             sem_loop.smp_tx_before, sem_loop.smp_tx_after,
503	             sem_loop.smp_rx_before, sem_loop.smp_rx_after,
504	             sem_loop.smp_fail_before, sem_loop.smp_fail_after);
505	      printf("Sem-loop IPI irq1=%" PRIu32 "->%" PRIu32
506	             " wake1=%" PRIu32 "->%" PRIu32
507	             " calls=%" PRIu32 "->%" PRIu32 "\n",
508	             sem_loop.ipi_irq_before, sem_loop.ipi_irq_after,
509	             sem_loop.ipi_wake_before, sem_loop.ipi_wake_after,
510	             sem_loop.cpu2_calls_before, sem_loop.cpu2_calls_after);
511	    }
