514	static void apctl_usage(void)
515	{
516	  printf("usage: apctl start|stop|restart|status [timeout_ms]\n");
517	  printf("       apctl cycle [count] [timeout_ms]\n");
518	  printf("       apctl ipitest [count] [timeout_ms]\n");
519	}
520	
521	/****************************************************************************
522	 * Public Functions
523	 ****************************************************************************/
524	
525	int main(int argc, char *argv[])
526	{
527	  uint32_t timeout;
528	  uint32_t count;
529	  uint32_t i;
530	  int ret = -EINVAL;
531	
532	  if (argc < 2)
533	    {
534	      apctl_usage();
535	      return 1;
536	    }
537	
538	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
539	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
540	
541	  if (strcmp(argv[1], "start") == 0)
542	    {
543	      ret = bk7258_ap_start(timeout);
544	    }
545	  else if (strcmp(argv[1], "stop") == 0)
546	    {
547	      ret = bk7258_ap_stop(timeout);
548	    }
549	  else if (strcmp(argv[1], "restart") == 0)
550	    {
551	      ret = bk7258_ap_restart(timeout);
552	    }
553	  else if (strcmp(argv[1], "status") == 0)
554	    {
555	      apctl_status();
556	      return 0;
557	    }
558	  else if (strcmp(argv[1], "ipitest") == 0)
559	    {
560	      count = apctl_u32(argc > 2 ? argv[2] : NULL,
561	                        BK7258_AP_IPI_DEFAULT_COUNT);
562	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
563	                          BK7258_AP_IPI_DEFAULT_TIMEOUT_MS);
564	      ret = bk7258_ap_ipi_test(count, timeout);
565	    }
566	  else if (strcmp(argv[1], "cycle") == 0)
567	    {
568	      count = apctl_u32(argc > 2 ? argv[2] : NULL, 3);
569	      timeout = apctl_u32(argc > 3 ? argv[3] : NULL,
570	                          BK7258_AP_DEFAULT_TIMEOUT_MS);
571	
572	      /* Normalize the entry state so every iteration is one complete
573	       * start/stop generation, including when cycle is invoked from READY.
574	       */
575	
576	      ret = bk7258_ap_stop(timeout);
577	      for (i = 0; ret >= 0 && i < count; i++)
578	        {
579	          ret = bk7258_ap_start(timeout);
580	          if (ret < 0)
581	            {
582	              break;
583	            }
584	
585	          apctl_status();
586	          ret = bk7258_ap_stop(timeout);
587	        }
588	    }
589	  else
590	    {
591	      apctl_usage();
592	      return 1;
593	    }
594	
595	  apctl_status();
596	  if (ret < 0)
597	    {
598	      if (ret == -ENOTSUP)
599	        {
600	          fprintf(stderr,
601	                  "apctl: %s is disabled while AP scheduler-online mode "
602	                  "is active\n", argv[1]);
603	        }
604	      else
605	        {
606	          fprintf(stderr, "apctl: %s failed: %d\n", argv[1], ret);
607	        }
608	
609	      return 1;
610	    }
611	
612	  return 0;
613	}
