161	static int bk7258_cpu2_wait(uint32_t wanted, uint32_t timeout_ms)
162	{
163	  volatile struct bk7258_cpu2_probe_state_s *state =
164	    bk7258_cpu2_probe_state();
165	  uint32_t current;
166	  uint32_t elapsed;
167	
168	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
169	    {
170	      current = state->state;
171	      __asm volatile ("dmb sy" ::: "memory");
172	      if (current == wanted)
173	        {
174	          return OK;
175	        }
176	
177	      if (current == BK7258_CPU2_PROBE_STATE_FAILED)
178	        {
179	          return -EIO;
180	        }
181	
182	      up_mdelay(1);
183	    }
184	
185	  return -ETIMEDOUT;
186	}
