357	static int32_t bk7258_ap_sem_exact_waiter_value(
358	  pthread_t thread, cpu_set_t cpuset)
359	{
360	  FAR struct tcb_s *tcb;
361	  irqstate_t flags;
362	  int32_t observed = INT32_MAX;
363	  int value = 0;
364	  int ret;
365	
366	  tcb = nxsched_get_tcb((pid_t)thread);
367	  if (tcb == NULL)
368	    {
369	      return observed;
370	    }
371	
372	  flags = enter_critical_section();
373	  ret = nxsem_get_value(&g_bk7258_ap_cpu1_sem, &value);
374	  if (ret >= 0 &&
375	      tcb->task_state == TSTATE_WAIT_SEM &&
376	      tcb->waitobj == (FAR void *)&g_bk7258_ap_cpu1_sem &&
377	      value == -1 && tcb->affinity == cpuset)
378	    {
379	      observed = (int32_t)value;
380	    }
381	
382	  leave_critical_section(flags);
383	  nxsched_put_tcb(tcb);
384	  __asm volatile ("dmb sy" ::: "memory");
385	  return observed;
386	}
