392	  volatile struct bk7258_ap_sem_wake_loop_state_s *loop_state,
393	  uint32_t error, uint32_t cycle)
394	{
395	  bk7258_ap_sem_wake_loop_fail(loop_state, error);
396	  if (cycle == 1 && loop_state->completed_cycles == 0)
397	    {
398	      bk7258_ap_sem_wake_fail(
399	        sem_state, bk7258_ap_sem_wake_loop_sem_error(error));
400	    }
401	
402	  bk7258_ap_affinity_fail(
403	    affinity, bk7258_ap_sem_wake_loop_affinity_error(error));
404	  __asm volatile ("dmb sy; sev" ::: "memory");
405	}
