407	static int bk7258_ap_sem_wake_loop_abort(
408	  volatile struct bk7258_ap_affinity_state_s *affinity,
409	  volatile struct bk7258_ap_sem_wake_state_s *sem_state,
410	  volatile struct bk7258_ap_sem_wake_loop_state_s *loop_state,
411	  uint32_t error, int first_cycle_completed, int sem_initialized,
412	  int ret)
413	{
