419	    }
420	
421	  bk7258_ap_affinity_fail(
422	    affinity, bk7258_ap_sem_wake_loop_affinity_error(error));
423	  if (sem_initialized && affinity->task_completed == 0)
424	    {
425	      (void)nxsem_post(&g_bk7258_ap_cpu1_sem);
426	    }
427	
428	  __asm volatile ("dmb sy; sev" ::: "memory");
