433	/* Do not take a TCB reference here.  If CPU1 is already in
434	 * nxsched_release_pid(), CPU0 releasing that reference can wake exit_sem and
435	 * add an extra scheduler IPI to the N8-C3/N8-C4 measurement window.
436	 */
437	
438	static int bk7258_ap_pid_released(pthread_t thread)
439	{
440	  pid_t pid = (pid_t)thread;
441	  irqstate_t flags;
442	  int released = 1;
443	  int hash_ndx;
444	
445	  flags = spin_lock_irqsave_notrace(&g_pidhashlock);
446	  if (g_pidhash != NULL && g_npidhash > 0 && pid >= 0)
447	    {
448	      hash_ndx = PIDHASH(pid);
449	      if (g_pidhash[hash_ndx] != NULL &&
450	          g_pidhash[hash_ndx]->pid == pid)
451	        {
452	          released = 0;
453	        }
454	    }
455	
456	  spin_unlock_irqrestore_notrace(&g_pidhashlock, flags);
457	  return released;
458	}
