461	static FAR void *bk7258_ap_cpu1_affinity_task(FAR void *arg)
462	{
463	  volatile struct bk7258_ap_affinity_state_s *state = arg;
464	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
465	  volatile struct bk7258_ap_sem_wake_state_s *sem_state =
466	    bk7258_ap_sem_wake_state();
467	#  ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE_LOOP
468	  volatile struct bk7258_ap_sem_wake_loop_state_s *loop_state =
469	    bk7258_ap_sem_wake_loop_state();
470	  uint32_t cycle;
471	  uint32_t elapsed;
472	  uint32_t loop_wait_state;
473	  uint32_t sem_wait_state;
474	  uint32_t post_sequence;
475	  int continued;
476	#  else
477	  uint32_t wait_state;
478	#  endif
479	#endif
480	  cpu_set_t observed = 0;
481	  pthread_t self = pthread_self();
482	  int ret;
483	
484	  if (state == NULL)
485	    {
486	      return NULL;
487	    }
488	
489	  state->task_id = (uint32_t)self;
490	  state->task_cpu = (uint32_t)up_cpu_index();
491	  state->task_started++;
492	  __asm volatile ("dmb sy" ::: "memory");
493	
494	  if (state->magic != BK7258_AP_AFFINITY_STATE_MAGIC ||
495	      state->version != BK7258_AP_AFFINITY_STATE_VERSION ||
496	      state->size != sizeof(struct bk7258_ap_affinity_state_s) ||
497	      state->generation != bk7258_ap_boot_state()->generation ||
498	      state->state != BK7258_AP_AFFINITY_STATE_DISPATCHING)
499	    {
500	      bk7258_ap_affinity_fail(state,
501	                             BK7258_AP_AFFINITY_ERROR_BAD_STATE);
502	      goto done;
503	    }
504	
505	  state->state = BK7258_AP_AFFINITY_STATE_RUNNING;
506	  __asm volatile ("dmb sy" ::: "memory");
507	
508	  ret = pthread_getaffinity_np(self, sizeof(observed), &observed);
509	  state->observed_mask = (uint32_t)observed;
510	
511	  if (ret != 0)
512	    {
513	      bk7258_ap_affinity_fail(state,
514	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
515	    }
516	  else if (state->task_cpu != BK7258_AP_SECONDARY_CPU)
517	    {
518	      bk7258_ap_affinity_fail(state,
519	                             BK7258_AP_AFFINITY_ERROR_BAD_CPU);
520	    }
521	  else if (state->observed_mask != state->requested_mask)
522	    {
523	      bk7258_ap_affinity_fail(state,
524	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
525	    }
526	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
527	#  ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE_LOOP
528	  else if (sem_state->magic != BK7258_AP_SEM_WAKE_STATE_MAGIC ||
529	           sem_state->version != BK7258_AP_SEM_WAKE_STATE_VERSION ||
530	           sem_state->size != sizeof(struct bk7258_ap_sem_wake_state_s) ||
531	           sem_state->generation != state->generation ||
532	           sem_state->state != BK7258_AP_SEM_WAKE_STATE_INITIALIZING ||
533	           sem_state->error != BK7258_AP_SEM_WAKE_ERROR_NONE ||
534	           loop_state->magic != BK7258_AP_SEM_WAKE_LOOP_STATE_MAGIC ||
535	           loop_state->version != BK7258_AP_SEM_WAKE_LOOP_STATE_VERSION ||
536	           loop_state->size !=
537	             sizeof(struct bk7258_ap_sem_wake_loop_state_s) ||
538	           loop_state->generation != state->generation ||
539	           loop_state->state !=
540	             BK7258_AP_SEM_WAKE_LOOP_STATE_INITIALIZING ||
541	           loop_state->error != BK7258_AP_SEM_WAKE_LOOP_ERROR_NONE ||
542	           loop_state->requested_cycles !=
543	             BK7258_AP_SEM_WAKE_LOOP_CYCLES)
544	    {
545	      bk7258_ap_sem_wake_loop_task_fail(
546	        state, sem_state, loop_state,
547	        BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_STATE, 1);
548	    }
549	  else
550	    {
551	      sem_state->task_id = (uint32_t)self;
552	      for (cycle = 1; cycle <= BK7258_AP_SEM_WAKE_LOOP_CYCLES;
553	           cycle++)
554	        {
555	          __asm volatile ("dmb sy" ::: "memory");
556	          if (loop_state->state !=
557	                (cycle == 1 ?
558	                   BK7258_AP_SEM_WAKE_LOOP_STATE_INITIALIZING :
559	                   BK7258_AP_SEM_WAKE_LOOP_STATE_CONTINUE) ||
560	              loop_state->completed_cycles != cycle - 1 ||
561	              loop_state->wait_entered != cycle - 1 ||
562	              loop_state->waiter_observed != cycle - 1 ||
563	              loop_state->post_count != cycle - 1 ||
564	              loop_state->wait_returned != cycle - 1)
565	            {
566	              bk7258_ap_sem_wake_loop_task_fail(
567	                state, sem_state, loop_state,
568	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
569	              goto done;
570	            }
571	
572	          loop_state->wait_sequence = cycle;
573	          loop_state->wait_entered++;
574	          if (cycle == 1)
575	            {
576	              sem_state->wait_entered = 1;
577	              sem_state->state = BK7258_AP_SEM_WAKE_STATE_WAITING;
578	            }
579	
580	          __asm volatile ("dmb sy" ::: "memory");
581	          loop_state->state = BK7258_AP_SEM_WAKE_LOOP_STATE_WAITING;
582	          __asm volatile ("dmb sy; sev" ::: "memory");
583	
584	          ret = nxsem_wait_uninterruptible(&g_bk7258_ap_cpu1_sem);
585	          __asm volatile ("dmb sy" ::: "memory");
586	          loop_wait_state = loop_state->state;
587	          post_sequence = loop_state->post_sequence;
588	          sem_wait_state = cycle == 1 ? sem_state->state :
589	            BK7258_AP_SEM_WAKE_STATE_POSTED;
590	          loop_state->wait_result = (int32_t)ret;
591	          loop_state->wake_cpu = (uint32_t)up_cpu_index();
592	          loop_state->wait_returned++;
593	          if (cycle == 1)
594	            {
595	              sem_state->wait_result = (int32_t)ret;
596	              sem_state->wait_returned = 1;
597	              sem_state->wake_cpu = loop_state->wake_cpu;
598	            }
599	
600	          __asm volatile ("dmb sy" ::: "memory");
601	          if (ret < 0)
602	            {
603	              bk7258_ap_sem_wake_loop_task_fail(
604	                state, sem_state, loop_state,
605	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEM_WAIT, cycle);
606	              goto done;
607	            }
608	          else if (loop_wait_state !=
609	                     BK7258_AP_SEM_WAKE_LOOP_STATE_POSTED ||
610	                   sem_wait_state != BK7258_AP_SEM_WAKE_STATE_POSTED)
611	            {
612	              bk7258_ap_sem_wake_loop_task_fail(
613	                state, sem_state, loop_state,
614	                BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_STATE, cycle);
615	              goto done;
616	            }
617	          else if (post_sequence != cycle)
618	            {
619	              bk7258_ap_sem_wake_loop_task_fail(
620	                state, sem_state, loop_state,
621	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
622	              goto done;
623	            }
624	          else if (loop_state->post_count != cycle)
625	            {
626	              bk7258_ap_sem_wake_loop_task_fail(
627	                state, sem_state, loop_state,
628	                BK7258_AP_SEM_WAKE_LOOP_ERROR_COUNT_MISMATCH, cycle);
629	              goto done;
630	            }
631	          else if (loop_state->wake_cpu != BK7258_AP_SECONDARY_CPU)
632	            {
633	              bk7258_ap_sem_wake_loop_task_fail(
634	                state, sem_state, loop_state,
635	                BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_CPU, cycle);
636	              goto done;
637	            }
638	
639	          loop_state->completed_cycles++;
640	          loop_state->wake_sequence = cycle;
641	          if (cycle == 1)
642	            {
643	              sem_state->state = BK7258_AP_SEM_WAKE_STATE_WOKEN;
644	            }
645	
646	          __asm volatile ("dmb sy" ::: "memory");
647	          loop_state->state = BK7258_AP_SEM_WAKE_LOOP_STATE_WOKEN;
648	          __asm volatile ("dmb sy; sev" ::: "memory");
649	
650	          if (cycle < BK7258_AP_SEM_WAKE_LOOP_CYCLES)
651	            {
652	              continued = 0;
653	              for (elapsed = 0;
654	                   elapsed < BK7258_AP_SEM_WAKE_LOOP_TIMEOUT_MS;
655	                   elapsed++)
656	                {
657	                  __asm volatile ("dmb sy" ::: "memory");
658	                  if (loop_state->state ==
659	                        BK7258_AP_SEM_WAKE_LOOP_STATE_CONTINUE &&
660	                      loop_state->completed_cycles == cycle &&
661	                      loop_state->wake_sequence == cycle)
662	                    {
663	                      continued = 1;
664	                      break;
665	                    }
666	
667	                  if (loop_state->state ==
668	                        BK7258_AP_SEM_WAKE_LOOP_STATE_FAILED ||
669	                      state->state == BK7258_AP_AFFINITY_STATE_FAILED)
670	                    {
671	                      goto done;
672	                    }
673	
674	                  if (loop_state->state !=
675	                        BK7258_AP_SEM_WAKE_LOOP_STATE_WOKEN)
676	                    {
677	                      bk7258_ap_sem_wake_loop_task_fail(
678	                        state, sem_state, loop_state,
679	                        BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
680	                      goto done;
681	                    }
682	
683	                  __asm volatile ("wfe" ::: "memory");
684	                }
685	
686	              if (!continued)
687	                {
688	                  bk7258_ap_sem_wake_loop_task_fail(
689	                    state, sem_state, loop_state,
690	                    BK7258_AP_SEM_WAKE_LOOP_ERROR_WAKE_TIMEOUT, cycle);
691	                  goto done;
692	                }
693	            }
694	        }
695	    }
696	#  else
697	  else if (sem_state->magic != BK7258_AP_SEM_WAKE_STATE_MAGIC ||
698	           sem_state->version != BK7258_AP_SEM_WAKE_STATE_VERSION ||
699	           sem_state->size != sizeof(struct bk7258_ap_sem_wake_state_s) ||
700	           sem_state->generation != state->generation ||
701	           sem_state->state != BK7258_AP_SEM_WAKE_STATE_INITIALIZING ||
702	           sem_state->error != BK7258_AP_SEM_WAKE_ERROR_NONE)
703	    {
704	      bk7258_ap_sem_wake_fail(sem_state,
705	                             BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
706	    }
707	  else
708	    {
709	      sem_state->task_id = (uint32_t)self;
710	      sem_state->wait_entered = 1;
711	      sem_state->state = BK7258_AP_SEM_WAKE_STATE_WAITING;
712	      __asm volatile ("dmb sy; sev" ::: "memory");
713	
714	      ret = nxsem_wait_uninterruptible(&g_bk7258_ap_cpu1_sem);
715	      __asm volatile ("dmb sy" ::: "memory");
716	      wait_state = sem_state->state;
717	      sem_state->wait_result = (int32_t)ret;
718	      sem_state->wait_returned = 1;
719	      sem_state->wake_cpu = (uint32_t)up_cpu_index();
720	      __asm volatile ("dmb sy" ::: "memory");
721	
722	      if (ret < 0)
723	        {
724	          bk7258_ap_sem_wake_fail(sem_state,
725	                                 BK7258_AP_SEM_WAKE_ERROR_SEM_WAIT);
726	        }
727	      else if (wait_state != BK7258_AP_SEM_WAKE_STATE_POSTED)
728	        {
729	          bk7258_ap_sem_wake_fail(sem_state,
730	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
731	        }
732	      else if (sem_state->wake_cpu != BK7258_AP_SECONDARY_CPU)
733	        {
734	          bk7258_ap_sem_wake_fail(sem_state,
735	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_CPU);
736	        }
737	      else
738	        {
739	          sem_state->state = BK7258_AP_SEM_WAKE_STATE_WOKEN;
740	          __asm volatile ("dmb sy; sev" ::: "memory");
741	        }
742	    }
743	#  endif
744	#endif
745	
746	done:
747	  state->task_completed++;
748	  __asm volatile ("dmb sy; sev" ::: "memory");
749	  return NULL;
750	}
751	#endif
