802	static void __attribute__((noinline, noreturn, used))
803	bk7258_ap_secondary_bootstrap(void)
804	{
805	  volatile struct bk7258_cpu2_probe_state_s *state;
806	
807	  bk7258_cpu2_fpu_initialize();
808	  state = bk7258_cpu2_probe_state();
809	  uint32_t control;
810	  uint32_t msp;
811	
812	  __asm volatile ("mrs %0, msp" : "=r" (msp));
813	  __asm volatile ("mrs %0, control" : "=r" (control));
814	
815	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
816	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
817	  state->runtime_vtor = BK7258_SCB_VTOR;
818	  state->runtime_msp = msp;
819	  state->control = control;
820	  state->boot_count++;
821	  __asm volatile ("dmb sy" ::: "memory");
822	
823	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
824	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
825	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
826	    {
827	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
828	      goto parked;
829	    }
830	
831	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
832	  __asm volatile ("dmb sy" ::: "memory");
833	
834	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
835	        BK7258_CPU2_LOCAL_CORE_ID ||
836	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
837	    {
838	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
839	      goto parked;
840	    }
841	
842	  if (state->runtime_vtor !=
843	      (uint32_t)(uintptr_t)__vector_core1_table)
844	    {
845	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
846	      goto parked;
847	    }
848	
849	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
850	      msp > BK7258_CPU2_BOOT_STACK_TOP)
851	    {
852	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
853	      goto parked;
854	    }
855	
856	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
857	      state->idle_stack_base >= state->idle_stack_top ||
858	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
859	    {
860	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
861	      goto parked;
862	    }
863	
864	#ifdef CONFIG_BK7258_AP_IPI
865	  if (bk7258_ap_ipi_secondary_initialize() < 0)
866	    {
867	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
868	      goto parked;
869	    }
870	#endif
871	
872	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
873	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
874	  state->online_mask = BK7258_AP_PRIMARY_MASK;
875	
876	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
877	  state->secondary_ready = 0;
878	  __asm volatile ("dmb sy" ::: "memory");
879	
880	  if (bk7258_cpu2_scheduler_irq_initialize() < 0)
881	    {
882	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
883	      goto parked;
884	    }
885	
886	  bk7258_ap_secondary_enter_scheduler(state->idle_stack_top);
887	#else
888	  state->secondary_ready = 1;
889	  __asm volatile ("dmb sy" ::: "memory");
890	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
891	  __asm volatile ("dmb sy; sev" ::: "memory");
892	
893	#  ifdef CONFIG_BK7258_AP_IPI
894	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
895	#  endif
896	
897	  for (; ; )
898	    {
899	      __asm volatile ("dmb sy" ::: "memory");
900	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
901	        {
902	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
903	          state->secondary_ready = 0;
904	          __asm volatile ("dmb sy" ::: "memory");
905	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
906	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
907	          __asm volatile ("dmb sy; sev" ::: "memory");
908	          goto parked;
909	        }
910	
911	      state->heartbeat++;
912	#  ifdef CONFIG_BK7258_AP_IPI
913	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
914	#  else
915	      __asm volatile ("dmb sy; wfe" ::: "memory");
916	#  endif
917	    }
918	#endif
919	
920	parked:
921	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
922	  for (; ; )
923	    {
924	      __asm volatile ("wfe");
925	    }
926	}
