928	static void __attribute__((naked, noreturn, used))
929	bk7258_ap_secondary_reset(void)
930	{
931	  __asm volatile
932	    (
933	      "cpsid i\n"
934	      "movs r0, #0\n"
935	      "msr control, r0\n"
936	      "msr basepri, r0\n"
937	      "msr faultmask, r0\n"
938	      "ldr r0, =0x20000000\n"
939	      "movs r1, #1\n"
940	      "str r1, [r0]\n"
941	      "ldr r0, =__vector_core1_table\n"
942	      "ldr r1, =0xe000ed08\n"
943	      "str r0, [r1]\n"
944	      "dsb sy\n"
945	      "isb sy\n"
946	      "b bk7258_ap_secondary_bootstrap\n"
947	    );
948	}
