950	static void __attribute__((noinline, noreturn, used))
951	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
952	{
953	  volatile struct bk7258_cpu2_probe_state_s *state =
954	    bk7258_cpu2_probe_state();
955	  uintptr_t frame = (uintptr_t)stack;
956	  uint32_t error;
957	
958	  state->fault_exception = exception;
959	  state->fault_hfsr = BK7258_SCB_HFSR;
960	  state->fault_cfsr = BK7258_SCB_CFSR;
961	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
962	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
963	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
964	
965	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
966	      ((frame >= BK7258_CPU2_BOOT_STACK_BASE &&
967	        frame <= BK7258_CPU2_BOOT_STACK_TOP -
968	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
969	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
970	       ||
971	       (frame >= state->idle_stack_base &&
972	        frame <= state->idle_stack_top -
973	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
974	#endif
975	      ))
976	    {
977	      const volatile uint32_t *regs =
978	        (const volatile uint32_t *)frame;
979	
980	      state->fault_lr = regs[5];
981	      state->fault_pc = regs[6];
982	      state->fault_xpsr = regs[7];
983	    }
984	
985	  error = exception == 2u ?
986	    BK7258_CPU2_PROBE_ERROR_NMI :
987	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
988	  bk7258_cpu2_fail(error);
989	
990	  for (; ; )
991	    {
992	      __asm volatile ("wfe");
993	    }
994	}
