996	static void __attribute__((naked, noreturn, used))
997	bk7258_ap_secondary_fault_entry(void)
998	{
999	  __asm volatile
1000	    (
1001	      "tst lr, #4\n"
1002	      "ite eq\n"
1003	      "mrseq r0, msp\n"
1004	      "mrsne r0, psp\n"
1005	      "mrs r1, ipsr\n"
1006	      "b bk7258_ap_secondary_fault_handler\n"
1007	    );
1008	}
