1050	int up_cpu_start(int cpu)
1051	{
1052	  volatile struct bk7258_cpu2_probe_state_s *state =
1053	    bk7258_cpu2_probe_state();
1054	  volatile uint32_t *control = bk7258_cpu2_control();
1055	  struct tcb_s *tcb;
1056	  uintptr_t idle_base;
1057	  uintptr_t idle_top;
1058	  uint32_t generation;
1059	  uint32_t value;
1060	  int ret;
1061	
1062	  if (cpu != BK7258_AP_SECONDARY_CPU)
1063	    {
1064	      return -EINVAL;
1065	    }
1066	
1067	  bk7258_cpu2_hold_reset(state);
1068	  up_mdelay(1);
1069	
1070	  generation = bk7258_ap_boot_state()->generation;
1071	  if (generation == 0)
1072	    {
1073	      generation = 1;
1074	    }
1075	
1076	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
1077	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
1078	  state->size = sizeof(*state);
1079	  state->generation = generation;
1080	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
1081	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
1082	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
1083	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
1084	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
1085	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
1086	  state->secondary_entry =
1087	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
1088	  state->online_mask = BK7258_AP_PRIMARY_MASK;
1089	
1090	  tcb = current_task(cpu);
1091	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
1092	      tcb->adj_stack_size == 0)
1093	    {
1094	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1095	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
1096	      return -ENOMEM;
1097	    }
1098	
1099	  idle_base = (uintptr_t)tcb->stack_base_ptr;
1100	  idle_top = idle_base + tcb->adj_stack_size;
1101	  state->idle_stack_base = (uint32_t)idle_base;
1102	  state->idle_stack_top = (uint32_t)idle_top;
1103	
1104	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
1105	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
1106	    {
1107	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1108	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
1109	      return -ENOMEM;
1110	    }
1111	
1112	  value = *control;
1113	  state->control_before = value;
1114	  value &= ~(BK7258_SYS_CPU2_RESET |
1115	             BK7258_SYS_CPU2_POWER_DOWN |
1116	             BK7258_SYS_CPU2_HALT |
1117	             BK7258_SYS_CPU2_RXEVT_SEL |
1118	             BK7258_SYS_CPU2_BOOT_MASK);
1119	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
1120	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
1121	  *control = value;
1122	  __asm volatile ("dsb sy; isb sy" ::: "memory");
1123	
1124	  state->control_after = value;
1125	  __asm volatile ("dmb sy" ::: "memory");
1126	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1127	  __asm volatile ("dmb sy" ::: "memory");
1128	
1129	#ifdef CONFIG_BK7258_AP_IPI
1130	  ret = bk7258_ap_ipi_primary_initialize();
1131	  if (ret < 0)
1132	    {
1133	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
1134	      return ret;
1135	    }
1136	#endif
1137	
1138	  value |= BK7258_SYS_CPU2_RESET;
1139	  *control = value;
1140	  state->control_after = value;
1141	  __asm volatile ("dsb sy; sev" ::: "memory");
1142	
1143	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1144	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE,
1145	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
1146	#else
1147	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
1148	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
1149	#endif
1150	  if (ret < 0)
1151	    {
1152	      bk7258_cpu2_hold_reset(state);
1153	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
1154	        {
1155	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
1156	        }
1157	    }
1158	
1159	  return ret;
1160	}
