1211	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1212	int bk7258_ap_smp_scheduler_selftest(uint32_t timeout_ms)
1213	{
1214	  volatile struct bk7258_ap_smp_state_s *state = bk7258_ap_smp_state();
1215	  uint32_t elapsed;
1216	  int cpu;
1217	  int ret;
1218	
1219	  if (timeout_ms == 0)
1220	    {
1221	      timeout_ms = BK7258_AP_SMP_DEFAULT_TIMEOUT_MS;
1222	    }
1223	
1224	  if (state->magic != BK7258_AP_SMP_STATE_MAGIC ||
1225	      state->version != BK7258_AP_SMP_STATE_VERSION ||
1226	      state->size != sizeof(struct bk7258_ap_smp_state_s) ||
1227	      state->generation != bk7258_ap_boot_state()->generation ||
1228	      state->state != BK7258_AP_SMP_STATE_ONLINE ||
1229	      state->online_mask != BK7258_AP_ONLINE_MASK)
1230	    {
1231	      return -EAGAIN;
1232	    }
1233	
1234	  state->error = BK7258_AP_SMP_ERROR_NONE;
1235	  state->requested_count = 2;
1236	  state->completed_count = 0;
1237	  state->test_runs++;
1238	  state->last_callback_cpu = UINT32_MAX;
1239	
1240	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
1241	    {
1242	      state->tx_count[cpu] = 0;
1243	      state->rx_count[cpu] = 0;
1244	      state->coalesced_count[cpu] = 0;
1245	      state->send_failures[cpu] = 0;
1246	      state->call_handler_count[cpu] = 0;
1247	      state->delivered_handler_count[cpu] = 0;
1248	      state->callback_count[cpu] = 0;
1249	      state->last_command[cpu] = 0;
1250	    }
1251	
1252	  __asm volatile ("dmb sy" ::: "memory");
1253	  state->state = BK7258_AP_SMP_STATE_TESTING;
1254	  __asm volatile ("dmb sy" ::: "memory");
1255	
1256	  nxsched_smp_call_init(&g_bk7258_ap_smp_forward_call,
1257	                        bk7258_ap_smp_secondary_callback,
1258	                        (FAR void *)state);
1259	  ret = nxsched_smp_call_single_async(BK7258_AP_SECONDARY_CPU,
1260	                                      &g_bk7258_ap_smp_forward_call);
1261	  if (ret < 0)
1262	    {
1263	      state->error = BK7258_AP_SMP_ERROR_CALL;
1264	      state->state = BK7258_AP_SMP_STATE_FAILED;
1265	      __asm volatile ("dmb sy; sev" ::: "memory");
1266	      return ret;
1267	    }
1268	
1269	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
1270	    {
1271	      __asm volatile ("dmb sy" ::: "memory");
1272	      if (state->callback_count[BK7258_AP_PRIMARY_CPU] == 1 &&
1273	          state->callback_count[BK7258_AP_SECONDARY_CPU] == 1)
1274	        {
1275	          break;
1276	        }
1277	
1278	      if (state->state == BK7258_AP_SMP_STATE_FAILED)
1279	        {
1280	          return -EIO;
1281	        }
1282	
1283	      up_mdelay(1);
1284	    }
1285	
1286	  if (elapsed == timeout_ms)
1287	    {
1288	      state->error = BK7258_AP_SMP_ERROR_TIMEOUT;
1289	      state->state = BK7258_AP_SMP_STATE_FAILED;
1290	      __asm volatile ("dmb sy; sev" ::: "memory");
1291	      return -ETIMEDOUT;
1292	    }
1293	
1294	  if (state->tx_count[0] < 1 || state->tx_count[1] < 1 ||
1295	      state->rx_count[0] < 1 || state->rx_count[1] < 1 ||
1296	      state->call_handler_count[0] < 1 ||
1297	      state->call_handler_count[1] < 1 ||
1298	      state->delivered_handler_count[0] < 1 ||
1299	      state->delivered_handler_count[1] < 1 ||
1300	      state->send_failures[0] != 0 ||
1301	      state->send_failures[1] != 0 ||
1302	      state->last_callback_cpu != BK7258_AP_PRIMARY_CPU)
1303	    {
1304	      state->error = BK7258_AP_SMP_ERROR_COUNT_MISMATCH;
1305	      state->state = BK7258_AP_SMP_STATE_FAILED;
1306	      __asm volatile ("dmb sy; sev" ::: "memory");
1307	      return -EIO;
1308	    }
1309	
1310	  state->completed_count = 2;
1311	  state->error = BK7258_AP_SMP_ERROR_NONE;
1312	  __asm volatile ("dmb sy" ::: "memory");
1313	  state->state = BK7258_AP_SMP_STATE_PASSED;
1314	  __asm volatile ("dmb sy; sev" ::: "memory");
1315	  return OK;
1316	}
1317	#endif
