108	                                          unsigned int vaddr,
109	                                          unsigned int paddr,
110	                                          int psize, int num)
111	{
112	  uint32_t regval;
113	#ifdef CONFIG_SMP
114	  int cpu_to_stop = 0;
115	#endif
116	  const bool os_ready = OSINIT_OS_READY();
117	  unsigned int i;
118	  unsigned int shift;
119	  unsigned int mask_s;
120	  unsigned int mmu_addr;
121	  unsigned int mmu_table_val;
122	  irqstate_t flags;
123	
124	  /* address check */
125	
126	  if ((ADDRESS_CHECK(vaddr, psize)) || (ADDRESS_CHECK(paddr, psize)))
127	    {
128	      return MMU_SET_ADDR_ALIGNED_ERROR;
129	    }
130	
131	  /* psize check */
132	
133	  if (psize == 32)
134	    {
135	      shift  = 15;
136	      mask_s = 0;
137	    }
138	  else if (psize == 16)
139	    {
140	      shift  = 14;
141	      mask_s = 1;
142	    }
143	  else if (psize == 8)
144	    {
145	      shift  = 13;
146	      mask_s = 2;
147	    }
148	  else if (psize == 4)
149	    {
150	      shift  = 12;
151	      mask_s = 3;
152	    }
153	  else if (psize == 2)
154	    {
155	      shift  = 11;
156	      mask_s = 4;
157	    }
158	  else
159	    {
160	      return MMU_SET_PAGE_SIZE_ERROR;
161	    }
162	
163	  /* mmu value */
164	
165	  mmu_table_val = paddr >> shift;
166	
167	  /* mmu_addr */
168	
169	  if (pid == 0 || pid == 1)
170	    {
171	      if (vaddr >= PRO_DRAM1_START_ADDR && vaddr < PRO_DRAM1_END_ADDR(psize))
172	        {
173	          mmu_addr = 1152 + ((vaddr & (0x3fffff >> mask_s)) >> shift);
174	        }
175	      else
176	        {
177	          return MMU_SET_VADDR_OUT_RANGE;
178	        }
179	    }
180	  else
181	    {
182	      if (vaddr >= PRO_DRAM1_START_ADDR && vaddr < PRO_DRAM1_END_ADDR(psize))
183	        {
184	          mmu_addr = (1024 + (pid << 7)) +
185	                     ((vaddr & (0x3fffff >> mask_s)) >> shift);
186	        }
187	      else
188	        {
189	          return MMU_SET_VADDR_OUT_RANGE;
190	        }
191	    }
192	
193	  /* The MMU registers are implemented in such a way that lookups from the
194	   * cache subsystem may collide with CPU access to the MMU registers. We use
195	   * the flash guards to make sure the cache is disabled.
196	   */
197	
198	  flags = 0; /* suppress GCC warning */
199	  if (os_ready)
200	    {
201	      flags = enter_critical_section();
202	    }
203	
204	#ifdef CONFIG_SMP
205	  /* The other CPU might be accessing the cache at the same time, just by
206	   * using variables in external RAM.
207	   */
208	
209	  if (os_ready)
210	    {
211	      cpu_to_stop = this_cpu() == 1 ? 0 : 1;
212	      g_cpu_wait  = true;
213	      g_cpu_pause = false;
214	      nxsched_smp_call_single_async(cpu_to_stop, &g_call_data);
215	      while (!g_cpu_pause);
216	    }
217	
218	  spi_disable_cache(1);
219	#endif
220	
221	  spi_disable_cache(0);
222	
223	  /* mmu change */
224	
225	  for (i = 0; i < num; i++)
226	    {
227	      *(volatile unsigned int *)(CACHE_MMU_ADDRESS_BASE(cpu_no) +
228	        mmu_addr * 4) = mmu_table_val + i; /* write table */
229	      mmu_addr++;
230	    }
231	
232	  if (cpu_no == 0)
233	    {
234	      regval  = getreg32(DPORT_PRO_CACHE_CTRL1_REG);
235	      regval &= ~DPORT_PRO_CMMU_SRAM_PAGE_MODE_M;
236	      regval |= mask_s << DPORT_PRO_CMMU_SRAM_PAGE_MODE_S;
237	      putreg32(regval, DPORT_PRO_CACHE_CTRL1_REG);
238	    }
239	  else
240	    {
241	      regval  = getreg32(DPORT_APP_CACHE_CTRL1_REG);
242	      regval &= ~DPORT_APP_CMMU_SRAM_PAGE_MODE_M;
243	      regval |= mask_s << DPORT_APP_CMMU_SRAM_PAGE_MODE_S;
244	      putreg32(regval, DPORT_APP_CACHE_CTRL1_REG);
245	    }
246	
247	  spi_enable_cache(0);
248	#ifdef CONFIG_SMP
249	  spi_enable_cache(1);
250	
251	  if (os_ready)
252	    {
253	      g_cpu_wait = false;
254	    }
255	#endif
