261	  uint32_t page_num = (len + MMU_PAGE_SIZE - 1) / MMU_PAGE_SIZE;
262	  uint32_t ret = page_num * MMU_PAGE_SIZE;
263	  mmu_val = paddr >> 16;
264	  bool write_back = false;
265	
266	  while (page_num)
267	    {
268	      entry_id = (vaddr & MMU_VADDR_MASK) >> 16;
