110	
111	static int32_t bp2p_exact_waiter(sem_t *sem, pthread_t thread,
112	                                  cpu_set_t cpuset)
113	{
114	  FAR struct tcb_s *tcb;
115	  irqstate_t flags;
116	  int32_t observed = INT32_MAX;
117	  int value = 0;
118	  int ret;
119	
120	  tcb = nxsched_get_tcb((pid_t)thread);
121	  if (tcb == NULL)
122	    {
123	      return observed;
124	    }
125	
126	  flags = enter_critical_section();
127	  ret = nxsem_get_value(sem, &value);
128	  if (ret >= 0 &&
129	      tcb->task_state == TSTATE_WAIT_SEM &&
130	      tcb->waitobj == (FAR void *)sem &&
131	      value == -1 && tcb->affinity == cpuset)
132	    {
133	      observed = (int32_t)value;
134	    }
135	
136	  leave_critical_section(flags);
137	  nxsched_put_tcb(tcb);
138	  __asm volatile ("dmb sy" ::: "memory");
139	  return observed;
140	}
