490	    }
491	
492	  /* Wait for both tasks to complete and PIDs to be released. */
493	
494	  for (elapsed = 0; elapsed < timeout_ms * 3; elapsed++)
495	    {
496	      __asm volatile ("dmb sy" ::: "memory");
497	      if (state->task_completed[0] != 0 && state->task_completed[1] != 0)
498	        {
499	          if (bk7258_ap_pid_released(thread[0]) &&
500	              bk7258_ap_pid_released(thread[1]))
501	            {
502	              state->aux[0] = 1;
503	              state->aux[1] = 1;
504	              break;
505	            }
506	        }
507	
508	      if (state->state == BK7258_AP_BP2P_STATE_FAILED)
509	        {
510	          return -EIO;
511	        }
512	
513	      up_mdelay(1);
514	    }
515	
516	  if (elapsed == timeout_ms * 3)
517	    {
518	      state->error = BK7258_AP_BP2P_ERROR_WAIT_TIMEOUT;
519	      state->state = BK7258_AP_BP2P_STATE_FAILED;
520	      __asm volatile ("dmb sy; sev" ::: "memory");
521	      return -ETIMEDOUT;
522	    }
523	
524	  /* Verify final counter deltas. */
525	
526	  __asm volatile ("dmb sy" ::: "memory");
527	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
528	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
529	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
530	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
531	  state->calls_after = cpu2->smp_call_requests;
532	  __asm volatile ("dmb sy" ::: "memory");
533	
534	  if (state->state == BK7258_AP_BP2P_STATE_FAILED)
535	    {
536	      return -EIO;
537	    }
538	
539	  /* CPU0->CPU1: +9 (1 dispatch + 8 wakes), CPU1->CPU0: +8, calls: +17 */
540	
541	  if (state->smp_tx0_after != state->smp_tx0_before + 9 ||
542	      state->smp_rx1_after != state->smp_rx1_before + 9 ||
543	      state->smp_tx1_after != state->smp_tx1_before + 8 ||
544	      state->smp_rx0_after != state->smp_rx0_before + 8 ||
545	      state->calls_after != state->calls_before + 17)
546	    {
547	      state->error = BK7258_AP_BP2P_ERROR_COUNT_MISMATCH;
548	      state->state = BK7258_AP_BP2P_STATE_FAILED;
549	      __asm volatile ("dmb sy; sev" ::: "memory");
550	      return -EIO;
551	    }
552	
553	  if (state->task_started[0] != 1 || state->task_started[1] != 1 ||
554	      state->task_completed[0] != 1 || state->task_completed[1] != 1 ||
555	      state->sequence[0] != BK7258_AP_ADV_CYCLES ||
556	      state->sequence[1] != BK7258_AP_ADV_CYCLES ||
557	      state->task_cpu[0] != BK7258_AP_PRIMARY_CPU ||
558	      state->task_cpu[1] != BK7258_AP_SECONDARY_CPU)
559	    {
560	      state->error = BK7258_AP_BP2P_ERROR_COUNT_MISMATCH;
561	      state->state = BK7258_AP_BP2P_STATE_FAILED;
562	      __asm volatile ("dmb sy; sev" ::: "memory");
563	      return -EIO;
564	    }
565	
566	  state->completed = BK7258_AP_ADV_CYCLES;
567	  state->error = BK7258_AP_BP2P_ERROR_NONE;
568	  __asm volatile ("dmb sy" ::: "memory");
569	  state->state = BK7258_AP_BP2P_STATE_PASSED;
570	  __asm volatile ("dmb sy; sev" ::: "memory");
571	  return OK;
572	}
