582	static int32_t bdul_exact_waiter(sem_t *sem, pthread_t thread,
583	                                  cpu_set_t cpuset)
584	{
585	  FAR struct tcb_s *tcb;
586	  irqstate_t flags;
587	  int32_t observed = INT32_MAX;
588	  int value = 0;
589	  int ret;
590	
591	  tcb = nxsched_get_tcb((pid_t)thread);
592	  if (tcb == NULL)
593	    {
594	      return observed;
595	    }
596	
597	  flags = enter_critical_section();
598	  ret = nxsem_get_value(sem, &value);
599	  if (ret >= 0 &&
600	      tcb->task_state == TSTATE_WAIT_SEM &&
601	      tcb->waitobj == (FAR void *)sem &&
602	      value == -1 && tcb->affinity == cpuset)
603	    {
604	      observed = (int32_t)value;
605	    }
606	
607	  leave_critical_section(flags);
608	  nxsched_put_tcb(tcb);
609	  __asm volatile ("dmb sy" ::: "memory");
610	  return observed;
611	}
