613	static int bk7258_ap_bdul_pid_released(pthread_t thread)
614	{
615	  pid_t pid = (pid_t)thread;
616	  irqstate_t flags;
617	  int released = 1;
618	  int hash_ndx;
619	
620	  flags = spin_lock_irqsave_notrace(&g_pidhashlock);
621	  if (g_pidhash != NULL && g_npidhash > 0 && pid >= 0)
622	    {
623	      hash_ndx = PIDHASH(pid);
624	      if (g_pidhash[hash_ndx] != NULL &&
625	          g_pidhash[hash_ndx]->pid == pid)
626	        {
627	          released = 0;
628	        }
629	    }
630	
631	  spin_unlock_irqrestore_notrace(&g_pidhashlock, flags);
632	  return released;
633	}
