635	/* Task A runs on CPU1, executes 8 times, posts B each round. */
636	
637	static FAR void *bdul_task_a(FAR void *arg)
638	{
639	  volatile struct bk7258_ap_advanced_state_s *state = arg;
640	  uint32_t cycle;
641	  uint32_t elapsed;
642	  int ret;
643	
644	  if (state == NULL)
645	    {
646	      return NULL;
647	    }
648	
649	  state->task_id[0] = (uint32_t)pthread_self();
650	  state->task_cpu[0] = (uint32_t)up_cpu_index();
651	  state->task_started[0]++;
652	  __asm volatile ("dmb sy" ::: "memory");
653	
654	  /* Wait to be started by CPU0 post. */
655	
656	  ret = nxsem_wait_uninterruptible(&g_bdul_sem[0]);
657	  if (ret < 0)
658	    {
659	      state->error = BK7258_AP_BDUL_ERROR_SEM_POST;
660	      state->state = BK7258_AP_BDUL_STATE_FAILED;
661	      __asm volatile ("dmb sy; sev" ::: "memory");
662	      goto done;
663	    }
664	
665	  for (cycle = 1; cycle <= BK7258_AP_ADV_CYCLES; cycle++)
666	    {
667	      if (up_cpu_index() != BK7258_AP_SECONDARY_CPU)
668	        {
669	          state->error = BK7258_AP_BDUL_ERROR_BAD_CPU;
670	          state->state = BK7258_AP_BDUL_STATE_FAILED;
671	          __asm volatile ("dmb sy; sev" ::: "memory");
672	          goto done;
673	        }
674	
675	      state->sequence[0] = cycle;
676	      __asm volatile ("dmb sy" ::: "memory");
677	
678	      /* Prove B is waiting before posting. */
679	
680	      for (elapsed = 0; elapsed < BK7258_AP_ADV_TIMEOUT_MS; elapsed++)
681	        {
682	          if (bdul_exact_waiter(&g_bdul_sem[1],
683	                                (pthread_t)state->task_id[1],
684	                                (cpu_set_t)(1u <<
685	                                  BK7258_AP_SECONDARY_CPU)) == -1)
686	            {
687	              break;
688	            }
689	
690	          if (state->state == BK7258_AP_BDUL_STATE_FAILED)
691	            {
692	              goto done;
693	            }
694	
695	          up_mdelay(1);
696	        }
697	
698	      if (elapsed == BK7258_AP_ADV_TIMEOUT_MS)
699	        {
700	          state->error = BK7258_AP_BDUL_ERROR_WAIT_TIMEOUT;
701	          state->state = BK7258_AP_BDUL_STATE_FAILED;
702	          __asm volatile ("dmb sy; sev" ::: "memory");
703	          goto done;
704	        }
705	
706	      ret = nxsem_post(&g_bdul_sem[1]);
707	      if (ret < 0)
708	        {
709	          state->error = BK7258_AP_BDUL_ERROR_SEM_POST;
710	          state->state = BK7258_AP_BDUL_STATE_FAILED;
711	          __asm volatile ("dmb sy; sev" ::: "memory");
712	          goto done;
713	        }
714	
715	      /* Wait for B to post us back (rounds 1..7) or done (round 8). */
716	
717	      if (cycle < BK7258_AP_ADV_CYCLES)
718	        {
719	          for (elapsed = 0; elapsed < BK7258_AP_ADV_TIMEOUT_MS; elapsed++)
720	            {
721	              __asm volatile ("dmb sy" ::: "memory");
722	              if (state->sequence[1] == cycle)
723	                {
724	                  break;
725	                }
726	
727	              if (state->state == BK7258_AP_BDUL_STATE_FAILED)
728	                {
729	                  goto done;
730	                }
731	
732	              up_mdelay(1);
733	            }
734	
735	          if (elapsed == BK7258_AP_ADV_TIMEOUT_MS)
736	            {
737	              state->error = BK7258_AP_BDUL_ERROR_WAIT_TIMEOUT;
738	              state->state = BK7258_AP_BDUL_STATE_FAILED;
739	              __asm volatile ("dmb sy; sev" ::: "memory");
740	              goto done;
741	            }
742	
743	          ret = nxsem_wait_uninterruptible(&g_bdul_sem[0]);
744	          if (ret < 0)
745	            {
746	              state->error = BK7258_AP_BDUL_ERROR_SEM_POST;
747	              state->state = BK7258_AP_BDUL_STATE_FAILED;
748	              __asm volatile ("dmb sy; sev" ::: "memory");
749	              goto done;
750	            }
751	        }
752	    }
753	
754	done:
755	  state->task_completed[0]++;
756	  __asm volatile ("dmb sy; sev" ::: "memory");
757	  return NULL;
758	}
