852	int bk7258_ap_smp_bdul_selftest(uint32_t timeout_ms)
853	{
854	  volatile struct bk7258_ap_advanced_state_s *state = bk7258_ap_bdul_state();
855	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
856	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
857	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
858	    bk7258_cpu2_probe_state();
859	  pthread_attr_t attr;
860	  pthread_t thread[2];
861	  cpu_set_t cpuset1 = (cpu_set_t)(1u << BK7258_AP_SECONDARY_CPU);
862	  uint32_t elapsed;
863	  int ret;
864	  int i;
865	
866	  if (timeout_ms == 0)
867	    {
868	      timeout_ms = BK7258_AP_ADV_TIMEOUT_MS;
869	    }
870	
871	  /* Validate N8-C4 prerequisites. */
872	
873	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
874	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
875	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
876	      smp->generation != bk7258_ap_boot_state()->generation ||
877	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
878	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
879	      smp->online_mask != 0x3u ||
880	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
881	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
882	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
883	      ipi->generation != bk7258_ap_boot_state()->generation ||
884	      ipi->state != BK7258_AP_IPI_STATE_READY ||
885	      ipi->error != BK7258_AP_IPI_ERROR_NONE ||
886	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE ||
887	      cpu2->online_mask != 0x3u)
888	    {
889	      return -EAGAIN;
890	    }
891	
892	  /* Initialize shared state. */
893	
894	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
895	  state->version = BK7258_AP_BDUL_STATE_VERSION;
896	  state->size = sizeof(*state);
897	  state->generation = bk7258_ap_boot_state()->generation;
898	  state->state = BK7258_AP_BDUL_STATE_INITIALIZING;
899	  state->requested = BK7258_AP_ADV_CYCLES;
900	  state->smp_tx0_before = smp->tx_count[BK7258_AP_PRIMARY_CPU];
901	  state->smp_rx1_before = smp->rx_count[BK7258_AP_SECONDARY_CPU];
902	  state->smp_tx1_before = smp->tx_count[BK7258_AP_SECONDARY_CPU];
903	  state->smp_rx0_before = smp->rx_count[BK7258_AP_PRIMARY_CPU];
904	  state->calls_before = cpu2->smp_call_requests;
905	  __asm volatile ("dmb sy" ::: "memory");
906	  state->magic = BK7258_AP_BDUL_STATE_MAGIC;
907	  __asm volatile ("dmb sy" ::: "memory");
908	
909	  /* Initialize two semaphores with count 0. */
910	
911	  for (i = 0; i < 2; i++)
912	    {
913	      ret = nxsem_init(&g_bdul_sem[i], 0, 0);
914	      if (ret < 0)
915	        {
916	          state->error = BK7258_AP_BDUL_ERROR_SEM_INIT;
917	          state->state = BK7258_AP_BDUL_STATE_FAILED;
918	          __asm volatile ("dmb sy; sev" ::: "memory");
919	          return ret;
920	        }
921	
922	#ifdef CONFIG_PRIORITY_INHERITANCE
923	      ret = nxsem_set_protocol(&g_bdul_sem[i], SEM_PRIO_NONE);
924	      if (ret < 0)
925	        {
926	          state->error = BK7258_AP_BDUL_ERROR_SEM_INIT;
927	          state->state = BK7258_AP_BDUL_STATE_FAILED;
928	          __asm volatile ("dmb sy; sev" ::: "memory");
929	          return ret;
930	        }
931	#endif
932	    }
933	
934	  /* Create task B first (mask 0x2/CPU1). */
935	
936	  ret = pthread_attr_init(&attr);
937	  if (ret != 0)
938	    {
939	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
940	      state->state = BK7258_AP_BDUL_STATE_FAILED;
941	      __asm volatile ("dmb sy; sev" ::: "memory");
942	      return -ret;
943	    }
944	
945	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
946	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset1), &cpuset1);
947	  state->state = BK7258_AP_BDUL_STATE_RUNNING;
948	  __asm volatile ("dmb sy" ::: "memory");
949	
950	  ret = pthread_create(&thread[1], &attr, bdul_task_b,
951	                       (FAR void *)state);
952	  (void)pthread_attr_destroy(&attr);
953	  if (ret != 0)
954	    {
955	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
956	      state->state = BK7258_AP_BDUL_STATE_FAILED;
957	      __asm volatile ("dmb sy; sev" ::: "memory");
958	      return -ret;
959	    }
960	
961	  /* Create task A (mask 0x2/CPU1). */
962	
963	  ret = pthread_attr_init(&attr);
964	  if (ret != 0)
965	    {
966	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
967	      state->state = BK7258_AP_BDUL_STATE_FAILED;
968	      __asm volatile ("dmb sy; sev" ::: "memory");
969	      return -ret;
970	    }
971	
972	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
973	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset1), &cpuset1);
974	
975	  ret = pthread_create(&thread[0], &attr, bdul_task_a,
976	                       (FAR void *)state);
977	  (void)pthread_attr_destroy(&attr);
978	  if (ret != 0)
979	    {
980	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
981	      state->state = BK7258_AP_BDUL_STATE_FAILED;
982	      __asm volatile ("dmb sy; sev" ::: "memory");
983	      return -ret;
984	    }
985	
986	  /* Post task A to start. */
987	
988	  ret = nxsem_post(&g_bdul_sem[0]);
989	  if (ret < 0)
990	    {
991	      state->error = BK7258_AP_BDUL_ERROR_SEM_POST;
992	      state->state = BK7258_AP_BDUL_STATE_FAILED;
993	      __asm volatile ("dmb sy; sev" ::: "memory");
994	      return ret;
995	    }
996	
997	  /* Wait for both tasks to complete and PIDs to be released. */
998	
999	  for (elapsed = 0; elapsed < timeout_ms * 3; elapsed++)
1000	    {
1001	      __asm volatile ("dmb sy" ::: "memory");
1002	      if (state->task_completed[0] != 0 && state->task_completed[1] != 0)
1003	        {
1004	          if (bk7258_ap_bdul_pid_released(thread[0]) &&
1005	              bk7258_ap_bdul_pid_released(thread[1]))
1006	            {
1007	              state->aux[0] = 1;
1008	              state->aux[1] = 1;
1009	              break;
1010	            }
1011	        }
1012	
1013	      if (state->state == BK7258_AP_BDUL_STATE_FAILED)
1014	        {
1015	          return -EIO;
1016	        }
1017	
1018	      up_mdelay(1);
1019	    }
1020	
1021	  if (elapsed == timeout_ms * 3)
1022	    {
1023	      state->error = BK7258_AP_BDUL_ERROR_WAIT_TIMEOUT;
1024	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1025	      __asm volatile ("dmb sy; sev" ::: "memory");
1026	      return -ETIMEDOUT;
1027	    }
1028	
1029	  /* Verify final counter deltas: CPU0->CPU1 +3, CPU1->CPU0 +0, calls +3 */
1030	
1031	  __asm volatile ("dmb sy" ::: "memory");
1032	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1033	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1034	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1035	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1036	  state->calls_after = cpu2->smp_call_requests;
1037	  __asm volatile ("dmb sy" ::: "memory");
1038	
1039	  if (state->state == BK7258_AP_BDUL_STATE_FAILED)
1040	    {
1041	      return -EIO;
1042	    }
1043	
1044	  if (state->smp_tx0_after != state->smp_tx0_before + 3 ||
1045	      state->smp_rx1_after != state->smp_rx1_before + 3 ||
1046	      state->smp_tx1_after != state->smp_tx1_before ||
1047	      state->smp_rx0_after != state->smp_rx0_before ||
1048	      state->calls_after != state->calls_before + 3)
1049	    {
1050	      state->error = BK7258_AP_BDUL_ERROR_COUNT_MISMATCH;
1051	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1052	      __asm volatile ("dmb sy; sev" ::: "memory");
1053	      return -EIO;
1054	    }
1055	
1056	  if (state->task_started[0] != 1 || state->task_started[1] != 1 ||
1057	      state->task_completed[0] != 1 || state->task_completed[1] != 1 ||
1058	      state->sequence[0] != BK7258_AP_ADV_CYCLES ||
1059	      state->sequence[1] != BK7258_AP_ADV_CYCLES ||
1060	      state->task_cpu[0] != BK7258_AP_SECONDARY_CPU ||
1061	      state->task_cpu[1] != BK7258_AP_SECONDARY_CPU)
1062	    {
1063	      state->error = BK7258_AP_BDUL_ERROR_COUNT_MISMATCH;
1064	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1065	      __asm volatile ("dmb sy; sev" ::: "memory");
1066	      return -EIO;
1067	    }
1068	
1069	  state->completed = BK7258_AP_ADV_CYCLES;
1070	  state->error = BK7258_AP_BDUL_ERROR_NONE;
1071	  __asm volatile ("dmb sy" ::: "memory");
1072	  state->state = BK7258_AP_BDUL_STATE_PASSED;
1073	  __asm volatile ("dmb sy; sev" ::: "memory");
