1080	 * N8-C7 Controlled Migration
1081	 ****************************************************************************/
1082	
1083	#ifdef CONFIG_BK7258_AP_SMP_CONTROLLED_MIGRATION
1084	
1085	static FAR void *bmig_migration_task(FAR void *arg)
1086	{
1087	  volatile struct bk7258_ap_advanced_state_s *state = arg;
1088	  cpu_set_t target;
1089	  cpu_set_t observed;
1090	  uint32_t cycle;
1091	  int ret;
1092	
1093	  if (state == NULL)
1094	    {
1095	      return NULL;
1096	    }
1097	
1098	  state->task_id[0] = (uint32_t)pthread_self();
1099	  state->task_cpu[0] = (uint32_t)up_cpu_index();
1100	  state->task_started[0]++;
1101	  __asm volatile ("dmb sy" ::: "memory");
1102	
1103	  for (cycle = 1; cycle <= BK7258_AP_ADV_CYCLES; cycle++)
1104	    {
1105	      /* Odd transitions target 0x2/CPU1, even target 0x1/CPU0. */
1106	
1107	      if ((cycle & 1u) != 0)
1108	        {
1109	          target = (cpu_set_t)(1u << BK7258_AP_SECONDARY_CPU);
1110	        }
1111	      else
1112	        {
1113	          target = (cpu_set_t)(1u << BK7258_AP_PRIMARY_CPU);
1114	        }
1115	
1116	      ret = pthread_setaffinity_np(pthread_self(), sizeof(target), &target);
1117	      if (ret != 0)
1118	        {
1119	          state->error = BK7258_AP_BMIG_ERROR_SETAFFINITY;
1120	          state->state = BK7258_AP_BMIG_STATE_FAILED;
1121	          __asm volatile ("dmb sy; sev" ::: "memory");
1122	          goto done;
1123	        }
1124	
1125	      /* Verify affinity and CPU. */
1126	
1127	      observed = 0;
1128	      ret = pthread_getaffinity_np(pthread_self(), sizeof(observed),
1129	                                   &observed);
1130	      if (ret != 0)
1131	        {
1132	          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
1133	          state->state = BK7258_AP_BMIG_STATE_FAILED;
1134	          __asm volatile ("dmb sy; sev" ::: "memory");
1135	          goto done;
1136	        }
1137	
1138	      if (observed != target)
1139	        {
1140	          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
1141	          state->state = BK7258_AP_BMIG_STATE_FAILED;
1142	          __asm volatile ("dmb sy; sev" ::: "memory");
1143	          goto done;
1144	        }
1145	
1146	      if ((target & (1u << BK7258_AP_SECONDARY_CPU)) != 0)
1147	        {
1148	          if (up_cpu_index() != BK7258_AP_SECONDARY_CPU)
1149	            {
1150	              state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
1151	              state->state = BK7258_AP_BMIG_STATE_FAILED;
1152	              __asm volatile ("dmb sy; sev" ::: "memory");
1153	              goto done;
1154	            }
1155	        }
1156	      else
1157	        {
1158	          if (up_cpu_index() != BK7258_AP_PRIMARY_CPU)
1159	            {
1160	              state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
1161	              state->state = BK7258_AP_BMIG_STATE_FAILED;
1162	              __asm volatile ("dmb sy; sev" ::: "memory");
1163	              goto done;
1164	            }
1165	        }
1166	
1167	      state->sequence[0] = cycle;
1168	      state->task_cpu[0] = (uint32_t)up_cpu_index();
1169	      __asm volatile ("dmb sy; sev" ::: "memory");
1170	    }
1171	
1172	done:
1173	  state->task_completed[0]++;
1174	  __asm volatile ("dmb sy; sev" ::: "memory");
1175	  return NULL;
1176	}
