1178	static int bk7258_ap_bmig_pid_released(pthread_t thread)
1179	{
1180	  pid_t pid = (pid_t)thread;
1181	  irqstate_t flags;
1182	  int released = 1;
1183	  int hash_ndx;
1184	
1185	  flags = spin_lock_irqsave_notrace(&g_pidhashlock);
1186	  if (g_pidhash != NULL && g_npidhash > 0 && pid >= 0)
1187	    {
1188	      hash_ndx = PIDHASH(pid);
1189	      if (g_pidhash[hash_ndx] != NULL &&
1190	          g_pidhash[hash_ndx]->pid == pid)
1191	        {
1192	          released = 0;
1193	        }
1194	    }
1195	
1196	  spin_unlock_irqrestore_notrace(&g_pidhashlock, flags);
1197	  return released;
1198	}
