1200	int bk7258_ap_smp_bmig_selftest(uint32_t timeout_ms)
1201	{
1202	  volatile struct bk7258_ap_advanced_state_s *state = bk7258_ap_bmig_state();
1203	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
1204	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
1205	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
1206	    bk7258_cpu2_probe_state();
1207	  pthread_attr_t attr;
1208	  pthread_t thread;
1209	  cpu_set_t cpuset = (cpu_set_t)(1u << BK7258_AP_PRIMARY_CPU);
1210	  uint32_t elapsed;
1211	  int ret;
1212	
1213	  if (timeout_ms == 0)
1214	    {
1215	      timeout_ms = BK7258_AP_ADV_TIMEOUT_MS;
1216	    }
1217	
1218	  /* Validate N8-C4 prerequisites. */
1219	
1220	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
1221	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
1222	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
1223	      smp->generation != bk7258_ap_boot_state()->generation ||
1224	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
1225	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
1226	      smp->online_mask != 0x3u ||
1227	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
1228	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
1229	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
1230	      ipi->generation != bk7258_ap_boot_state()->generation ||
1231	      ipi->state != BK7258_AP_IPI_STATE_READY ||
1232	      ipi->error != BK7258_AP_IPI_ERROR_NONE ||
1233	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE ||
1234	      cpu2->online_mask != 0x3u)
1235	    {
1236	      return -EAGAIN;
1237	    }
1238	
1239	  /* Initialize shared state. */
1240	
1241	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
1242	  state->version = BK7258_AP_BMIG_STATE_VERSION;
1243	  state->size = sizeof(*state);
1244	  state->generation = bk7258_ap_boot_state()->generation;
1245	  state->state = BK7258_AP_BMIG_STATE_INITIALIZING;
1246	  state->requested = BK7258_AP_ADV_CYCLES;
1247	  state->smp_tx0_before = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1248	  state->smp_rx1_before = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1249	  state->smp_tx1_before = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1250	  state->smp_rx0_before = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1251	  state->calls_before = cpu2->smp_call_requests;
1252	  __asm volatile ("dmb sy" ::: "memory");
1253	  state->magic = BK7258_AP_BMIG_STATE_MAGIC;
1254	  __asm volatile ("dmb sy" ::: "memory");
1255	
1256	  /* Create detached task with mask 0x1/CPU0. */
1257	
1258	  ret = pthread_attr_init(&attr);
1259	  if (ret != 0)
1260	    {
1261	      state->error = BK7258_AP_BMIG_ERROR_CREATE;
1262	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1263	      __asm volatile ("dmb sy; sev" ::: "memory");
1264	      return -ret;
1265	    }
1266	
1267	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
1268	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset), &cpuset);
1269	  state->state = BK7258_AP_BMIG_STATE_RUNNING;
1270	  __asm volatile ("dmb sy" ::: "memory");
1271	
1272	  ret = pthread_create(&thread, &attr, bmig_migration_task,
1273	                       (FAR void *)state);
1274	  (void)pthread_attr_destroy(&attr);
1275	  if (ret != 0)
1276	    {
1277	      state->error = BK7258_AP_BMIG_ERROR_CREATE;
1278	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1279	      __asm volatile ("dmb sy; sev" ::: "memory");
1280	      return -ret;
1281	    }
1282	
1283	  state->task_id[0] = (uint32_t)thread;
1284	  __asm volatile ("dmb sy" ::: "memory");
1285	
1286	  /* Wait for task to complete and PID to be released. */
1287	
1288	  for (elapsed = 0; elapsed < timeout_ms * 3; elapsed++)
1289	    {
1290	      __asm volatile ("dmb sy" ::: "memory");
1291	      if (state->task_completed[0] != 0)
1292	        {
1293	          if (bk7258_ap_bmig_pid_released(thread))
1294	            {
1295	              state->aux[0] = 1;
1296	              break;
1297	            }
1298	        }
1299	
1300	      if (state->state == BK7258_AP_BMIG_STATE_FAILED)
1301	        {
1302	          return -EIO;
1303	        }
1304	
1305	      up_mdelay(1);
1306	    }
1307	
1308	  if (elapsed == timeout_ms * 3)
1309	    {
1310	      state->error = BK7258_AP_BMIG_ERROR_TIMEOUT;
1311	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1312	      __asm volatile ("dmb sy; sev" ::: "memory");
1313	      return -ETIMEDOUT;
1314	    }
1315	
1316	  /* Verify: tx/rx +4 each direction, calls +8. */
1317	
1318	  __asm volatile ("dmb sy" ::: "memory");
1319	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1320	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1321	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1322	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1323	  state->calls_after = cpu2->smp_call_requests;
1324	  __asm volatile ("dmb sy" ::: "memory");
1325	
1326	  if (state->state == BK7258_AP_BMIG_STATE_FAILED)
1327	    {
1328	      return -EIO;
1329	    }
1330	
1331	  if (state->smp_tx0_after != state->smp_tx0_before + 4 ||
1332	      state->smp_rx1_after != state->smp_rx1_before + 4 ||
1333	      state->smp_tx1_after != state->smp_tx1_before + 4 ||
1334	      state->smp_rx0_after != state->smp_rx0_before + 4 ||
1335	      state->calls_after != state->calls_before + 8)
1336	    {
1337	      state->error = BK7258_AP_BMIG_ERROR_COUNT_MISMATCH;
1338	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1339	      __asm volatile ("dmb sy; sev" ::: "memory");
1340	      return -EIO;
1341	    }
1342	
1343	  if (state->task_started[0] != 1 || state->task_completed[0] != 1 ||
1344	      state->sequence[0] != BK7258_AP_ADV_CYCLES)
1345	    {
1346	      state->error = BK7258_AP_BMIG_ERROR_COUNT_MISMATCH;
1347	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1348	      __asm volatile ("dmb sy; sev" ::: "memory");
1349	      return -EIO;
1350	    }
1351	
1352	  state->completed = BK7258_AP_ADV_CYCLES;
1353	  state->error = BK7258_AP_BMIG_ERROR_NONE;
1354	  __asm volatile ("dmb sy" ::: "memory");
1355	  state->state = BK7258_AP_BMIG_STATE_PASSED;
1356	  __asm volatile ("dmb sy; sev" ::: "memory");
1357	  return OK;
1358	}
