1552	    {
1553	      state->error = BK7258_AP_BTIM_ERROR_TIMEOUT;
1554	      state->state = BK7258_AP_BTIM_STATE_FAILED;
1555	      __asm volatile ("dmb sy; sev" ::: "memory");
1556	      return -ETIMEDOUT;
1557	    }
1558	
1559	  /* Verify: CPU0->CPU1 +8, CPU1->CPU0 +0, calls +8. */
1560	
1561	  __asm volatile ("dmb sy" ::: "memory");
1562	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1563	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1564	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1565	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1566	  state->calls_after = cpu2->smp_call_requests;
1567	  __asm volatile ("dmb sy" ::: "memory");
1568	
1569	  if (state->state == BK7258_AP_BTIM_STATE_FAILED)
1570	    {
1571	      return -EIO;
1572	    }
1573	
1574	  if (state->smp_tx0_after != state->smp_tx0_before + 8 ||
1575	      state->smp_rx1_after != state->smp_rx1_before + 8 ||
1576	      state->smp_tx1_after != state->smp_tx1_before ||
1577	      state->smp_rx0_after != state->smp_rx0_before ||
1578	      state->calls_after != state->calls_before + 8)
1579	    {
1580	      state->error = BK7258_AP_BTIM_ERROR_COUNT_MISMATCH;
1581	      state->state = BK7258_AP_BTIM_STATE_FAILED;
1582	      __asm volatile ("dmb sy; sev" ::: "memory");
1583	      return -EIO;
1584	    }
1585	
1586	  if (state->task_started[0] != 1 || state->task_completed[0] != 1 ||
1587	      state->sequence[0] != BK7258_AP_ADV_CYCLES)
1588	    {
1589	      state->error = BK7258_AP_BTIM_ERROR_COUNT_MISMATCH;
1590	      state->state = BK7258_AP_BTIM_STATE_FAILED;
1591	      __asm volatile ("dmb sy; sev" ::: "memory");
1592	      return -EIO;
1593	    }
1594	
1595	  state->completed = BK7258_AP_ADV_CYCLES;
1596	  state->error = BK7258_AP_BTIM_ERROR_NONE;
1597	  __asm volatile ("dmb sy" ::: "memory");
1598	  state->state = BK7258_AP_BTIM_STATE_PASSED;
1599	  __asm volatile ("dmb sy; sev" ::: "memory");
1600	  return OK;
