259	static uint32_t apctl_u32(const char *value, uint32_t fallback)
260	{
261	  char *end;
262	  unsigned long parsed;
263	
264	  if (value == NULL)
265	    {
266	      return fallback;
267	    }
268	
269	  parsed = strtoul(value, &end, 0);
270	  if (*value == '\0' || *end != '\0' || parsed > UINT32_MAX)
271	    {
272	      return fallback;
273	    }
274	
275	  return (uint32_t)parsed;
276	}
