491	  state->task_id = (uint32_t)self;
492	  state->task_cpu = (uint32_t)up_cpu_index();
493	  state->task_started++;
494	  __asm volatile ("dmb sy" ::: "memory");
495	
496	  if (state->magic != BK7258_AP_AFFINITY_STATE_MAGIC ||
497	      state->version != BK7258_AP_AFFINITY_STATE_VERSION ||
498	      state->size != sizeof(struct bk7258_ap_affinity_state_s) ||
499	      state->generation != bk7258_ap_boot_state()->generation ||
500	      state->state != BK7258_AP_AFFINITY_STATE_DISPATCHING)
501	    {
502	      bk7258_ap_affinity_fail(state,
503	                             BK7258_AP_AFFINITY_ERROR_BAD_STATE);
504	      goto done;
505	    }
506	
507	  state->state = BK7258_AP_AFFINITY_STATE_RUNNING;
508	  __asm volatile ("dmb sy" ::: "memory");
509	
510	  ret = pthread_getaffinity_np(self, sizeof(observed), &observed);
511	  state->observed_mask = (uint32_t)observed;
512	
513	  if (ret != 0)
514	    {
515	      bk7258_ap_affinity_fail(state,
516	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
517	    }
518	  else if (state->task_cpu != BK7258_AP_SECONDARY_CPU)
519	    {
520	      bk7258_ap_affinity_fail(state,
521	                             BK7258_AP_AFFINITY_ERROR_BAD_CPU);
522	    }
523	  else if (state->observed_mask != state->requested_mask)
524	    {
525	      bk7258_ap_affinity_fail(state,
526	                             BK7258_AP_AFFINITY_ERROR_BAD_MASK);
527	    }
528	#ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE
529	#  ifdef CONFIG_BK7258_AP_SMP_CPU1_SEM_WAKE_LOOP
530	  else if (sem_state->magic != BK7258_AP_SEM_WAKE_STATE_MAGIC ||
531	           sem_state->version != BK7258_AP_SEM_WAKE_STATE_VERSION ||
532	           sem_state->size != sizeof(struct bk7258_ap_sem_wake_state_s) ||
533	           sem_state->generation != state->generation ||
534	           sem_state->state != BK7258_AP_SEM_WAKE_STATE_INITIALIZING ||
535	           sem_state->error != BK7258_AP_SEM_WAKE_ERROR_NONE ||
536	           loop_state->magic != BK7258_AP_SEM_WAKE_LOOP_STATE_MAGIC ||
537	           loop_state->version != BK7258_AP_SEM_WAKE_LOOP_STATE_VERSION ||
538	           loop_state->size !=
539	             sizeof(struct bk7258_ap_sem_wake_loop_state_s) ||
540	           loop_state->generation != state->generation ||
541	           loop_state->state !=
542	             BK7258_AP_SEM_WAKE_LOOP_STATE_INITIALIZING ||
543	           loop_state->error != BK7258_AP_SEM_WAKE_LOOP_ERROR_NONE ||
544	           loop_state->requested_cycles !=
545	             BK7258_AP_SEM_WAKE_LOOP_CYCLES)
546	    {
547	      bk7258_ap_sem_wake_loop_task_fail(
548	        state, sem_state, loop_state,
549	        BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_STATE, 1);
550	    }
551	  else
552	    {
553	      sem_state->task_id = (uint32_t)self;
554	      for (cycle = 1; cycle <= BK7258_AP_SEM_WAKE_LOOP_CYCLES;
555	           cycle++)
556	        {
557	          __asm volatile ("dmb sy" ::: "memory");
558	          if (loop_state->state !=
559	                (cycle == 1 ?
560	                   BK7258_AP_SEM_WAKE_LOOP_STATE_INITIALIZING :
561	                   BK7258_AP_SEM_WAKE_LOOP_STATE_CONTINUE) ||
562	              loop_state->completed_cycles != cycle - 1 ||
563	              loop_state->wait_entered != cycle - 1 ||
564	              loop_state->waiter_observed != cycle - 1 ||
565	              loop_state->post_count != cycle - 1 ||
566	              loop_state->wait_returned != cycle - 1)
567	            {
568	              bk7258_ap_sem_wake_loop_task_fail(
569	                state, sem_state, loop_state,
570	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
571	              goto done;
572	            }
573	
574	          loop_state->wait_sequence = cycle;
575	          loop_state->wait_entered++;
576	          if (cycle == 1)
577	            {
578	              sem_state->wait_entered = 1;
579	              sem_state->state = BK7258_AP_SEM_WAKE_STATE_WAITING;
580	            }
581	
582	          __asm volatile ("dmb sy" ::: "memory");
583	          loop_state->state = BK7258_AP_SEM_WAKE_LOOP_STATE_WAITING;
584	          __asm volatile ("dmb sy; sev" ::: "memory");
585	
586	          ret = nxsem_wait_uninterruptible(&g_bk7258_ap_cpu1_sem);
587	          __asm volatile ("dmb sy" ::: "memory");
588	          loop_wait_state = loop_state->state;
589	          post_sequence = loop_state->post_sequence;
590	          sem_wait_state = cycle == 1 ? sem_state->state :
591	            BK7258_AP_SEM_WAKE_STATE_POSTED;
592	          loop_state->wait_result = (int32_t)ret;
593	          loop_state->wake_cpu = (uint32_t)up_cpu_index();
594	          loop_state->wait_returned++;
595	          if (cycle == 1)
596	            {
597	              sem_state->wait_result = (int32_t)ret;
598	              sem_state->wait_returned = 1;
599	              sem_state->wake_cpu = loop_state->wake_cpu;
600	            }
601	
602	          __asm volatile ("dmb sy" ::: "memory");
603	          if (ret < 0)
604	            {
605	              bk7258_ap_sem_wake_loop_task_fail(
606	                state, sem_state, loop_state,
607	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEM_WAIT, cycle);
608	              goto done;
609	            }
610	          else if (loop_wait_state !=
611	                     BK7258_AP_SEM_WAKE_LOOP_STATE_POSTED ||
612	                   sem_wait_state != BK7258_AP_SEM_WAKE_STATE_POSTED)
613	            {
614	              bk7258_ap_sem_wake_loop_task_fail(
615	                state, sem_state, loop_state,
616	                BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_STATE, cycle);
617	              goto done;
618	            }
619	          else if (post_sequence != cycle)
620	            {
621	              bk7258_ap_sem_wake_loop_task_fail(
622	                state, sem_state, loop_state,
623	                BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
624	              goto done;
625	            }
626	          else if (loop_state->post_count != cycle)
627	            {
628	              bk7258_ap_sem_wake_loop_task_fail(
629	                state, sem_state, loop_state,
630	                BK7258_AP_SEM_WAKE_LOOP_ERROR_COUNT_MISMATCH, cycle);
631	              goto done;
632	            }
633	          else if (loop_state->wake_cpu != BK7258_AP_SECONDARY_CPU)
634	            {
635	              bk7258_ap_sem_wake_loop_task_fail(
636	                state, sem_state, loop_state,
637	                BK7258_AP_SEM_WAKE_LOOP_ERROR_BAD_CPU, cycle);
638	              goto done;
639	            }
640	
641	          loop_state->completed_cycles++;
642	          loop_state->wake_sequence = cycle;
643	          if (cycle == 1)
644	            {
645	              sem_state->state = BK7258_AP_SEM_WAKE_STATE_WOKEN;
646	            }
647	
648	          __asm volatile ("dmb sy" ::: "memory");
649	          loop_state->state = BK7258_AP_SEM_WAKE_LOOP_STATE_WOKEN;
650	          __asm volatile ("dmb sy" ::: "memory");
651	
652	          /* CPU0 publishes the loop error before FAILED.  If its bounded
653	           * abort raced this wake publication, restore terminal FAILED after
654	           * the task's last normal state writes instead of leaving
655	           * error != NONE paired with WOKEN.
656	           */
657	
658	          published_error = loop_state->error;
659	          if (published_error != BK7258_AP_SEM_WAKE_LOOP_ERROR_NONE)
660	            {
661	              bk7258_ap_sem_wake_loop_fail(loop_state, published_error);
662	              published_sem_error = sem_state->error;
663	              if (published_sem_error != BK7258_AP_SEM_WAKE_ERROR_NONE)
664	                {
665	                  bk7258_ap_sem_wake_fail(sem_state,
666	                                         published_sem_error);
667	                }
668	
669	              bk7258_ap_affinity_fail(
670	                state,
671	                bk7258_ap_sem_wake_loop_affinity_error(published_error));
672	              goto done;
673	            }
674	
675	          __asm volatile ("sev" ::: "memory");
676	
677	          if (cycle < BK7258_AP_SEM_WAKE_LOOP_CYCLES)
678	            {
679	              continued = 0;
680	              for (elapsed = 0;
681	                   elapsed < BK7258_AP_SEM_WAKE_LOOP_TIMEOUT_MS;
682	                   elapsed++)
683	                {
684	                  __asm volatile ("dmb sy" ::: "memory");
685	                  if (loop_state->state ==
686	                        BK7258_AP_SEM_WAKE_LOOP_STATE_CONTINUE &&
687	                      loop_state->completed_cycles == cycle &&
688	                      loop_state->wake_sequence == cycle)
689	                    {
690	                      continued = 1;
691	                      break;
692	                    }
693	
694	                  if (loop_state->state ==
695	                        BK7258_AP_SEM_WAKE_LOOP_STATE_FAILED ||
696	                      state->state == BK7258_AP_AFFINITY_STATE_FAILED)
697	                    {
698	                      goto done;
699	                    }
700	
701	                  if (loop_state->state !=
702	                        BK7258_AP_SEM_WAKE_LOOP_STATE_WOKEN)
703	                    {
704	                      bk7258_ap_sem_wake_loop_task_fail(
705	                        state, sem_state, loop_state,
706	                        BK7258_AP_SEM_WAKE_LOOP_ERROR_SEQUENCE, cycle);
707	                      goto done;
708	                    }
709	
710	                  __asm volatile ("wfe" ::: "memory");
711	                }
712	
713	              if (!continued)
714	                {
715	                  bk7258_ap_sem_wake_loop_task_fail(
716	                    state, sem_state, loop_state,
717	                    BK7258_AP_SEM_WAKE_LOOP_ERROR_WAKE_TIMEOUT, cycle);
718	                  goto done;
719	                }
720	            }
721	        }
722	    }
723	#  else
724	  else if (sem_state->magic != BK7258_AP_SEM_WAKE_STATE_MAGIC ||
725	           sem_state->version != BK7258_AP_SEM_WAKE_STATE_VERSION ||
726	           sem_state->size != sizeof(struct bk7258_ap_sem_wake_state_s) ||
727	           sem_state->generation != state->generation ||
728	           sem_state->state != BK7258_AP_SEM_WAKE_STATE_INITIALIZING ||
729	           sem_state->error != BK7258_AP_SEM_WAKE_ERROR_NONE)
730	    {
731	      bk7258_ap_sem_wake_fail(sem_state,
732	                             BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
733	    }
734	  else
735	    {
736	      sem_state->task_id = (uint32_t)self;
737	      sem_state->wait_entered = 1;
738	      sem_state->state = BK7258_AP_SEM_WAKE_STATE_WAITING;
739	      __asm volatile ("dmb sy; sev" ::: "memory");
740	
741	      ret = nxsem_wait_uninterruptible(&g_bk7258_ap_cpu1_sem);
742	      __asm volatile ("dmb sy" ::: "memory");
743	      wait_state = sem_state->state;
744	      sem_state->wait_result = (int32_t)ret;
745	      sem_state->wait_returned = 1;
746	      sem_state->wake_cpu = (uint32_t)up_cpu_index();
747	      __asm volatile ("dmb sy" ::: "memory");
748	
749	      if (ret < 0)
750	        {
751	          bk7258_ap_sem_wake_fail(sem_state,
752	                                 BK7258_AP_SEM_WAKE_ERROR_SEM_WAIT);
753	        }
754	      else if (wait_state != BK7258_AP_SEM_WAKE_STATE_POSTED)
755	        {
756	          bk7258_ap_sem_wake_fail(sem_state,
757	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_STATE);
758	        }
759	      else if (sem_state->wake_cpu != BK7258_AP_SECONDARY_CPU)
760	        {
761	          bk7258_ap_sem_wake_fail(sem_state,
762	                                 BK7258_AP_SEM_WAKE_ERROR_BAD_CPU);
763	        }
764	      else
765	        {
766	          sem_state->state = BK7258_AP_SEM_WAKE_STATE_WOKEN;
767	          __asm volatile ("dmb sy; sev" ::: "memory");
768	        }
769	    }
770	#  endif
771	#endif
772	
773	done:
774	  state->task_completed++;
775	  __asm volatile ("dmb sy; sev" ::: "memory");
776	  return NULL;
777	}
778	#endif
