780	static void __attribute__((noinline, noreturn, used))
781	bk7258_ap_secondary_scheduler_entry(void)
782	{
783	  volatile struct bk7258_cpu2_probe_state_s *state =
784	    bk7258_cpu2_probe_state();
785	  uint32_t control;
786	  uint32_t msp;
787	
788	  arm_initialize_stack();
789	  __asm volatile ("mrs %0, msp" : "=r" (msp));
790	  __asm volatile ("mrs %0, control" : "=r" (control));
791	
792	  state->runtime_msp = msp;
793	  state->control = control;
794	  state->online_mask = BK7258_AP_ONLINE_MASK;
795	  state->secondary_ready = 1;
796	
797	#ifdef CONFIG_SCHED_INSTRUMENTATION
798	  sched_note_cpu_started(this_task());
799	#endif
800	
801	  bk7258_ap_ipi_mark_scheduler_online();
802	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
803	  state->state = BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE;
804	  __asm volatile ("dmb sy; sev" ::: "memory");
805	
806	  nx_idle_trampoline();
807	
808	  bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
809	  for (; ; )
810	    {
811	      __asm volatile ("wfe");
812	    }
813	}
