815	static void __attribute__((naked, noreturn, used))
816	bk7258_ap_secondary_enter_scheduler(
817	  uint32_t stack_top __attribute__((unused)))
818	{
819	  __asm volatile
820	    (
821	      "msr msp, r0\n"
822	      "dsb sy\n"
823	      "isb sy\n"
824	      "b bk7258_ap_secondary_scheduler_entry\n"
825	    );
826	}
827	#endif
