829	static void __attribute__((noinline, noreturn, used))
830	bk7258_ap_secondary_bootstrap(void)
831	{
832	  volatile struct bk7258_cpu2_probe_state_s *state;
833	
834	  bk7258_cpu2_fpu_initialize();
835	  state = bk7258_cpu2_probe_state();
836	  uint32_t control;
837	  uint32_t msp;
838	
839	  __asm volatile ("mrs %0, msp" : "=r" (msp));
840	  __asm volatile ("mrs %0, control" : "=r" (control));
841	
842	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
843	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
844	  state->runtime_vtor = BK7258_SCB_VTOR;
845	  state->runtime_msp = msp;
846	  state->control = control;
847	  state->boot_count++;
848	  __asm volatile ("dmb sy" ::: "memory");
849	
850	  if (state->magic != BK7258_CPU2_PROBE_STATE_MAGIC ||
851	      state->version != BK7258_CPU2_PROBE_STATE_VERSION ||
852	      state->size != sizeof(struct bk7258_cpu2_probe_state_s))
853	    {
854	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_BOOT_STATE);
855	      goto parked;
856	    }
857	
858	  state->state = BK7258_CPU2_PROBE_STATE_BOOTSTRAP;
859	  __asm volatile ("dmb sy" ::: "memory");
860	
861	  if (*(volatile uint32_t *)BK7258_LOCAL_CORE_ID_ADDR !=
862	        BK7258_CPU2_LOCAL_CORE_ID ||
863	      state->physical_core_id != BK7258_CPU2_PHYSICAL_ID)
864	    {
865	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_CORE_ID);
866	      goto parked;
867	    }
868	
869	  if (state->runtime_vtor !=
870	      (uint32_t)(uintptr_t)__vector_core1_table)
871	    {
872	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_VTOR);
873	      goto parked;
874	    }
875	
876	  if (msp <= BK7258_CPU2_BOOT_STACK_BASE ||
877	      msp > BK7258_CPU2_BOOT_STACK_TOP)
878	    {
879	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_MSP);
880	      goto parked;
881	    }
882	
883	  if (state->idle_stack_base < BK7258_AP_RAM_BASE ||
884	      state->idle_stack_base >= state->idle_stack_top ||
885	      state->idle_stack_top > BK7258_CPU2_BOOT_STACK_BASE)
886	    {
887	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
888	      goto parked;
889	    }
890	
891	#ifdef CONFIG_BK7258_AP_IPI
892	  if (bk7258_ap_ipi_secondary_initialize() < 0)
893	    {
894	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
895	      goto parked;
896	    }
897	#endif
898	
899	  state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
900	  state->error = BK7258_CPU2_PROBE_ERROR_NONE;
901	  state->online_mask = BK7258_AP_PRIMARY_MASK;
902	
903	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
904	  state->secondary_ready = 0;
905	  __asm volatile ("dmb sy" ::: "memory");
906	
907	  if (bk7258_cpu2_scheduler_irq_initialize() < 0)
908	    {
909	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
910	      goto parked;
911	    }
912	
913	  bk7258_ap_secondary_enter_scheduler(state->idle_stack_top);
914	#else
915	  state->secondary_ready = 1;
916	  __asm volatile ("dmb sy" ::: "memory");
917	  state->state = BK7258_CPU2_PROBE_STATE_SECONDARY_READY;
918	  __asm volatile ("dmb sy; sev" ::: "memory");
919	
920	#  ifdef CONFIG_BK7258_AP_IPI
921	  __asm volatile ("cpsie i; dsb sy; isb sy" ::: "memory");
922	#  endif
923	
924	  for (; ; )
925	    {
926	      __asm volatile ("dmb sy" ::: "memory");
927	      if (state->command == BK7258_CPU2_PROBE_COMMAND_STOP)
928	        {
929	          state->state = BK7258_CPU2_PROBE_STATE_STOPPING;
930	          state->secondary_ready = 0;
931	          __asm volatile ("dmb sy" ::: "memory");
932	          state->command = BK7258_CPU2_PROBE_COMMAND_NONE;
933	          state->state = BK7258_CPU2_PROBE_STATE_STOPPED;
934	          __asm volatile ("dmb sy; sev" ::: "memory");
935	          goto parked;
936	        }
937	
938	      state->heartbeat++;
939	#  ifdef CONFIG_BK7258_AP_IPI
940	      __asm volatile ("dmb sy; dsb sy; wfi" ::: "memory");
941	#  else
942	      __asm volatile ("dmb sy; wfe" ::: "memory");
943	#  endif
944	    }
945	#endif
946	
947	parked:
948	  __asm volatile ("cpsid i; dsb sy; isb sy" ::: "memory");
949	  for (; ; )
950	    {
951	      __asm volatile ("wfe");
952	    }
953	}
