955	static void __attribute__((naked, noreturn, used))
956	bk7258_ap_secondary_reset(void)
957	{
958	  __asm volatile
959	    (
960	      "cpsid i\n"
961	      "movs r0, #0\n"
962	      "msr control, r0\n"
963	      "msr basepri, r0\n"
964	      "msr faultmask, r0\n"
965	      "ldr r0, =0x20000000\n"
966	      "movs r1, #1\n"
967	      "str r1, [r0]\n"
968	      "ldr r0, =__vector_core1_table\n"
969	      "ldr r1, =0xe000ed08\n"
970	      "str r0, [r1]\n"
971	      "dsb sy\n"
972	      "isb sy\n"
973	      "b bk7258_ap_secondary_bootstrap\n"
974	    );
975	}
