977	static void __attribute__((noinline, noreturn, used))
978	bk7258_ap_secondary_fault_handler(uint32_t *stack, uint32_t exception)
979	{
980	  volatile struct bk7258_cpu2_probe_state_s *state =
981	    bk7258_cpu2_probe_state();
982	  uintptr_t frame = (uintptr_t)stack;
983	  uint32_t error;
984	
985	  state->fault_exception = exception;
986	  state->fault_hfsr = BK7258_SCB_HFSR;
987	  state->fault_cfsr = BK7258_SCB_CFSR;
988	  state->fault_lr = BK7258_CPU2_INVALID_VALUE;
989	  state->fault_pc = BK7258_CPU2_INVALID_VALUE;
990	  state->fault_xpsr = BK7258_CPU2_INVALID_VALUE;
991	
992	  if ((frame & (sizeof(uint32_t) - 1u)) == 0 &&
993	      ((frame >= BK7258_CPU2_BOOT_STACK_BASE &&
994	        frame <= BK7258_CPU2_BOOT_STACK_TOP -
995	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
996	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
997	       ||
998	       (frame >= state->idle_stack_base &&
999	        frame <= state->idle_stack_top -
1000	                 BK7258_CPU2_FRAME_WORDS * sizeof(uint32_t))
1001	#endif
1002	      ))
1003	    {
1004	      const volatile uint32_t *regs =
1005	        (const volatile uint32_t *)frame;
1006	
1007	      state->fault_lr = regs[5];
1008	      state->fault_pc = regs[6];
1009	      state->fault_xpsr = regs[7];
1010	    }
1011	
1012	  error = exception == 2u ?
1013	    BK7258_CPU2_PROBE_ERROR_NMI :
1014	    BK7258_CPU2_PROBE_ERROR_HARDFAULT;
1015	  bk7258_cpu2_fail(error);
1016	
1017	  for (; ; )
1018	    {
1019	      __asm volatile ("wfe");
1020	    }
1021	}
