1023	static void __attribute__((naked, noreturn, used))
1024	bk7258_ap_secondary_fault_entry(void)
1025	{
1026	  __asm volatile
1027	    (
1028	      "tst lr, #4\n"
1029	      "ite eq\n"
1030	      "mrseq r0, msp\n"
1031	      "mrsne r0, psp\n"
1032	      "mrs r1, ipsr\n"
1033	      "b bk7258_ap_secondary_fault_handler\n"
1034	    );
1035	}
