1077	int up_cpu_start(int cpu)
1078	{
1079	  volatile struct bk7258_cpu2_probe_state_s *state =
1080	    bk7258_cpu2_probe_state();
1081	  volatile uint32_t *control = bk7258_cpu2_control();
1082	  struct tcb_s *tcb;
1083	  uintptr_t idle_base;
1084	  uintptr_t idle_top;
1085	  uint32_t generation;
1086	  uint32_t value;
1087	  int ret;
1088	
1089	  if (cpu != BK7258_AP_SECONDARY_CPU)
1090	    {
1091	      return -EINVAL;
1092	    }
1093	
1094	  bk7258_cpu2_hold_reset(state);
1095	  up_mdelay(1);
1096	
1097	  generation = bk7258_ap_boot_state()->generation;
1098	  if (generation == 0)
1099	    {
1100	      generation = 1;
1101	    }
1102	
1103	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
1104	  state->version = BK7258_CPU2_PROBE_STATE_VERSION;
1105	  state->size = sizeof(*state);
1106	  state->generation = generation;
1107	  state->command = BK7258_CPU2_PROBE_COMMAND_START;
1108	  state->state = BK7258_CPU2_PROBE_STATE_STARTING;
1109	  state->local_core_id = BK7258_CPU2_LOCAL_CORE_ID;
1110	  state->physical_core_id = BK7258_CPU2_PHYSICAL_ID;
1111	  state->vector = (uint32_t)(uintptr_t)__vector_core1_table;
1112	  state->initial_msp = BK7258_CPU2_BOOT_STACK_TOP;
1113	  state->secondary_entry =
1114	    (uint32_t)(uintptr_t)bk7258_ap_secondary_bootstrap;
1115	  state->online_mask = BK7258_AP_PRIMARY_MASK;
1116	
1117	  tcb = current_task(cpu);
1118	  if (tcb == NULL || tcb->stack_base_ptr == NULL ||
1119	      tcb->adj_stack_size == 0)
1120	    {
1121	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1122	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
1123	      return -ENOMEM;
1124	    }
1125	
1126	  idle_base = (uintptr_t)tcb->stack_base_ptr;
1127	  idle_top = idle_base + tcb->adj_stack_size;
1128	  state->idle_stack_base = (uint32_t)idle_base;
1129	  state->idle_stack_top = (uint32_t)idle_top;
1130	
1131	  if (idle_base < BK7258_AP_RAM_BASE || idle_base >= idle_top ||
1132	      idle_top > BK7258_CPU2_BOOT_STACK_BASE)
1133	    {
1134	      state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1135	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_BAD_IDLE_STACK);
1136	      return -ENOMEM;
1137	    }
1138	
1139	  value = *control;
1140	  state->control_before = value;
1141	  value &= ~(BK7258_SYS_CPU2_RESET |
1142	             BK7258_SYS_CPU2_POWER_DOWN |
1143	             BK7258_SYS_CPU2_HALT |
1144	             BK7258_SYS_CPU2_RXEVT_SEL |
1145	             BK7258_SYS_CPU2_BOOT_MASK);
1146	  value |= BK7258_SYS_CPU2_RXEVT_SEL;
1147	  value |= state->vector & BK7258_SYS_CPU2_BOOT_MASK;
1148	  *control = value;
1149	  __asm volatile ("dsb sy; isb sy" ::: "memory");
1150	
1151	  state->control_after = value;
1152	  __asm volatile ("dmb sy" ::: "memory");
1153	  state->magic = BK7258_CPU2_PROBE_STATE_MAGIC;
1154	  __asm volatile ("dmb sy" ::: "memory");
1155	
1156	#ifdef CONFIG_BK7258_AP_IPI
1157	  ret = bk7258_ap_ipi_primary_initialize();
1158	  if (ret < 0)
1159	    {
1160	      bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_IPI_INIT);
1161	      return ret;
1162	    }
1163	#endif
1164	
1165	  value |= BK7258_SYS_CPU2_RESET;
1166	  *control = value;
1167	  state->control_after = value;
1168	  __asm volatile ("dsb sy; sev" ::: "memory");
1169	
1170	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1171	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE,
1172	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
1173	#else
1174	  ret = bk7258_cpu2_wait(BK7258_CPU2_PROBE_STATE_SECONDARY_READY,
1175	                         BK7258_CPU2_PROBE_TIMEOUT_MS);
1176	#endif
1177	  if (ret < 0)
1178	    {
1179	      bk7258_cpu2_hold_reset(state);
1180	      if (state->state != BK7258_CPU2_PROBE_STATE_FAILED)
1181	        {
1182	          bk7258_cpu2_fail(BK7258_CPU2_PROBE_ERROR_TIMEOUT);
1183	        }
1184	    }
1185	
1186	  return ret;
1187	}
