1238	#ifdef CONFIG_BK7258_AP_SMP_SCHED_ONLINE
1239	int bk7258_ap_smp_scheduler_selftest(uint32_t timeout_ms)
1240	{
1241	  volatile struct bk7258_ap_smp_state_s *state = bk7258_ap_smp_state();
1242	  uint32_t elapsed;
1243	  int cpu;
1244	  int ret;
1245	
1246	  if (timeout_ms == 0)
1247	    {
1248	      timeout_ms = BK7258_AP_SMP_DEFAULT_TIMEOUT_MS;
1249	    }
1250	
1251	  if (state->magic != BK7258_AP_SMP_STATE_MAGIC ||
1252	      state->version != BK7258_AP_SMP_STATE_VERSION ||
1253	      state->size != sizeof(struct bk7258_ap_smp_state_s) ||
1254	      state->generation != bk7258_ap_boot_state()->generation ||
1255	      state->state != BK7258_AP_SMP_STATE_ONLINE ||
1256	      state->online_mask != BK7258_AP_ONLINE_MASK)
1257	    {
1258	      return -EAGAIN;
1259	    }
1260	
1261	  state->error = BK7258_AP_SMP_ERROR_NONE;
1262	  state->requested_count = 2;
1263	  state->completed_count = 0;
1264	  state->test_runs++;
1265	  state->last_callback_cpu = UINT32_MAX;
1266	
1267	  for (cpu = 0; cpu < CONFIG_SMP_NCPUS; cpu++)
1268	    {
1269	      state->tx_count[cpu] = 0;
1270	      state->rx_count[cpu] = 0;
1271	      state->coalesced_count[cpu] = 0;
1272	      state->send_failures[cpu] = 0;
1273	      state->call_handler_count[cpu] = 0;
1274	      state->delivered_handler_count[cpu] = 0;
1275	      state->callback_count[cpu] = 0;
1276	      state->last_command[cpu] = 0;
1277	    }
1278	
1279	  __asm volatile ("dmb sy" ::: "memory");
1280	  state->state = BK7258_AP_SMP_STATE_TESTING;
1281	  __asm volatile ("dmb sy" ::: "memory");
1282	
1283	  nxsched_smp_call_init(&g_bk7258_ap_smp_forward_call,
1284	                        bk7258_ap_smp_secondary_callback,
1285	                        (FAR void *)state);
1286	  ret = nxsched_smp_call_single_async(BK7258_AP_SECONDARY_CPU,
1287	                                      &g_bk7258_ap_smp_forward_call);
1288	  if (ret < 0)
1289	    {
1290	      state->error = BK7258_AP_SMP_ERROR_CALL;
1291	      state->state = BK7258_AP_SMP_STATE_FAILED;
1292	      __asm volatile ("dmb sy; sev" ::: "memory");
1293	      return ret;
1294	    }
1295	
1296	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
1297	    {
1298	      __asm volatile ("dmb sy" ::: "memory");
1299	      if (state->callback_count[BK7258_AP_PRIMARY_CPU] == 1 &&
1300	          state->callback_count[BK7258_AP_SECONDARY_CPU] == 1)
1301	        {
1302	          break;
1303	        }
1304	
1305	      if (state->state == BK7258_AP_SMP_STATE_FAILED)
1306	        {
1307	          return -EIO;
1308	        }
1309	
1310	      up_mdelay(1);
1311	    }
1312	
1313	  if (elapsed == timeout_ms)
1314	    {
1315	      state->error = BK7258_AP_SMP_ERROR_TIMEOUT;
1316	      state->state = BK7258_AP_SMP_STATE_FAILED;
1317	      __asm volatile ("dmb sy; sev" ::: "memory");
1318	      return -ETIMEDOUT;
1319	    }
1320	
1321	  if (state->tx_count[0] < 1 || state->tx_count[1] < 1 ||
1322	      state->rx_count[0] < 1 || state->rx_count[1] < 1 ||
1323	      state->call_handler_count[0] < 1 ||
1324	      state->call_handler_count[1] < 1 ||
1325	      state->delivered_handler_count[0] < 1 ||
1326	      state->delivered_handler_count[1] < 1 ||
1327	      state->send_failures[0] != 0 ||
1328	      state->send_failures[1] != 0 ||
1329	      state->last_callback_cpu != BK7258_AP_PRIMARY_CPU)
1330	    {
1331	      state->error = BK7258_AP_SMP_ERROR_COUNT_MISMATCH;
1332	      state->state = BK7258_AP_SMP_STATE_FAILED;
1333	      __asm volatile ("dmb sy; sev" ::: "memory");
1334	      return -EIO;
1335	    }
1336	
1337	  state->completed_count = 2;
1338	  state->error = BK7258_AP_SMP_ERROR_NONE;
1339	  __asm volatile ("dmb sy" ::: "memory");
1340	  state->state = BK7258_AP_SMP_STATE_PASSED;
1341	  __asm volatile ("dmb sy; sev" ::: "memory");
1342	  return OK;
1343	}
1344	#endif
