186	static int bk7258_ap_wait(uint32_t wanted, uint32_t timeout_ms)
187	{
188	  volatile struct bk7258_ap_boot_state_s *state = bk7258_ap_boot_state();
189	  uint32_t elapsed;
190	  uint32_t event;
191	
192	  if (timeout_ms == 0)
193	    {
194	      timeout_ms = BK7258_AP_DEFAULT_TIMEOUT_MS;
195	    }
196	
197	  for (elapsed = 0; elapsed < timeout_ms; elapsed++)
198	    {
199	      event = bk7258_ap_mbox_receive();
200	      if (event != BK7258_AP_EVENT_NONE)
201	        {
202	          state->last_event = event;
203	        }
204	
205	      __asm volatile ("dmb sy" ::: "memory");
206	      if (state->state == wanted)
207	        {
208	          return OK;
209	        }
210	
211	      if (state->state == BK7258_AP_STATE_FAILED)
212	        {
213	          return -EIO;
214	        }
215	
216	      nxsig_usleep(1000);
217	    }
218	
219	  return -ETIMEDOUT;
220	}
