608	
609	  timeout = apctl_u32(argc > 2 ? argv[2] : NULL,
610	                      BK7258_AP_DEFAULT_TIMEOUT_MS);
611	
612	  if (strcmp(argv[1], "start") == 0)
613	    {
614	      ret = bk7258_ap_start(timeout);
615	    }
616	  else if (strcmp(argv[1], "stop") == 0)
617	    {
618	      ret = bk7258_ap_stop(timeout);
619	    }
620	  else if (strcmp(argv[1], "restart") == 0)
621	    {
622	      ret = bk7258_ap_restart(timeout);
623	    }
624	  else if (strcmp(argv[1], "status") == 0)
625	    {
626	      apctl_status();
627	      return 0;
628	    }
629	  else if (strcmp(argv[1], "ipitest") == 0)
630	    {
631	      count = apctl_u32(argc > 2 ? argv[2] : NULL,
632	                        BK7258_AP_IPI_DEFAULT_COUNT);
