933	int bk7258_ap_smp_bdul_selftest(uint32_t timeout_ms)
934	{
935	  volatile struct bk7258_ap_advanced_state_s *state = bk7258_ap_bdul_state();
936	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
937	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
938	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
939	    bk7258_cpu2_probe_state();
940	  pthread_attr_t attr;
941	  pthread_t thread[2];
942	  cpu_set_t cpuset1 = (cpu_set_t)(1u << BK7258_AP_SECONDARY_CPU);
943	  uint32_t elapsed;
944	  int ret;
945	  int i;
946	
947	  if (timeout_ms == 0)
948	    {
949	      timeout_ms = BK7258_AP_ADV_TIMEOUT_MS;
950	    }
951	
952	  /* Validate N8-C4 prerequisites. */
953	
954	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
955	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
956	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
957	      smp->generation != bk7258_ap_boot_state()->generation ||
958	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
959	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
960	      smp->online_mask != 0x3u ||
961	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
962	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
963	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
964	      ipi->generation != bk7258_ap_boot_state()->generation ||
965	      ipi->state != BK7258_AP_IPI_STATE_READY ||
966	      ipi->error != BK7258_AP_IPI_ERROR_NONE ||
967	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE ||
968	      cpu2->online_mask != 0x3u)
969	    {
970	      return -EAGAIN;
971	    }
972	
973	  /* Initialize shared state. */
974	
975	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
976	  state->version = BK7258_AP_BDUL_STATE_VERSION;
977	  state->size = sizeof(*state);
978	  state->generation = bk7258_ap_boot_state()->generation;
979	  state->state = BK7258_AP_BDUL_STATE_INITIALIZING;
980	  state->requested = BK7258_AP_ADV_CYCLES;
981	  state->smp_tx0_before = smp->tx_count[BK7258_AP_PRIMARY_CPU];
982	  state->smp_rx1_before = smp->rx_count[BK7258_AP_SECONDARY_CPU];
983	  state->smp_tx1_before = smp->tx_count[BK7258_AP_SECONDARY_CPU];
984	  state->smp_rx0_before = smp->rx_count[BK7258_AP_PRIMARY_CPU];
985	  state->calls_before = cpu2->smp_call_requests;
986	  __asm volatile ("dmb sy" ::: "memory");
987	  state->magic = BK7258_AP_BDUL_STATE_MAGIC;
988	  __asm volatile ("dmb sy" ::: "memory");
989	
990	  /* Initialize two semaphores with count 0. */
991	
992	  for (i = 0; i < 2; i++)
993	    {
994	      ret = nxsem_init(&g_bdul_sem[i], 0, 0);
995	      if (ret < 0)
996	        {
997	          state->error = BK7258_AP_BDUL_ERROR_SEM_INIT;
998	          state->state = BK7258_AP_BDUL_STATE_FAILED;
999	          __asm volatile ("dmb sy; sev" ::: "memory");
1000	          return ret;
1001	        }
1002	
1003	#ifdef CONFIG_PRIORITY_INHERITANCE
1004	      ret = nxsem_set_protocol(&g_bdul_sem[i], SEM_PRIO_NONE);
1005	      if (ret < 0)
1006	        {
1007	          state->error = BK7258_AP_BDUL_ERROR_SEM_INIT;
1008	          state->state = BK7258_AP_BDUL_STATE_FAILED;
1009	          __asm volatile ("dmb sy; sev" ::: "memory");
1010	          return ret;
1011	        }
1012	#endif
1013	    }
1014	
1015	  /* Create task B first (mask 0x2/CPU1). */
1016	
1017	  ret = pthread_attr_init(&attr);
1018	  if (ret != 0)
1019	    {
1020	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
1021	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1022	      __asm volatile ("dmb sy; sev" ::: "memory");
1023	      return -ret;
1024	    }
1025	
1026	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
1027	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset1), &cpuset1);
1028	  state->state = BK7258_AP_BDUL_STATE_RUNNING;
1029	  __asm volatile ("dmb sy" ::: "memory");
1030	
1031	  ret = pthread_create(&thread[1], &attr, bdul_task_b,
1032	                       (FAR void *)state);
1033	  (void)pthread_attr_destroy(&attr);
1034	  if (ret != 0)
1035	    {
1036	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
1037	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1038	      __asm volatile ("dmb sy; sev" ::: "memory");
1039	      return -ret;
1040	    }
1041	
1042	  /* Create task A (mask 0x2/CPU1). */
1043	
1044	  ret = pthread_attr_init(&attr);
1045	  if (ret != 0)
1046	    {
1047	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
1048	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1049	      __asm volatile ("dmb sy; sev" ::: "memory");
1050	      return -ret;
1051	    }
1052	
1053	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
1054	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset1), &cpuset1);
1055	
1056	  ret = pthread_create(&thread[0], &attr, bdul_task_a,
1057	                       (FAR void *)state);
1058	  (void)pthread_attr_destroy(&attr);
1059	  if (ret != 0)
1060	    {
1061	      state->error = BK7258_AP_BDUL_ERROR_CREATE;
1062	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1063	      __asm volatile ("dmb sy; sev" ::: "memory");
1064	      return -ret;
1065	    }
1066	
1067	  /* Post task A to start. */
1068	
1069	  ret = nxsem_post(&g_bdul_sem[0]);
1070	  if (ret < 0)
1071	    {
1072	      state->error = BK7258_AP_BDUL_ERROR_SEM_POST;
1073	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1074	      __asm volatile ("dmb sy; sev" ::: "memory");
1075	      return ret;
1076	    }
1077	
1078	  /* Wait for both tasks to complete and PIDs to be released. */
1079	
1080	  for (elapsed = 0; elapsed < timeout_ms * 3; elapsed++)
1081	    {
1082	      __asm volatile ("dmb sy" ::: "memory");
1083	      if (state->task_completed[0] != 0 && state->task_completed[1] != 0)
1084	        {
1085	          if (bk7258_ap_bdul_pid_released(thread[0]) &&
1086	              bk7258_ap_bdul_pid_released(thread[1]))
1087	            {
1088	              state->aux[0] = 1;
1089	              state->aux[1] = 1;
1090	              break;
1091	            }
1092	        }
1093	
1094	      if (state->state == BK7258_AP_BDUL_STATE_FAILED)
1095	        {
1096	          return -EIO;
1097	        }
1098	
1099	      up_mdelay(1);
1100	    }
1101	
1102	  if (elapsed == timeout_ms * 3)
1103	    {
1104	      state->error = BK7258_AP_BDUL_ERROR_WAIT_TIMEOUT;
1105	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1106	      __asm volatile ("dmb sy; sev" ::: "memory");
1107	      return -ETIMEDOUT;
1108	    }
1109	
1110	  /* Verify final counter deltas: CPU0->CPU1 +3, CPU1->CPU0 +0, calls +3 */
1111	
1112	  __asm volatile ("dmb sy" ::: "memory");
1113	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1114	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1115	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1116	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1117	  state->calls_after = cpu2->smp_call_requests;
1118	  __asm volatile ("dmb sy" ::: "memory");
1119	
1120	  if (state->state == BK7258_AP_BDUL_STATE_FAILED)
1121	    {
1122	      return -EIO;
1123	    }
1124	
1125	  if (state->smp_tx0_after != state->smp_tx0_before + 3 ||
1126	      state->smp_rx1_after != state->smp_rx1_before + 3 ||
1127	      state->smp_tx1_after != state->smp_tx1_before ||
1128	      state->smp_rx0_after != state->smp_rx0_before ||
1129	      state->calls_after != state->calls_before + 3)
1130	    {
1131	      state->error = BK7258_AP_BDUL_ERROR_COUNT_MISMATCH;
1132	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1133	      __asm volatile ("dmb sy; sev" ::: "memory");
1134	      return -EIO;
1135	    }
1136	
1137	  if (state->task_started[0] != 1 || state->task_started[1] != 1 ||
1138	      state->task_completed[0] != 1 || state->task_completed[1] != 1 ||
1139	      state->sequence[0] != BK7258_AP_ADV_CYCLES ||
1140	      state->sequence[1] != BK7258_AP_ADV_CYCLES ||
1141	      state->task_cpu[0] != BK7258_AP_SECONDARY_CPU ||
1142	      state->task_cpu[1] != BK7258_AP_SECONDARY_CPU)
1143	    {
1144	      state->error = BK7258_AP_BDUL_ERROR_COUNT_MISMATCH;
1145	      state->state = BK7258_AP_BDUL_STATE_FAILED;
1146	      __asm volatile ("dmb sy; sev" ::: "memory");
1147	      return -EIO;
1148	    }
1149

650	  state->state = BK7258_AP_BP2P_STATE_PASSED;
651	  __asm volatile ("dmb sy; sev" ::: "memory");
652	  return OK;
653	}
