663	static int32_t bdul_exact_waiter(sem_t *sem, pthread_t thread,
664	                                  cpu_set_t cpuset)
665	{
666	  FAR struct tcb_s *tcb;
667	  irqstate_t flags;
668	  int32_t observed = INT32_MAX;
669	  int value = 0;
670	  int ret;
671	
672	  tcb = nxsched_get_tcb((pid_t)thread);
673	  if (tcb == NULL)
674	    {
675	      return observed;
676	    }
677	
678	  flags = enter_critical_section();
679	  ret = nxsem_get_value(sem, &value);
680	  if (ret >= 0 &&
681	      tcb->task_state == TSTATE_WAIT_SEM &&
682	      tcb->waitobj == (FAR void *)sem &&
683	      value == -1 && tcb->affinity == cpuset)
684	    {
685	      observed = (int32_t)value;
686	    }
687	
688	  leave_critical_section(flags);
689	  nxsched_put_tcb(tcb);
690	  __asm volatile ("dmb sy" ::: "memory");
691	  return observed;
692	}
