1249	          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
1250	          state->state = BK7258_AP_BMIG_STATE_FAILED;
1251	          __asm volatile ("dmb sy; sev" ::: "memory");
1252	          goto done;
1253	        }
1254	
1255	      if (observed != target)
1256	        {
1257	          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
1258	          state->state = BK7258_AP_BMIG_STATE_FAILED;
1259	          __asm volatile ("dmb sy; sev" ::: "memory");
1260	          goto done;
1261	        }
1262	
1263	      if ((target & (1u << BK7258_AP_SECONDARY_CPU)) != 0)
1264	        {
1265	          if (up_cpu_index() != BK7258_AP_SECONDARY_CPU)
1266	            {
1267	              state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
1268	              state->state = BK7258_AP_BMIG_STATE_FAILED;
1269	              __asm volatile ("dmb sy; sev" ::: "memory");
1270	              goto done;
1271	            }
1272	        }
1273	      else
1274	        {
1275	          if (up_cpu_index() != BK7258_AP_PRIMARY_CPU)
1276	            {
1277	              state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
1278	              state->state = BK7258_AP_BMIG_STATE_FAILED;
1279	              __asm volatile ("dmb sy; sev" ::: "memory");
1280	              goto done;
1281	            }
1282	        }
1283	
1284	      state->sequence[0] = cycle;
1285	      state->task_cpu[0] = (uint32_t)up_cpu_index();
1286	      __asm volatile ("dmb sy; sev" ::: "memory");
1287	    }
1288	
1289	done:
1290	  state->task_completed[0]++;
1291	  __asm volatile ("dmb sy; sev" ::: "memory");
1292	  return NULL;
1293	}
