1295	static int bk7258_ap_bmig_pid_released(pthread_t thread)
1296	{
1297	  pid_t pid = (pid_t)thread;
1298	  irqstate_t flags;
1299	  int released = 1;
1300	  int hash_ndx;
1301	
1302	  flags = spin_lock_irqsave_notrace(&g_pidhashlock);
1303	  if (g_pidhash != NULL && g_npidhash > 0 && pid >= 0)
1304	    {
1305	      hash_ndx = PIDHASH(pid);
1306	      if (g_pidhash[hash_ndx] != NULL &&
1307	          g_pidhash[hash_ndx]->pid == pid)
1308	        {
1309	          released = 0;
1310	        }
1311	    }
1312	
1313	  spin_unlock_irqrestore_notrace(&g_pidhashlock, flags);
1314	  return released;
1315	}
