1317	int bk7258_ap_smp_bmig_selftest(uint32_t timeout_ms)
1318	{
1319	  volatile struct bk7258_ap_advanced_state_s *state = bk7258_ap_bmig_state();
1320	  volatile struct bk7258_ap_smp_state_s *smp = bk7258_ap_smp_state();
1321	  volatile struct bk7258_ap_ipi_state_s *ipi = bk7258_ap_ipi_state();
1322	  volatile struct bk7258_cpu2_probe_state_s *cpu2 =
1323	    bk7258_cpu2_probe_state();
1324	  pthread_attr_t attr;
1325	  pthread_t thread;
1326	  cpu_set_t cpuset = (cpu_set_t)(1u << BK7258_AP_PRIMARY_CPU);
1327	  uint32_t elapsed;
1328	  int ret;
1329	
1330	  if (timeout_ms == 0)
1331	    {
1332	      timeout_ms = BK7258_AP_ADV_TIMEOUT_MS;
1333	    }
1334	
1335	  /* Validate N8-C4 prerequisites. */
1336	
1337	  if (smp->magic != BK7258_AP_SMP_STATE_MAGIC ||
1338	      smp->version != BK7258_AP_SMP_STATE_VERSION ||
1339	      smp->size != sizeof(struct bk7258_ap_smp_state_s) ||
1340	      smp->generation != bk7258_ap_boot_state()->generation ||
1341	      smp->state != BK7258_AP_SMP_STATE_PASSED ||
1342	      smp->error != BK7258_AP_SMP_ERROR_NONE ||
1343	      smp->online_mask != 0x3u ||
1344	      ipi->magic != BK7258_AP_IPI_STATE_MAGIC ||
1345	      ipi->version != BK7258_AP_IPI_STATE_VERSION ||
1346	      ipi->size != sizeof(struct bk7258_ap_ipi_state_s) ||
1347	      ipi->generation != bk7258_ap_boot_state()->generation ||
1348	      ipi->state != BK7258_AP_IPI_STATE_READY ||
1349	      ipi->error != BK7258_AP_IPI_ERROR_NONE ||
1350	      cpu2->state != BK7258_CPU2_PROBE_STATE_SCHEDULER_ONLINE ||
1351	      cpu2->online_mask != 0x3u)
1352	    {
1353	      return -EAGAIN;
1354	    }
1355	
1356	  /* Initialize shared state. */
1357	
1358	  memset((void *)(uintptr_t)state, 0, sizeof(*state));
1359	  state->version = BK7258_AP_BMIG_STATE_VERSION;
1360	  state->size = sizeof(*state);
1361	  state->generation = bk7258_ap_boot_state()->generation;
1362	  state->state = BK7258_AP_BMIG_STATE_INITIALIZING;
1363	  state->requested = BK7258_AP_ADV_CYCLES;
1364	  state->smp_tx0_before = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1365	  state->smp_rx1_before = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1366	  state->smp_tx1_before = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1367	  state->smp_rx0_before = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1368	  state->calls_before = cpu2->smp_call_requests;
1369	  __asm volatile ("dmb sy" ::: "memory");
1370	  state->magic = BK7258_AP_BMIG_STATE_MAGIC;
1371	  __asm volatile ("dmb sy" ::: "memory");
1372	
1373	  /* Create detached task with mask 0x1/CPU0. */
1374	
1375	  ret = pthread_attr_init(&attr);
1376	  if (ret != 0)
1377	    {
1378	      state->error = BK7258_AP_BMIG_ERROR_CREATE;
1379	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1380	      __asm volatile ("dmb sy; sev" ::: "memory");
1381	      return -ret;
1382	    }
1383	
1384	  (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
1385	  (void)pthread_attr_setaffinity_np(&attr, sizeof(cpuset), &cpuset);
1386	  state->state = BK7258_AP_BMIG_STATE_RUNNING;
1387	  __asm volatile ("dmb sy" ::: "memory");
1388	
1389	  ret = pthread_create(&thread, &attr, bmig_migration_task,
1390	                       (FAR void *)state);
1391	  (void)pthread_attr_destroy(&attr);
1392	  if (ret != 0)
1393	    {
1394	      state->error = BK7258_AP_BMIG_ERROR_CREATE;
1395	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1396	      __asm volatile ("dmb sy; sev" ::: "memory");
1397	      return -ret;
1398	    }
1399	
1400	  state->task_id[0] = (uint32_t)thread;
1401	  __asm volatile ("dmb sy" ::: "memory");
1402	
1403	  /* Wait for task to complete and PID to be released. */
1404	
1405	  for (elapsed = 0; elapsed < timeout_ms * 3; elapsed++)
1406	    {
1407	      __asm volatile ("dmb sy" ::: "memory");
1408	      if (state->task_completed[0] != 0)
1409	        {
1410	          if (bk7258_ap_bmig_pid_released(thread))
1411	            {
1412	              state->aux[0] = 1;
1413	              break;
1414	            }
1415	        }
1416	
1417	      if (state->state == BK7258_AP_BMIG_STATE_FAILED)
1418	        {
1419	          return -EIO;
1420	        }
1421	
1422	      /* The controller and migration task both start on CPU0. */
1423	
1424	      (void)nxsig_usleep(1000);
1425	    }
1426	
1427	  if (elapsed == timeout_ms * 3)
1428	    {
1429	      state->error = BK7258_AP_BMIG_ERROR_TIMEOUT;
1430	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1431	      __asm volatile ("dmb sy; sev" ::: "memory");
1432	      return -ETIMEDOUT;
1433	    }
1434	
1435	  /* Verify: tx/rx +4 each direction, calls +8. */
1436	
1437	  __asm volatile ("dmb sy" ::: "memory");
1438	  state->smp_tx0_after = smp->tx_count[BK7258_AP_PRIMARY_CPU];
1439	  state->smp_rx1_after = smp->rx_count[BK7258_AP_SECONDARY_CPU];
1440	  state->smp_tx1_after = smp->tx_count[BK7258_AP_SECONDARY_CPU];
1441	  state->smp_rx0_after = smp->rx_count[BK7258_AP_PRIMARY_CPU];
1442	  state->calls_after = cpu2->smp_call_requests;
1443	  __asm volatile ("dmb sy" ::: "memory");
1444	
1445	  if (state->state == BK7258_AP_BMIG_STATE_FAILED)
1446	    {
1447	      return -EIO;
1448	    }
1449	
1450	  if (state->smp_tx0_after != state->smp_tx0_before + 4 ||
1451	      state->smp_rx1_after != state->smp_rx1_before + 4 ||
1452	      state->smp_tx1_after != state->smp_tx1_before + 4 ||
1453	      state->smp_rx0_after != state->smp_rx0_before + 4 ||
1454	      state->calls_after != state->calls_before + 8)
1455	    {
1456	      state->error = BK7258_AP_BMIG_ERROR_COUNT_MISMATCH;
1457	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1458	      __asm volatile ("dmb sy; sev" ::: "memory");
1459	      return -EIO;
1460	    }
1461	
1462	  if (state->task_started[0] != 1 || state->task_completed[0] != 1 ||
1463	      state->sequence[0] != BK7258_AP_ADV_CYCLES)
1464	    {
1465	      state->error = BK7258_AP_BMIG_ERROR_COUNT_MISMATCH;
1466	      state->state = BK7258_AP_BMIG_STATE_FAILED;
1467	      __asm volatile ("dmb sy; sev" ::: "memory");
1468	      return -EIO;
1469	    }
1470	
1471	  state->completed = BK7258_AP_ADV_CYCLES;
1472	  state->error = BK7258_AP_BMIG_ERROR_NONE;
1473	  __asm volatile ("dmb sy" ::: "memory");
1474	  state->state = BK7258_AP_BMIG_STATE_PASSED;
1475	  __asm volatile ("dmb sy; sev" ::: "memory");
1476	  return OK;
1477	}
