1487	static FAR void *btim_timed_task(FAR void *arg)
1488	{
1489	  volatile struct bk7258_ap_advanced_state_s *state = arg;
1490	  uint32_t cycle;
1491	  int ret;
1492	
1493	  if (state == NULL)
1494	    {
1495	      return NULL;
1496	    }
1497	
1498	  state->task_id[0] = (uint32_t)pthread_self();
1499	  state->task_cpu[0] = (uint32_t)up_cpu_index();
1500	  state->task_started[0]++;
1501	  __asm volatile ("dmb sy" ::: "memory");
1502	
1503	  for (cycle = 1; cycle <= BK7258_AP_ADV_CYCLES; cycle++)
1504	    {
1505	      state->value[0] = (int32_t)cycle;
1506	      __asm volatile ("dmb sy" ::: "memory");
1507	
1508	      ret = nxsig_usleep(BK7258_AP_ADV_TIMED_INTERVAL_US);
1509	      __asm volatile ("dmb sy" ::: "memory");
1510	
1511	      state->value[1] = (int32_t)ret;
1512	      state->sequence[0] = cycle;
1513	
1514	      if (ret < 0)
1515	        {
1516	          state->error = BK7258_AP_BTIM_ERROR_SLEEP;
1517	          state->state = BK7258_AP_BTIM_STATE_FAILED;
1518	          __asm volatile ("dmb sy; sev" ::: "memory");
1519	          goto done;
1520	        }
1521	
1522	      if (up_cpu_index() != BK7258_AP_SECONDARY_CPU)
1523	        {
1524	          state->error = BK7258_AP_BTIM_ERROR_BAD_CPU;
1525	          state->state = BK7258_AP_BTIM_STATE_FAILED;
1526	          __asm volatile ("dmb sy; sev" ::: "memory");
1527	          goto done;
1528	        }
1529	
1530	      __asm volatile ("dmb sy; sev" ::: "memory");
1531	    }
1532	
1533	done:
1534	  state->task_completed[0]++;
1535	  __asm volatile ("dmb sy; sev" ::: "memory");
1536	  return NULL;
1537	}
