static FAR void *bmig_migration_task(FAR void *arg)
{
  volatile struct bk7258_ap_advanced_state_s *state = arg;
  cpu_set_t target;
  cpu_set_t observed;
  uint32_t cycle;
  int ret;

  if (state == NULL)
    {
      return NULL;
    }

  state->task_id[0] = (uint32_t)pthread_self();
  state->task_cpu[0] = (uint32_t)up_cpu_index();
  state->task_started[0]++;
  __asm volatile ("dmb sy" ::: "memory");

  for (cycle = 1; cycle <= BK7258_AP_ADV_CYCLES; cycle++)
    {
      /* Odd transitions target 0x2/CPU1, even target 0x1/CPU0. */

      if ((cycle & 1u) != 0)
        {
          target = (cpu_set_t)(1u << BK7258_AP_SECONDARY_CPU);
        }
      else
        {
          target = (cpu_set_t)(1u << BK7258_AP_PRIMARY_CPU);
        }

      ret = pthread_setaffinity_np(pthread_self(), sizeof(target), &target);
      if (ret != 0)
        {
          state->error = BK7258_AP_BMIG_ERROR_SETAFFINITY;
          state->state = BK7258_AP_BMIG_STATE_FAILED;
          __asm volatile ("dmb sy; sev" ::: "memory");
          goto done;
        }

      /* Updating a running task's own affinity does not guarantee that the
       * call returns on the target CPU.  Yield after excluding the current
       * CPU so the scheduler performs the controlled handoff before the
       * affinity and CPU observations below.
       */

      ret = sched_yield();
      if (ret != 0)
        {
          state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
          state->state = BK7258_AP_BMIG_STATE_FAILED;
          __asm volatile ("dmb sy; sev" ::: "memory");
          goto done;
        }

      /* Verify affinity and CPU. */

      observed = 0;
      ret = pthread_getaffinity_np(pthread_self(), sizeof(observed),
                                   &observed);
      if (ret != 0)
        {
          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
          state->state = BK7258_AP_BMIG_STATE_FAILED;
          __asm volatile ("dmb sy; sev" ::: "memory");
          goto done;
        }

      if (observed != target)
        {
          state->error = BK7258_AP_BMIG_ERROR_GETAFFINITY;
          state->state = BK7258_AP_BMIG_STATE_FAILED;
          __asm volatile ("dmb sy; sev" ::: "memory");
          goto done;
        }

      if ((target & (1u << BK7258_AP_SECONDARY_CPU)) != 0)
        {
          if (up_cpu_index() != BK7258_AP_SECONDARY_CPU)
            {
              state->error = BK7258_AP_BMIG_ERROR_BAD_CPU;
              state->state = BK7258_AP_BMIG_STATE_FAILED;
              __asm volatile ("dmb sy; sev" ::: "memory");
              goto done;
            }
        }
