  volatile struct bk7258_ap_advanced_state_s *state;
  FAR struct tcb_s *tcb;
  irqstate_t flags;
  uint32_t cycle;
  uint32_t elapsed;
  int blocked = 0;
  int value = 0;
  int ret;

