    {
      return -EINVAL;
    }

  state = rendezvous->state;
  cycle = rendezvous->cycle;
  if (cycle == 0 || up_cpu_index() != rendezvous->target)
    {
      return bmig_callback_fail(rendezvous,
                                BK7258_AP_BMIG_ERROR_BAD_CPU, -EIO);
